def _fail(message: str) -> NoReturn:
    raise LedgerError(message)


def _git_environment() -> dict[str, str]:
    environment = os.environ.copy()
    exact = {
        "GIT_ALTERNATE_OBJECT_DIRECTORIES",
        "GIT_CEILING_DIRECTORIES",
        "GIT_COMMON_DIR",
        "GIT_CONFIG",
        "GIT_CONFIG_COUNT",
        "GIT_CONFIG_GLOBAL",
        "GIT_CONFIG_PARAMETERS",
        "GIT_CONFIG_SYSTEM",
        "GIT_DIR",
        "GIT_INDEX_FILE",
        "GIT_OBJECT_DIRECTORY",
        "GIT_REPLACE_REF_BASE",
        "GIT_WORK_TREE",
    }
    for key in list(environment):
        if key in exact or key.startswith(("GIT_CONFIG_KEY_", "GIT_CONFIG_VALUE_")):
            environment.pop(key, None)
    environment.update(
        {
            "GIT_CONFIG_GLOBAL": os.devnull,
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_CONFIG_SYSTEM": os.devnull,
            "GIT_OPTIONAL_LOCKS": "0",
        }
    )
    return environment


def _run_git(repository_root: Path, arguments: list[str], path: str) -> str:
    if GIT is None:
        _fail(f"{path} cannot resolve Git objects because git is unavailable")
    try:
        result = subprocess.run(  # noqa: S603
            [GIT, "--no-replace-objects", *arguments],
            cwd=repository_root,
            env=_git_environment(),
            check=False,
            capture_output=True,
            timeout=10,
            text=True,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        _fail(f"{path} cannot resolve Git objects: {error}")
    if result.returncode != 0:
        detail = result.stderr.strip() or "git command failed"
        _fail(f"{path} cannot resolve Git objects: {detail}")
    return result.stdout.strip()


def _run_git_bytes(repository_root: Path, arguments: list[str], path: str) -> bytes:
    if GIT is None:
        _fail(f"{path} cannot resolve Git objects because git is unavailable")
    try:
        result = subprocess.run(  # noqa: S603
            [GIT, "--no-replace-objects", *arguments],
            cwd=repository_root,
            env=_git_environment(),
            check=False,
            capture_output=True,
            timeout=10,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        _fail(f"{path} cannot resolve Git objects: {error}")
    if result.returncode != 0:
        detail = result.stderr.decode("utf-8", errors="replace").strip()
        _fail(f"{path} cannot resolve Git objects: {detail or 'git command failed'}")
    return result.stdout


def _run_git_exact_line(repository_root: Path, arguments: list[str], path: str) -> str:
    """Return one exact Git output line without normalizing its content."""

    payload = _run_git_bytes(repository_root, arguments, path)
    if payload.count(b"\n") != 1 or not payload.endswith(b"\n") or b"\r" in payload:
        _fail(f"{path} did not return one exact LF-terminated line")
    try:
        value = payload[:-1].decode("utf-8")
    except UnicodeDecodeError:
        _fail(f"{path} did not return one exact UTF-8 line")
    if (
        not value
        or value != value.strip()
        or any(ord(character) < 0x20 or ord(character) == 0x7F for character in value)
    ):
        _fail(f"{path} did not return one exact whitespace-free line")
    return value


def _authorized_origin_repository(
    repository_root: Path,
    path: str,
    *,
    repository_name: str,
) -> str:
    """Bind one unambiguous effective fetch and push destination for origin."""

    fetch_url = _run_git_exact_line(
        repository_root,
        ["remote", "get-url", "--all", "origin"],
        f"{path} fetch URL",
    )
    push_url = _run_git_exact_line(
        repository_root,
        ["remote", "get-url", "--push", "--all", "origin"],
        f"{path} push URL",
    )
    fetch_repository = _validate_authorized_github_remote(
        fetch_url,
        f"{path} fetch URL",
        repository_name=repository_name,
    )
    push_repository = _validate_authorized_github_remote(
        push_url,
        f"{path} push URL",
        repository_name=repository_name,
    )
    if fetch_repository != push_repository:
        _fail(f"{path} fetch and push destinations differ")
    return fetch_repository


@lru_cache(maxsize=512)
def _resolved_git_tree(repository_root: str, commit: str) -> str:
    root = Path(repository_root)
    object_type = _run_git(root, ["cat-file", "-t", commit], "receipt.source_commit")
    if object_type != "commit":
        _fail("receipt.source_commit does not identify a Git commit object")
    tree = _run_git(
        root,
        ["rev-parse", "--verify", f"{commit}^{{tree}}"],
        "receipt.source_tree",
    )
    if not HEX40.fullmatch(tree):
        _fail("receipt.source_commit resolved an invalid Git tree")
    return tree


def _validate_git_commit_tree(
    repository: str, commit: str, tree: str, path: str
) -> None:
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY.get(repository)
    if repository_root is None:
        _fail(f"{path}.repository has no configured local Git object authority")
    resolved = _resolved_git_tree(str(repository_root), commit)
    if resolved != tree:
        _fail(f"{path}.source_tree differs from source_commit^{{tree}}")


@lru_cache(maxsize=1024)
def _resolved_git_blob(
    repository_root: str, commit: str, relative_path: str
) -> tuple[str, bytes]:
    """Resolve one path from an immutable Git tree without consulting the worktree."""
    root = Path(repository_root)
    listing = _run_git_bytes(
        root,
        ["ls-tree", "-z", commit, "--", relative_path],
        f"committed subject {relative_path}",
    )
    records = [record for record in listing.split(b"\0") if record]
    if len(records) != 1 or b"\t" not in records[0]:
        _fail(f"committed subject {relative_path} is absent or ambiguous")
    metadata, encoded_path = records[0].split(b"\t", 1)
    try:
        mode, object_type, object_id = metadata.decode("ascii").split(" ")
    except (UnicodeDecodeError, ValueError) as error:
        _fail(f"committed subject {relative_path} has invalid Git metadata: {error}")
    if encoded_path != relative_path.encode("utf-8"):
        _fail(f"committed subject {relative_path} resolved a different path")
    if mode not in {"100644", "100755"} or object_type != "blob":
        _fail(f"committed subject {relative_path} is not a regular Git blob")
    size_text = _run_git(
        root,
        ["cat-file", "-s", object_id],
        f"committed subject size {relative_path}",
    )
    try:
        byte_count = int(size_text)
    except ValueError:
        _fail(f"committed subject {relative_path} has an invalid byte size")
    if not 1 <= byte_count <= MAX_EVIDENCE_FILE_BYTES:
        _fail(f"committed subject {relative_path} exceeds the file-size bound")
    content = _run_git_bytes(
        root,
        ["cat-file", "blob", object_id],
        f"committed subject bytes {relative_path}",
    )
    if len(content) != byte_count:
        _fail(f"committed subject {relative_path} changed while it was resolved")
    return object_id, content


def _resolved_git_blob_identity(
    repository_root: str, commit: str, relative_path: str
) -> tuple[str, int]:
    _, content = _resolved_git_blob(repository_root, commit, relative_path)
    return hashlib.sha256(content).hexdigest(), len(content)


def _require_committed_file(
    receipt: dict[str, Any],
    relative_path: str,
    expected_sha256: str,
    expected_bytes: int,
    label: str,
    *,
    cut: str = "source",
) -> None:
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[receipt["repository"]]
    commit_field = f"{cut}_commit"
    if commit_field not in receipt:
        _fail(f"{label} has no declared {cut} commit")
    digest, byte_count = _resolved_git_blob_identity(
        str(repository_root), receipt[commit_field], relative_path
    )
    if digest != expected_sha256 or byte_count != expected_bytes:
        _fail(f"{label} differs from the exact blob in the receipt {cut} commit")


def _receipt_artifact_bytes(
    receipt: dict[str, Any],
    relative_path: str,
    label: str,
) -> bytes:
    """Return the already content-addressed artifact from the receipt evidence cut."""
    matching = [
        artifact
        for artifact in receipt["artifacts"]
        if artifact["path"] == relative_path
    ]
    if len(matching) != 1:
        _fail(f"{label} is not uniquely bound by the receipt")
    artifact = matching[0]
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[receipt["repository"]]
    _, content = _resolved_git_blob(
        str(repository_root),
        receipt["evidence_commit"],
        relative_path,
    )
    if (
        len(content) != artifact["bytes"]
        or hashlib.sha256(content).hexdigest() != artifact["sha256"]
    ):
        _fail(f"{label} differs from the receipt evidence-cut artifact identity")
    return content


def _receipt_source_bytes(
    receipt: dict[str, Any],
    relative_path: str,
    label: str,
) -> bytes:
    """Return one immutable source input from the declared tested Git cut."""
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[receipt["repository"]]
    _, content = _resolved_git_blob(
        str(repository_root),
        receipt["source_commit"],
        relative_path,
    )
    if not content:
        _fail(f"{label} must not be empty")
    return content


def _require_strict_git_ancestor(
    repository: str, ancestor: str, descendant: str, label: str
) -> None:
    if ancestor == descendant:
        _fail(f"{label} must be a strict ancestor, not the same commit")
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[repository]
    if GIT is None:
        _fail(f"{label} cannot run because git is unavailable")
    try:
        result = subprocess.run(  # noqa: S603
            [
                GIT,
                "--no-replace-objects",
                "merge-base",
                "--is-ancestor",
                ancestor,
                descendant,
            ],
            cwd=repository_root,
            env=_git_environment(),
            check=False,
            capture_output=True,
            timeout=10,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        _fail(f"{label} cannot verify Git ancestry: {error}")
    if result.returncode == 1:
        _fail(f"{label} is not an ancestor of the required local evidence cut")
    if result.returncode != 0:
        detail = result.stderr.decode("utf-8", errors="replace").strip()
        _fail(f"{label} cannot verify Git ancestry: {detail or 'git failed'}")


def _require_git_ancestor_or_equal(
    repository: str, ancestor: str, descendant: str, label: str
) -> None:
    if ancestor == descendant:
        return
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[repository]
    if GIT is None:
        _fail(f"{label} cannot run because git is unavailable")
    try:
        result = subprocess.run(  # noqa: S603
            [
                GIT,
                "--no-replace-objects",
                "merge-base",
                "--is-ancestor",
                ancestor,
                descendant,
            ],
            cwd=repository_root,
            env=_git_environment(),
            check=False,
            capture_output=True,
            timeout=10,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        _fail(f"{label} cannot verify Git ancestry: {error}")
    if result.returncode == 1:
        _fail(f"{label} is not an ancestor of the required Git cut")
    if result.returncode != 0:
        detail = result.stderr.decode("utf-8", errors="replace").strip()
        _fail(f"{label} cannot verify Git ancestry: {detail or 'git failed'}")


def _validate_evidence_cut(receipt: dict[str, Any], path: str) -> None:
    """Bind two immutable local Git cuts without claiming remote reachability."""
    repository = receipt["repository"]
    evidence_commit = _hex(receipt["evidence_commit"], HEX40, f"{path}.evidence_commit")
    evidence_tree = _hex(receipt["evidence_tree"], HEX40, f"{path}.evidence_tree")
    _validate_git_commit_tree(repository, evidence_commit, evidence_tree, path)
    _require_strict_git_ancestor(
        repository,
        receipt["source_commit"],
        evidence_commit,
        f"{path}.source/evidence cuts",
    )


def _require_current_file_at_receipt_commit(
    receipt: dict[str, Any], path: Path, label: str
) -> None:
    try:
        relative = path.relative_to(ROOT).as_posix()
    except ValueError:
        _fail(f"{label} is outside the repository")
    current = ROOT
    for component in PurePosixPath(relative).parts:
        current /= component
        if current.is_symlink():
            _fail(f"{label} traverses a symlink")
    if not path.is_file():
        _fail(f"{label} must be a regular non-symlink file")
    _require_committed_file(
        receipt,
        relative,
        _file_sha256(path),
        path.stat().st_size,
        label,
    )


def _require_receipt_artifact_at_evidence_commit(
    receipt: dict[str, Any], relative_path: str, label: str
) -> None:
    matching = [
        artifact
        for artifact in receipt["artifacts"]
        if artifact["path"] == relative_path
    ]
    if len(matching) != 1:
        _fail(f"{label} is not uniquely bound by the passing receipt")
    artifact = matching[0]
    _require_committed_file(
        receipt,
        relative_path,
        artifact["sha256"],
        artifact["bytes"],
        label,
        cut="evidence",
    )


def _canonical_sha256(value: Any) -> str:
    payload = json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":")
    ).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _load_bounded_json_bytes(raw: bytes, label: str) -> dict[str, Any]:
    try:
        value = parse_json_bytes(
            raw,
            limits=TASK_SUBJECT_JSON_LIMITS,
            label=label,
        )
    except BoundedJsonError as error:
        _fail(str(error))
    if not isinstance(value, dict):
        _fail(f"{label} must contain one JSON object")
    _walk_limits(value)
    return value


def _load_bounded_json_file(path: Path, label: str) -> dict[str, Any]:
    """Load a maintained worktree file when the file itself is the checked input.

    Receipt artifacts must use `_receipt_artifact_bytes` and
    `_load_bounded_json_bytes`; a mutable worktree path is never receipt authority.
    """
    try:
        raw = read_bounded_regular_file(
            path,
            limits=TASK_SUBJECT_FILE_LIMITS,
            label=label,
        )
    except BoundedJsonError as error:
        _fail(str(error))
    return _load_bounded_json_bytes(raw, label)


def _load_bounded_json_from_git(
    repository: str,
    commit: str,
    relative_path: str,
    label: str,
) -> tuple[dict[str, Any], str, int]:
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[repository]
    _, raw = _resolved_git_blob(str(repository_root), commit, relative_path)
    return (
        _load_bounded_json_bytes(raw, label),
        hashlib.sha256(raw).hexdigest(),
        len(raw),
    )


def _parse_adr008_illustrative_json(raw: bytes) -> dict[str, Any]:
    """Parse ADR-008's one exact illustrative JSON fence."""
    if not 1 <= len(raw) <= MAX_TASK_SUBJECT_JSON_BYTES:
        _fail("ADR-008 exceeds the bounded source size")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        _fail(f"ADR-008 is not valid UTF-8: {error}")
    if "\r" in text:
        _fail("ADR-008 must use canonical LF line endings")
    heading = "## Illustrative extension envelope"
    heading_marker = f"\n{heading}\n"
    if text.count(heading_marker) != 1:
        _fail("ADR-008 must contain one exact illustrative extension-envelope heading")
    section = text.split(heading_marker, 1)[1]
    next_heading = section.find("\n## ")
    if next_heading >= 0:
        section = section[:next_heading]
    fences = re.findall(r"(?ms)^```json\n(.*?)^```[ \t]*$", section)
    if len(fences) != 1:
        _fail("ADR-008 illustrative section must contain one exact JSON fence")
    encoded = fences[0].encode("utf-8")
    if not 1 <= len(encoded) <= MAX_TASK_SUBJECT_JSON_BYTES:
        _fail("ADR-008 illustrative JSON exceeds the bounded size")
    try:
        value = parse_json_bytes(
            encoded,
            limits=TASK_SUBJECT_JSON_LIMITS,
            label="ADR-008 illustrative JSON",
        )
    except BoundedJsonError as error:
        _fail(f"ADR-008 illustrative JSON is invalid: {error}")
    if not isinstance(value, dict):
        _fail("ADR-008 illustrative JSON must contain one object")
    return value


def _validate_adr008_attachment_reference(value: Any, path: str) -> str:
    """Validate one exact protected-attachment reference in ADR-008."""
    if not isinstance(value, dict):
        _fail(f"{path} must be one protected-attachment reference object")
    _exact_keys(
        value,
        {"attachment_id", "digest", "byte_length", "media_type"},
        path,
    )
    attachment_id = _string(
        value["attachment_id"], f"{path}.attachment_id", maximum=256
    )
    if not attachment_id.isascii() or any(
        not 0x21 <= ord(character) <= 0x7E for character in attachment_id
    ):
        _fail(f"{path}.attachment_id must use bounded printable non-space ASCII")
    digest = _string(value["digest"], f"{path}.digest", maximum=71)
    if not SHA256_REFERENCE.fullmatch(digest):
        _fail(
            f"{path}.digest must contain sha256: followed by exactly "
            "64 lowercase hexadecimal characters"
        )
    byte_length = _integer(value["byte_length"], f"{path}.byte_length", minimum=1)
    if byte_length > MAX_EVIDENCE_REFERENCED_BYTES:
        _fail(f"{path}.byte_length exceeds the protected-attachment bound")
    media_type = _string(value["media_type"], f"{path}.media_type", maximum=128)
    if not MEDIA_TYPE.fullmatch(media_type):
        _fail(f"{path}.media_type must be a bounded lowercase media type")
    return attachment_id


def _validate_adr008_required_attachment_topology(value: Any) -> None:
    if not isinstance(value, dict):
        _fail("ADR-008 illustrative JSON must contain one object")
    lifecycle = value.get("lifecycle_outcome_evidence")
    if not isinstance(lifecycle, dict):
        _fail("ADR-008 illustrative JSON must contain lifecycle_outcome_evidence")
    if "ncp_source_authority_bundle_attachment" not in lifecycle:
        _fail(
            "ADR-008 illustrative lifecycle evidence requires "
            "ncp_source_authority_bundle_attachment"
        )
    assessments = lifecycle.get("assessments")
    if not isinstance(assessments, list) or not assessments:
        _fail("ADR-008 illustrative lifecycle evidence requires assessments")
    for index, assessment in enumerate(assessments):
        path = f"ADR-008.lifecycle_outcome_evidence.assessments[{index}]"
        if not isinstance(assessment, dict):
            _fail(f"{path} must be an object")
        if "adapter_scope_mapping_receipt_attachment" not in assessment:
            _fail(f"{path} requires adapter_scope_mapping_receipt_attachment")
        captures = assessment.get("source_capture_attachments")
        if not isinstance(captures, list) or not captures:
            _fail(f"{path} requires nonempty source_capture_attachments")


def _reject_adr008_digest_only_source_evidence(key: str, child: Any, path: str) -> None:
    semantic_key = key.casefold().replace("-", "_")
    digest_only_value = (isinstance(child, str) and "sha256:" in child.casefold()) or (
        isinstance(child, list)
        and bool(child)
        and all(
            isinstance(member, str) and "sha256:" in member.casefold()
            for member in child
        )
    )
    source_evidence_field = any(
        concept in semantic_key
        for concept in ("source_authority", "mapping_receipt", "source_capture")
    )
    digest_field = semantic_key.endswith(("_digest", "_digests", "_sha256", "_hash"))
    if source_evidence_field and (digest_field or digest_only_value):
        _fail(f"{path} is a forbidden digest-only source-evidence field")


def _register_adr008_attachment(
    value: Any, path: str, attachment_ids: set[str]
) -> None:
    attachment_id = _validate_adr008_attachment_reference(value, path)
    if attachment_id in attachment_ids:
        _fail("ADR-008 illustrative protected attachment IDs must be unique")
    attachment_ids.add(attachment_id)


def _queue_adr008_mapping_child(
    key: str,
    child: Any,
    child_path: str,
    attachment_ids: set[str],
    pending: list[tuple[Any, str]],
) -> None:
    _reject_adr008_digest_only_source_evidence(key, child, child_path)
    if key.endswith("_attachment"):
        _register_adr008_attachment(child, child_path, attachment_ids)
        pending.append((child, child_path))
        return
    if key.endswith("_attachments"):
        if not isinstance(child, list) or not child:
            _fail(f"{child_path} must be a nonempty attachment list")
        for index, attachment in enumerate(child):
            path = f"{child_path}[{index}]"
            _register_adr008_attachment(attachment, path, attachment_ids)
            pending.append((attachment, path))
        return
    pending.append((child, child_path))


def _validate_adr008_illustrative_value(value: Any) -> int:
    """Validate ADR-008's required attachment topology and digest references."""
    _validate_adr008_required_attachment_topology(value)
    references = 0
    attachment_ids: set[str] = set()
    pending: list[tuple[Any, str]] = [(value, "ADR-008")]
    while pending:
        current, path = pending.pop()
        if isinstance(current, dict):
            for key, child in current.items():
                child_path = f"{path}.{key}"
                _queue_adr008_mapping_child(
                    key,
                    child,
                    child_path,
                    attachment_ids,
                    pending,
                )
        elif isinstance(current, list):
            pending.extend(
                (child, f"{path}[{index}]") for index, child in enumerate(current)
            )
        elif isinstance(current, str) and "sha256:" in current.casefold():
            references += 1
            if not SHA256_REFERENCE.fullmatch(current):
                _fail(
                    "ADR-008 illustrative sha256 reference must contain exactly "
                    "64 lowercase hexadecimal characters"
                )
    if references == 0:
        _fail("ADR-008 illustrative JSON must retain at least one sha256 reference")
    return references


def _validate_adr008_illustrative_json(raw: bytes) -> int:
    """Parse and validate ADR-008's exact illustrative JSON fence."""
    return _validate_adr008_illustrative_value(_parse_adr008_illustrative_json(raw))


def _validate_identity_uri(value: Any, path: str) -> str:
    identity = _string(value, path, maximum=512)
    if not identity.isascii() or not IDENTITY_URI.fullmatch(identity):
        _fail(f"{path} must be a stable ASCII issuer-and-subject URI")
    return identity


def _validate_https_url(value: Any, path: str) -> str:
    url = _string(value, path, maximum=2048)
    if not url.isascii() or any(
        not 0x21 <= ord(character) <= 0x7E for character in url
    ):
        _fail(f"{path} must use printable non-space ASCII")
    parsed = urlsplit(url)
    if (
        parsed.scheme != "https"
        or not parsed.hostname
        or parsed.username is not None
        or parsed.password is not None
        or parsed.query
        or parsed.fragment
    ):
        _fail(
            f"{path} must be an absolute credential-free HTTPS URL without "
            "query or fragment"
        )
    try:
        port = parsed.port
        host = parsed.hostname.lower()
        host.encode("ascii")
    except (UnicodeError, ValueError) as error:
        _fail(f"{path} has an invalid host or port: {error}")
    try:
        ipaddress.ip_address(host)
    except ValueError:
        pass
    else:
        _fail(f"{path} cannot use an IP-literal receipt host")
    labels = host.split(".")
    if (
        port not in {None, 443}
        or parsed.hostname != host
        or host == "localhost"
        or host.endswith(".localhost")
        or host.endswith(".local")
        or len(host) > 253
        or len(labels) < 2
        or any(not DNS_LABEL.fullmatch(label) for label in labels)
        or labels[-1].isdigit()
        or not parsed.path.startswith("/")
        or parsed.path == "/"
    ):
        _fail(f"{path} must identify one resource on a public HTTPS host")
    return url


def _validate_authorized_github_remote(
    value: Any, path: str, *, repository_name: str
) -> str:
    """Validate one GitHub remote and return its canonical owner/repository."""

    remote = _string(value, path, maximum=256)
    if remote.startswith("git@github.com:"):
        repository = remote.removeprefix("git@github.com:")
    elif remote.startswith("https://github.com/"):
        repository = remote.removeprefix("https://github.com/")
    else:
        _fail(f"{path} must use the authorized GitHub SSH or HTTPS origin form")
    if repository.endswith(".git"):
        repository = repository[:-4]
    expected = AUTHORIZED_GITHUB_REPOSITORY_BY_NAME.get(repository_name)
    if expected is None:
        _fail(f"{path} has no checked repository authorization")
    if repository != expected:
        _fail(f"{path} does not identify the authorized GitHub repository {expected}")
    return repository


def _validate_branch_name(value: Any, path: str) -> str:
    branch = _string(value, path, maximum=128)
    if (
        branch.startswith("-")
        or branch in {"@", "HEAD"}
        or branch.startswith("refs/")
        or "@{" in branch
        or any(character in branch for character in "~^:?*[\\")
        or ".." in branch
    ):
        _fail(f"{path} is not an unambiguous Git branch name")
    if GIT is None:
        _fail(f"{path} cannot run git check-ref-format")
    try:
        result = subprocess.run(  # noqa: S603
            [GIT, "check-ref-format", "--branch", branch],
            cwd=ROOT,
            env=_git_environment(),
            check=False,
            capture_output=True,
            timeout=10,
            text=True,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        _fail(f"{path} cannot run git check-ref-format: {error}")
    if result.returncode != 0 or result.stdout.strip() != branch:
        _fail(f"{path} fails git check-ref-format --branch")
    return branch


def _exact_keys(value: dict[str, Any], expected: set[str], path: str) -> None:
    actual = set(value)
    if actual != expected:
        _fail(
            f"{path} keys differ: missing={sorted(expected - actual)} extra={sorted(actual - expected)}"
        )


def _string(
    value: Any, path: str, *, maximum: int = 4096, nonempty: bool = True
) -> str:
    if not isinstance(value, str):
        _fail(f"{path} must be a string")
    if nonempty and not value.strip():
        _fail(f"{path} must be nonempty")
    if "\x00" in value:
        _fail(f"{path} contains NUL")
    if len(value.encode("utf-8")) > maximum:
        _fail(f"{path} exceeds {maximum} UTF-8 bytes")
    return value


def _relative_path(value: Any, path: str) -> str:
    text = _string(value, path, maximum=512)
    if (
        not RELATIVE_PATH.fullmatch(text)
        or text == "."
        or "\\" in text
        or any(ord(character) < 0x20 for character in text)
        or PurePosixPath(text).as_posix() != text
    ):
        _fail(f"{path} must be a bounded repository-relative path")
    return text


def _hex(value: Any, pattern: re.Pattern[str], path: str) -> str:
    text = _string(value, path, maximum=64)
    if not pattern.fullmatch(text):
        _fail(f"{path} has an invalid immutable digest or commit")
    return text


def _integer(value: Any, path: str, *, minimum: int | None = None) -> int:
    if type(value) is not int:
        _fail(f"{path} must be an integer")
    if minimum is not None and value < minimum:
        _fail(f"{path} must be at least {minimum}")
    return value


def _walk_limits(value: Any, *, depth: int = 0, nodes: list[int] | None = None) -> None:
    if nodes is None:
        nodes = [0]
    nodes[0] += 1
    if nodes[0] > 100_000:
        _fail("ledger exceeds the aggregate node limit")
    if depth > 32:
        _fail("ledger exceeds the nesting-depth limit")
    if isinstance(value, dict):
        if len(value) > 256:
            _fail("ledger object exceeds 256 members")
        for key, child in value.items():
            _string(key, "object key", maximum=128)
            _walk_limits(child, depth=depth + 1, nodes=nodes)
    elif isinstance(value, list):
        if len(value) > 4096:
            _fail("ledger array exceeds 4096 items")
        for child in value:
            _walk_limits(child, depth=depth + 1, nodes=nodes)
    elif isinstance(value, str):
        _string(value, "string value", maximum=4096, nonempty=False)
    elif value is not None and not isinstance(value, (bool, int)):
        _fail(
            "ledger supports only JSON null, boolean, integer, string, array, and object values"
        )


def _scan_sensitive(value: Any, path: str = "$") -> None:
    if isinstance(value, str):
        if SECRET.search(value):
            _fail(f"{path} appears to contain a credential or private key")
        if ABSOLUTE_LOCAL_PATH.search(value) or _receipt_line_contains_host_path(value):
            _fail(f"{path} contains an absolute local path")
    elif isinstance(value, list):
        for index, child in enumerate(value):
            _scan_sensitive(child, f"{path}[{index}]")
    elif isinstance(value, dict):
        for key, child in value.items():
            _scan_sensitive(key, f"{path}.<key>")
            _scan_sensitive(child, f"{path}.{key}")


def _bounded_zlib_decode(content: bytes, *, wbits: int, label: str) -> bytes:
    """Decode one exact compressed stream without an allocation bomb or trailing data."""
    decoder = zlib.decompressobj(wbits)
    try:
        decoded = decoder.decompress(
            content,
            MAX_RECEIPT_ARTIFACT_DECODED_BYTES + 1,
        )
        if len(decoded) > MAX_RECEIPT_ARTIFACT_DECODED_BYTES or decoder.unconsumed_tail:
            _fail(f"{label} exceeds the decoded receipt-artifact byte bound")
        decoded += decoder.flush(MAX_RECEIPT_ARTIFACT_DECODED_BYTES + 1 - len(decoded))
    except zlib.error as error:
        _fail(f"{label} is not an exact supported compressed stream: {error}")
    if len(decoded) > MAX_RECEIPT_ARTIFACT_DECODED_BYTES:
        _fail(f"{label} exceeds the decoded receipt-artifact byte bound")
    if not decoder.eof or decoder.unused_data or decoder.unconsumed_tail:
        _fail(f"{label} has a truncated, concatenated, or trailing compressed stream")
    return decoded


def _gzip_header_text_views(content: bytes, label: str) -> list[tuple[str, str]]:
    """Require the no-option gzip profile used by portable receipt artifacts."""
    if len(content) < 18 or content[:2] != GZIP_MAGIC or content[2] != 8:
        _fail(f"{label} is not a canonical deflate gzip stream")
    flags = content[3]
    if flags != 0:
        _fail(f"{label} uses unsupported optional or reserved gzip header fields")
    if len(content) <= 18:
        _fail(f"{label} has no bounded gzip payload")
    return []


def _validate_receipt_text_controls(text: str, label: str) -> None:
    if RECEIPT_ARTIFACT_FORBIDDEN_CONTROL.search(text):
        _fail(f"{label} contains a forbidden textual control character")
    if not text.isascii():
        for character in text:
            if unicodedata.category(character) in {"Cf", "Cs"}:
                _fail(f"{label} contains a forbidden Unicode format or surrogate code")


def _decode_receipt_artifact_utf8(content: bytes, label: str) -> str:
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError as error:
        _fail(f"{label} is neither supported PNG nor strict UTF-8 text: {error}")
    _validate_receipt_text_controls(text, label)
    return text


def _receipt_json_scalar_views(
    relative_path: str,
    content: bytes,
    label: str,
) -> list[tuple[str, str]] | None:
    normalized_path = relative_path.lower()
    is_json = normalized_path.endswith((".json", ".json.gz"))
    is_jsonl = normalized_path.endswith((".jsonl", ".jsonl.gz"))
    views: list[tuple[str, str]] = []
    scalar_index = 0
    nested_json_bytes = 0
    json_node_count = 0

    def is_json_candidate(record: bytes) -> bool:
        stripped = record.lstrip()
        return bool(
            stripped
            and (
                stripped.startswith((b"{", b"[", b'"', b"-", b"t", b"f", b"n"))
                or stripped[0] in b"0123456789"
            )
        )

    def reject_opportunistic_error(error: BoundedJsonError) -> None:
        message = str(error)
        if any(
            marker in message
            for marker in (
                "duplicate JSON object key",
                "exceeds",
                "nesting",
                "non-finite",
            )
        ):
            _fail(message)

    def visit(value: Any, document_index: int, nested_depth: int) -> None:
        nonlocal json_node_count, nested_json_bytes, scalar_index
        json_node_count += 1
        if json_node_count > RECEIPT_ARTIFACT_JSON_LIMITS.maximum_items:
            _fail(f"{label} exceeds the aggregate decoded JSON node bound")
        if isinstance(value, str):
            _validate_receipt_text_controls(
                value,
                f"{label} decoded JSON scalar {scalar_index}",
            )
            views.append(
                (
                    f"{label} decoded JSON scalar {scalar_index}",
                    value,
                )
            )
            scalar_index += 1
            encoded_value = value.encode()
            if not is_json_candidate(encoded_value):
                return
            nested_json_bytes += len(encoded_value)
            if nested_json_bytes > MAX_RECEIPT_ARTIFACT_DECODED_BYTES:
                _fail(f"{label} exceeds the nested JSON byte budget")

            def visit_embedded(embedded: Any, embedded_index: int) -> None:
                if nested_depth >= MAX_RECEIPT_NESTED_JSON_DEPTH:
                    _fail(f"{label} exceeds the nested JSON depth bound")
                visit(embedded, embedded_index, nested_depth + 1)

            try:
                embedded = parse_json_bytes(
                    encoded_value,
                    limits=RECEIPT_ARTIFACT_JSON_LIMITS,
                    label=(
                        f"{label} decoded JSON scalar {scalar_index - 1} "
                        "embedded JSON"
                    ),
                )
            except BoundedJsonError:
                start = 0
                embedded_index = 0
                while start < len(encoded_value):
                    if embedded_index >= MAX_RECEIPT_JSONL_RECORDS:
                        _fail(f"{label} exceeds the embedded JSON-line bound")
                    end = encoded_value.find(b"\n", start)
                    if end < 0:
                        end = len(encoded_value)
                    record = encoded_value[start:end]
                    if is_json_candidate(record):
                        try:
                            embedded_record = parse_json_bytes(
                                record,
                                limits=RECEIPT_ARTIFACT_JSON_LIMITS,
                                label=(
                                    f"{label} decoded JSON scalar "
                                    f"{scalar_index - 1} embedded JSON-like "
                                    f"line {embedded_index}"
                                ),
                            )
                        except BoundedJsonError as error:
                            reject_opportunistic_error(error)
                        else:
                            visit_embedded(embedded_record, embedded_index)
                    embedded_index += 1
                    start = end + 1
            else:
                visit_embedded(embedded, 0)
        elif isinstance(value, list):
            for child in value:
                visit(child, document_index, nested_depth)
        elif isinstance(value, dict):
            key_type = value.get("kty")
            if isinstance(key_type, str) and (
                ("d" in value and key_type in {"RSA", "EC", "OKP"})
                or ("k" in value and key_type == "oct")
            ):
                _fail(
                    f"{label} JSON document {document_index} contains "
                    "a credential or private key in JWK key material"
                )
            if value.get("type") == "service_account":
                _fail(
                    f"{label} JSON document {document_index} contains "
                    "a credential or private key in a service-account object"
                )
            for key, child in value.items():
                visit(key, document_index, nested_depth)
                visit(child, document_index, nested_depth)
        elif value is not None and not isinstance(value, (bool, int, float)):
            _fail(
                f"{label} JSON document {document_index} has an unsupported "
                "native scalar"
            )

    def parse_json_lines(*, strict: bool) -> bool:
        start = 0
        record_index = 0
        found = False
        while start < len(content):
            if record_index >= MAX_RECEIPT_JSONL_RECORDS:
                _fail(f"{label} exceeds {MAX_RECEIPT_JSONL_RECORDS} JSONL records")
            end = content.find(b"\n", start)
            if end < 0:
                end = len(content)
            record = content[start:end]
            if strict and not record:
                _fail(f"{label} JSONL record {record_index} is empty")
            if record and (strict or is_json_candidate(record)):
                try:
                    parsed_record = parse_json_bytes(
                        record,
                        limits=RECEIPT_ARTIFACT_JSON_LIMITS,
                        label=f"{label} JSONL record {record_index}",
                    )
                except BoundedJsonError as error:
                    if strict:
                        _fail(str(error))
                    reject_opportunistic_error(error)
                else:
                    visit(parsed_record, record_index, 0)
                    found = True
            record_index += 1
            start = end + 1
        if strict and record_index == 0:
            _fail(f"{label} must contain at least one JSONL record")
        return found

    if is_json:
        try:
            document = parse_json_bytes(
                content,
                limits=RECEIPT_ARTIFACT_JSON_LIMITS,
                label=label,
            )
        except BoundedJsonError as error:
            _fail(str(error))
        visit(document, 0, 0)
    elif is_jsonl:
        parse_json_lines(strict=True)
    else:
        try:
            document = parse_json_bytes(
                content,
                limits=RECEIPT_ARTIFACT_JSON_LIMITS,
                label=label,
            )
        except BoundedJsonError:
            if not parse_json_lines(strict=False):
                return None
        else:
            visit(document, 0, 0)
    return views


def _receipt_text_payload_views(
    relative_path: str,
    content: bytes,
    label: str,
) -> list[tuple[str, str]]:
    text = _decode_receipt_artifact_utf8(content, label)
    json_views = _receipt_json_scalar_views(relative_path, content, label)
    return [(label, text), *(json_views or [])]


def _png_receipt_artifact_text_views(
    content: bytes, label: str
) -> list[tuple[str, str]]:
    """Validate one PNG container and expose every non-pixel metadata payload."""
    allowed_chunks = {
        b"IHDR",
        b"IDAT",
        b"IEND",
        b"tEXt",
        b"zTXt",
        b"iTXt",
    }
    cursor = len(PNG_SIGNATURE)
    chunk_index = 0
    saw_ihdr = False
    saw_idat = False
    idat_closed = False
    saw_iend = False
    ihdr = b""
    idat_parts: list[bytes] = []
    views: list[tuple[str, str]] = []
    metadata_bytes = 0
    text_chunk_count = 0

    def append_view(view_label: str, text: str, byte_count: int) -> None:
        nonlocal metadata_bytes
        metadata_bytes += byte_count
        if metadata_bytes > MAX_RECEIPT_PNG_TEXT_BYTES:
            _fail(f"{label} exceeds the aggregate decoded PNG metadata bound")
        views.append((view_label, text))

    def validate_keyword(keyword: bytes, chunk_label: str) -> None:
        if (
            not 1 <= len(keyword) <= 79
            or keyword.startswith(b" ")
            or keyword.endswith(b" ")
            or b"  " in keyword
            or any(byte < 32 or 127 <= byte <= 160 for byte in keyword)
        ):
            _fail(f"{chunk_label} has an invalid PNG text keyword")

    while cursor < len(content):
        if chunk_index >= MAX_RECEIPT_PNG_CHUNKS:
            _fail(f"{label} exceeds the bounded PNG chunk count")
        if cursor + 12 > len(content):
            _fail(f"{label} truncates a PNG chunk")
        length = int.from_bytes(content[cursor : cursor + 4], "big")
        chunk_type = content[cursor + 4 : cursor + 8]
        chunk_end = cursor + 12 + length
        if length > MAX_RECEIPT_ARTIFACT_DECODED_BYTES or chunk_end > len(content):
            _fail(f"{label} has an out-of-bound PNG chunk")
        chunk = content[cursor + 8 : cursor + 8 + length]
        expected_crc = int.from_bytes(
            content[cursor + 8 + length : chunk_end],
            "big",
        )
        observed_crc = zlib.crc32(chunk_type + chunk) & 0xFFFFFFFF
        if observed_crc != expected_crc:
            _fail(f"{label} has a PNG chunk checksum mismatch")
        if chunk_type not in allowed_chunks:
            _fail(f"{label} has an unsupported PNG metadata chunk")
        if chunk_index == 0 and (chunk_type != b"IHDR" or length != 13):
            _fail(f"{label} does not start with one exact PNG IHDR chunk")
        if chunk_type == b"IHDR":
            if saw_ihdr:
                _fail(f"{label} repeats the PNG IHDR chunk")
            saw_ihdr = True
            ihdr = chunk
        if saw_iend:
            _fail(f"{label} has data after the PNG IEND chunk")
        chunk_label = f"{label} PNG {chunk_type.decode('ascii')}[{chunk_index}]"
        if chunk_type == b"IDAT":
            if idat_closed:
                _fail(f"{label} has non-consecutive PNG IDAT chunks")
            saw_idat = True
            idat_parts.append(chunk)
        elif saw_idat and chunk_type != b"IEND":
            idat_closed = True
        if chunk_type == b"IDAT":
            pass
        elif chunk_type == b"tEXt":
            text_chunk_count += 1
            if text_chunk_count > MAX_RECEIPT_PNG_TEXT_CHUNKS:
                _fail(f"{label} exceeds the PNG text-chunk bound")
            try:
                keyword, text = chunk.split(b"\x00", 1)
            except ValueError:
                _fail(f"{chunk_label} has no text-keyword separator")
            validate_keyword(keyword, chunk_label)
            if b"\x00" in text:
                _fail(f"{chunk_label} has invalid text fields")
            append_view(
                f"{chunk_label} keyword",
                keyword.decode("latin-1"),
                len(keyword),
            )
            append_view(
                f"{chunk_label} text",
                text.decode("latin-1"),
                len(text),
            )
        elif chunk_type == b"zTXt":
            text_chunk_count += 1
            if text_chunk_count > MAX_RECEIPT_PNG_TEXT_CHUNKS:
                _fail(f"{label} exceeds the PNG text-chunk bound")
            try:
                keyword, compressed = chunk.split(b"\x00", 1)
            except ValueError:
                _fail(f"{chunk_label} has no text-keyword separator")
            validate_keyword(keyword, chunk_label)
            if (
                not compressed
                or compressed[0] != 0
            ):
                _fail(f"{chunk_label} has an unsupported compression method")
            append_view(
                f"{chunk_label} keyword",
                keyword.decode("latin-1"),
                len(keyword),
            )
            decoded = _bounded_zlib_decode(
                compressed[1:],
                wbits=zlib.MAX_WBITS,
                label=f"{chunk_label} text",
            )
            append_view(
                f"{chunk_label} text",
                decoded.decode("latin-1"),
                len(decoded),
            )
        elif chunk_type == b"iTXt":
            text_chunk_count += 1
            if text_chunk_count > MAX_RECEIPT_PNG_TEXT_CHUNKS:
                _fail(f"{label} exceeds the PNG text-chunk bound")
            try:
                keyword, remainder = chunk.split(b"\x00", 1)
            except ValueError:
                _fail(f"{chunk_label} has no text-keyword separator")
            validate_keyword(keyword, chunk_label)
            if (
                len(remainder) < 2
                or remainder[0] not in {0, 1}
                or remainder[1] != 0
            ):
                _fail(f"{chunk_label} has invalid compression fields")
            compression_flag = remainder[0]
            remainder = remainder[2:]
            try:
                language, remainder = remainder.split(b"\x00", 1)
                translated_keyword, text = remainder.split(b"\x00", 1)
            except ValueError:
                _fail(f"{chunk_label} truncates an international text field")
            if language and RECEIPT_PNG_LANGUAGE_TAG.fullmatch(language) is None:
                _fail(f"{chunk_label} has an invalid PNG language tag")
            try:
                text_fields = (
                    ("keyword", keyword.decode("latin-1")),
                    ("language", language.decode("ascii")),
                    ("translated keyword", translated_keyword.decode("utf-8")),
                )
            except UnicodeDecodeError as error:
                _fail(f"{chunk_label} has invalid text-field encoding: {error}")
            for (field, value), raw_value in zip(
                text_fields,
                (keyword, language, translated_keyword),
                strict=True,
            ):
                append_view(f"{chunk_label} {field}", value, len(raw_value))
            if compression_flag == 1:
                text = _bounded_zlib_decode(
                    text,
                    wbits=zlib.MAX_WBITS,
                    label=f"{chunk_label} text",
                )
            append_view(
                f"{chunk_label} text",
                _decode_receipt_artifact_utf8(text, f"{chunk_label} text"),
                len(text),
            )
        if chunk_type == b"IEND":
            if length != 0:
                _fail(f"{chunk_label} must be empty")
            saw_iend = True
        cursor = chunk_end
        chunk_index += 1
    if not saw_idat or not saw_iend:
        _fail(f"{label} lacks a complete PNG image-data and end boundary")

    width = int.from_bytes(ihdr[0:4], "big")
    height = int.from_bytes(ihdr[4:8], "big")
    bit_depth, color_type, compression, filter_method, interlace = ihdr[8:13]
    allowed_bit_depths = {
        0: {1, 2, 4, 8, 16},
        2: {8, 16},
        4: {8, 16},
        6: {8, 16},
    }
    if (
        not (
            1 <= width <= MAX_RECEIPT_PNG_DIMENSION
            and 1 <= height <= MAX_RECEIPT_PNG_DIMENSION
            and width * height <= MAX_RECEIPT_PNG_PIXELS
        )
        or color_type not in allowed_bit_depths
        or bit_depth not in allowed_bit_depths[color_type]
        or compression != 0
        or filter_method != 0
        or interlace not in {0, 1}
    ):
        _fail(f"{label} has an invalid PNG IHDR raster contract or display budget")
    channels = {0: 1, 2: 3, 3: 1, 4: 2, 6: 4}[color_type]
    bits_per_pixel = channels * bit_depth

    layouts: list[tuple[int, int]] = []
    if interlace == 0:
        layouts.append((height, (width * bits_per_pixel + 7) // 8))
    else:
        for x_start, y_start, x_step, y_step in (
            (0, 0, 8, 8),
            (4, 0, 8, 8),
            (0, 4, 4, 8),
            (2, 0, 4, 4),
            (0, 2, 2, 4),
            (1, 0, 2, 2),
            (0, 1, 1, 2),
        ):
            pass_width = (
                0
                if width <= x_start
                else (width - x_start + x_step - 1) // x_step
            )
            pass_height = (
                0
                if height <= y_start
                else (height - y_start + y_step - 1) // y_step
            )
            if pass_width and pass_height:
                layouts.append(
                    (
                        pass_height,
                        (pass_width * bits_per_pixel + 7) // 8,
                    )
                )
    scanline_count = sum(rows for rows, _ in layouts)
    expected_raster_bytes = sum(rows * (row_bytes + 1) for rows, row_bytes in layouts)
    if (
        scanline_count > MAX_RECEIPT_PNG_SCANLINES
        or expected_raster_bytes > MAX_RECEIPT_ARTIFACT_DECODED_BYTES
    ):
        _fail(f"{label} exceeds the bounded PNG raster budget")
    raster = _bounded_zlib_decode(
        b"".join(idat_parts),
        wbits=zlib.MAX_WBITS,
        label=f"{label} PNG image data",
    )
    if len(raster) != expected_raster_bytes:
        _fail(f"{label} PNG raster byte count differs from its IHDR contract")
    cursor = 0
    for rows, row_bytes in layouts:
        for _ in range(rows):
            if raster[cursor] > 4:
                _fail(f"{label} PNG scanline uses an unknown filter")
            cursor += row_bytes + 1
    if cursor != len(raster):
        _fail(f"{label} PNG raster traversal is incomplete")
    semantic_views: list[tuple[str, str]] = []
    for view_label, text in views:
        semantic_views.extend(
            _receipt_json_scalar_views(
                "png-metadata.log",
                text.encode(),
                view_label,
            )
            or []
        )
    return [*views, *semantic_views]


def _receipt_artifact_text_views(
    relative_path: str, content: bytes, label: str
) -> tuple[list[tuple[str, str]], bytes]:
    """Return all machine-scannable text and the decoded primary payload."""
    receipt_path = PurePosixPath(relative_path)
    suffix = receipt_path.suffix
    if suffix != suffix.lower():
        _fail(f"{label} has a non-canonical uppercase artifact suffix")
    if content.startswith(PNG_SIGNATURE):
        if suffix != ".png":
            _fail(f"{label} hides PNG content behind a non-PNG path")
        return _png_receipt_artifact_text_views(content, label), content
    if suffix == ".png":
        _fail(f"{label} has a PNG path without a PNG signature")
    if content.startswith(GZIP_MAGIC):
        if suffix != ".gz":
            _fail(f"{label} hides gzip content behind a non-gzip path")
        inner_suffix = receipt_path.with_suffix("").suffix
        if inner_suffix not in SUPPORTED_RECEIPT_TEXT_SUFFIXES:
            _fail(f"{label} has no supported textual suffix inside gzip")
        views = _gzip_header_text_views(content, label)
        decoded = _bounded_zlib_decode(content, wbits=31, label=label)
        if decoded.startswith(GZIP_MAGIC):
            _fail(f"{label} contains unsupported nested gzip content")
        _reject_unsupported_receipt_payload(decoded, f"{label} gzip payload")
        views.extend(
            _receipt_text_payload_views(
                relative_path,
                decoded,
                f"{label} gzip payload",
            )
        )
        return views, decoded
    if suffix == ".gz":
        _fail(f"{label} has a gzip path without a gzip signature")
    if suffix not in SUPPORTED_RECEIPT_TEXT_SUFFIXES:
        _fail(f"{label} has an unsupported receipt-artifact suffix")
    _reject_unsupported_receipt_payload(content, label)
    return _receipt_text_payload_views(relative_path, content, label), content


def _reject_unsupported_receipt_payload(content: bytes, label: str) -> None:
    """Reject a container signature even when it has a textual prefix."""
    for signature, format_name in UNSUPPORTED_RECEIPT_ARTIFACT_SIGNATURES:
        if content.startswith(signature):
            _fail(f"{label} uses unsupported opaque or container format {format_name}")
    for header, format_name in (
        (RECEIPT_ARTIFACT_PDF_HEADER, "PDF"),
        (b"%!PS", "PostScript"),
        (b"{\\rtf", "RTF"),
    ):
        if content.find(header, 0, 1024 + len(header) - 1) >= 0:
            _fail(
                f"{label} uses unsupported opaque or container format {format_name}"
            )


def _non_url_text_contains_host_path(text: str) -> bool:
    current = text
    for _ in range(MAX_RECEIPT_PERCENT_DECODE_DEPTH):
        if RECEIPT_ARTIFACT_HOST_PATH.search(current):
            return True
        decoded = unquote(current)
        if decoded == current:
            return False
        current = decoded
    if RECEIPT_ARTIFACT_HOST_PATH.search(current):
        return True
    decoded = unquote(current)
    return bool(
        decoded != current
        or RECEIPT_ARTIFACT_ENCODED_PATH_SEPARATOR.search(current)
    )


def _valid_receipt_http_hostname(hostname: str) -> bool:
    if "%" in hostname:
        return False
    try:
        ipaddress.ip_address(hostname)
    except ValueError:
        try:
            ascii_hostname = hostname.rstrip(".").encode("idna").decode("ascii").lower()
        except UnicodeError:
            return False
        return bool(
            ascii_hostname
            and len(ascii_hostname) <= 253
            and all(DNS_LABEL.fullmatch(label) for label in ascii_hostname.split("."))
        )
    return True


def _receipt_line_contains_host_path(line: str) -> bool:
    """Ignore valid HTTP route paths but inspect their query and fragment values."""
    if RECEIPT_ARTIFACT_WINDOWS_PATH.search(line):
        return True
    unmasked: list[str] = []
    cursor = 0
    for match in RECEIPT_ARTIFACT_HTTP_URL.finditer(line):
        unmasked.append(line[cursor : match.start()])
        token = match.group(0)
        try:
            parsed = urlsplit(token)
            hostname = parsed.hostname
            _ = parsed.port
        except ValueError:
            return True
        if (
            parsed.scheme.lower() not in {"http", "https"}
            or not parsed.netloc
            or hostname is None
            or parsed.username is not None
            or parsed.password is not None
            or not _valid_receipt_http_hostname(hostname)
            or any(character in parsed.path for character in "\\[]{}|^")
            or RECEIPT_ARTIFACT_INVALID_PERCENT_ESCAPE.search(token)
        ):
            return True
        if _non_url_text_contains_host_path(parsed.query):
            return True
        if _non_url_text_contains_host_path(parsed.fragment):
            return True
        cursor = match.end()
    unmasked.append(line[cursor:])
    return _non_url_text_contains_host_path("".join(unmasked))


def _classify_receipt_text_view(text: str, label: str) -> tuple[int, int]:
    """Scan one bounded text view without materializing a list of its lines."""
    _validate_receipt_text_controls(text, label)
    if SECRET.search(text):
        _fail(f"{label} appears to contain a credential or private key")
    host_path_lines = 0
    private_home_path_lines = 0
    start = 0
    line_count = 0

    def classify_line(end: int) -> None:
        nonlocal host_path_lines, private_home_path_lines, line_count
        if line_count >= MAX_RECEIPT_ARTIFACT_TEXT_LINES:
            _fail(f"{label} exceeds the receipt-artifact text-line bound")
        if end - start > MAX_RECEIPT_ARTIFACT_LINE_CHARS:
            _fail(f"{label} exceeds the receipt-artifact line-length bound")
        line = text[start:end]
        host_path_lines += _receipt_line_contains_host_path(line)
        private_home_path_lines += (
            RECEIPT_ARTIFACT_PRIVATE_HOME_PATH.search(line) is not None
        )
        line_count += 1

    for line_break in RECEIPT_ARTIFACT_LINE_BREAK.finditer(text):
        classify_line(line_break.start())
        start = line_break.end()
    if start < len(text):
        classify_line(len(text))
    return host_path_lines, private_home_path_lines


def _validate_receipt_artifact_portability(
    artifact: Mapping[str, Any],
    content: bytes,
    path: str,
    *,
    repository: str,
    task_id: str | None,
    source_commit: str | None,
    evidence_commit: str,
) -> None:
    """Reject secrets and host paths, except for six exact pre-policy log blobs."""
    relative_path = artifact["path"]
    views, decoded = _receipt_artifact_text_views(relative_path, content, path)
    host_path_lines = 0
    private_home_path_lines = 0
    for view_label, text in views:
        view_host_paths, view_private_home_paths = _classify_receipt_text_view(
            text, view_label
        )
        host_path_lines += view_host_paths
        private_home_path_lines += view_private_home_paths
    legacy = (
        LEGACY_NONPORTABLE_RECEIPT_ARTIFACTS.get((task_id, relative_path))
        if task_id is not None
        else None
    )
    if legacy is not None:
        exact_identity = (
            repository == "NCP"
            and source_commit == legacy["source_commit"]
            and evidence_commit == legacy["evidence_commit"]
            and artifact["bytes"] == legacy["bytes"]
            and artifact["sha256"] == legacy["sha256"]
            and len(content) == legacy["bytes"]
            and hashlib.sha256(content).hexdigest() == legacy["sha256"]
            and len(decoded) == legacy["decoded_bytes"]
            and hashlib.sha256(decoded).hexdigest() == legacy["decoded_sha256"]
        )
        if not exact_identity:
            _fail(f"{path} does not match its exact immutable pre-policy exception")
        if (
            host_path_lines != legacy["host_path_lines"]
            or private_home_path_lines != legacy["private_home_path_lines"]
        ):
            _fail(f"{path} differs from its classified pre-policy path inventory")
        return
    if host_path_lines:
        _fail(f"{path} contains an absolute host path")


def _validate_legacy_portability_exception_inventory(
    tasks: list[dict[str, Any]],
) -> None:
    """Keep the historical exception set exact and reject copies or stale entries."""
    policy_records = [
        {"task_id": task_id, "path": path, **metadata}
        for (task_id, path), metadata in sorted(
            LEGACY_NONPORTABLE_RECEIPT_ARTIFACTS.items()
        )
    ]
    policy_digest = hashlib.sha256(
        json.dumps(
            policy_records,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode()
    ).hexdigest()
    if (
        len(policy_records) != LEGACY_NONPORTABLE_RECEIPT_ARTIFACT_COUNT
        or policy_digest != LEGACY_NONPORTABLE_RECEIPT_ARTIFACT_POLICY_SHA256
    ):
        _fail("legacy receipt portability exception policy differs from its frozen set")
    observed: set[tuple[str, str]] = set()
    for task in tasks:
        task_id = task["id"]
        for transition in task["transitions"]:
            receipt = transition.get("receipt")
            if not isinstance(receipt, dict) or receipt.get("kind") != "passing":
                continue
            for artifact in receipt["artifacts"]:
                key = (task_id, artifact["path"])
                legacy = LEGACY_NONPORTABLE_RECEIPT_ARTIFACTS.get(key)
                if legacy is None:
                    continue
                if key in observed:
                    _fail(f"legacy receipt portability exception {key} is duplicated")
                if (
                    receipt["repository"] != "NCP"
                    or receipt["source_commit"] != legacy["source_commit"]
                    or receipt["evidence_commit"] != legacy["evidence_commit"]
                    or artifact["bytes"] != legacy["bytes"]
                    or artifact["sha256"] != legacy["sha256"]
                ):
                    _fail(
                        f"legacy receipt portability exception {key} has a different "
                        "receipt or artifact identity"
                    )
                observed.add(key)
    expected = set(LEGACY_NONPORTABLE_RECEIPT_ARTIFACTS)
    if observed != expected:
        missing = sorted(expected - observed)
        extra = sorted(observed - expected)
        _fail(
            "legacy receipt portability exception inventory differs from the exact "
            f"pre-policy set: missing={missing} extra={extra}"
        )


def _parse_timestamp(value: Any, path: str) -> datetime:
    text = _string(value, path, maximum=20)
    if not TIMESTAMP.fullmatch(text):
        _fail(f"{path} must be second-resolution UTC")
    try:
        return datetime.strptime(text, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError as error:
        raise LedgerError(f"{path} is not a real UTC datetime") from error


def _check_acyclic(dependencies: dict[str, tuple[str, ...]]) -> None:
    temporary: set[str] = set()
    permanent: set[str] = set()

    def visit(task_id: str) -> None:
        if task_id in permanent:
            return
        if task_id in temporary:
            _fail(f"task dependency cycle includes {task_id}")
        temporary.add(task_id)
        for dependency in dependencies[task_id]:
            visit(dependency)
        temporary.remove(task_id)
        permanent.add(task_id)

    for task_id in dependencies:
        visit(task_id)


def _check_transitively_reduced(dependencies: dict[str, tuple[str, ...]]) -> None:
    """Reject a DAG edge when another dependency path already orders its nodes."""
    _check_acyclic(dependencies)
    for task_id, direct_dependencies in dependencies.items():
        for candidate in direct_dependencies:
            pending = [
                dependency
                for dependency in direct_dependencies
                if dependency != candidate
            ]
            visited: set[str] = set()
            while pending:
                dependency = pending.pop()
                if dependency == candidate:
                    _fail(
                        f"task dependency {task_id}->{candidate} is transitively "
                        "redundant"
                    )
                if dependency in visited:
                    continue
                visited.add(dependency)
                pending.extend(dependencies[dependency])


def _validate_review_independence(
    reviewers: list[dict[str, Any]], path: str, *, minimum: int = 1
) -> None:
    independent = [
        reviewer for reviewer in reviewers if reviewer.get("independent") is True
    ]
    identities = {reviewer.get("identity") for reviewer in independent}
    if len(identities) < minimum:
        _fail(
            f"{path} requires at least {minimum} distinct independent reviewer identities"
        )
    for reviewer in independent:
        if reviewer.get("identity") == reviewer.get("implementation_owner"):
            _fail(f"{path} cannot count self-review as independent review")
        _validate_identity_uri(reviewer.get("identity"), f"{path}.independent.identity")
        _validate_identity_uri(
            reviewer.get("implementation_owner"),
            f"{path}.independent.implementation_owner",
        )


def _validate_reviewer(reviewer: Any, path: str) -> None:
    if not isinstance(reviewer, dict):
        _fail(f"{path} must be an object")
    _exact_keys(
        reviewer,
        {"identity", "role", "independent", "implementation_owner", "decision"},
        path,
    )
    for field in ("identity", "role", "implementation_owner", "decision"):
        _string(reviewer[field], f"{path}.{field}", maximum=256)
    if not isinstance(reviewer["independent"], bool):
        _fail(f"{path}.independent must be boolean")


def _validate_reviewer_owner_partition(
    reviewers: list[dict[str, Any]],
    path: str,
) -> None:
    reviewer_identities = {reviewer["identity"] for reviewer in reviewers}
    implementation_owners = {reviewer["implementation_owner"] for reviewer in reviewers}
    overlap = reviewer_identities & implementation_owners
    if overlap:
        _fail(
            f"{path} aliases reviewer identities with the task-wide "
            f"implementation-owner union: {sorted(overlap)[0]}"
        )


def _validate_task_wide_reviewer_owner_partition(
    task: dict[str, Any],
    path: str,
) -> None:
    """Reject role swapping across every passing receipt in one task generation history."""
    reviewer_groups: list[list[dict[str, Any]]] = []
    current_reviewers = task.get("reviewers")
    if isinstance(current_reviewers, list):
        reviewer_groups.append(current_reviewers)
    for transition in task.get("transitions", []):
        if not isinstance(transition, dict):
            continue
        receipt = transition.get("receipt")
        if (
            isinstance(receipt, dict)
            and receipt.get("kind") == "passing"
            and isinstance(receipt.get("reviewers"), list)
        ):
            reviewer_groups.append(receipt["reviewers"])
    reviewer_identities = {
        reviewer["identity"]
        for reviewers in reviewer_groups
        for reviewer in reviewers
        if isinstance(reviewer, dict) and isinstance(reviewer.get("identity"), str)
    }
    implementation_owners = {
        reviewer["implementation_owner"]
        for reviewers in reviewer_groups
        for reviewer in reviewers
        if isinstance(reviewer, dict)
        and isinstance(reviewer.get("implementation_owner"), str)
    }
    overlap = reviewer_identities & implementation_owners
    if overlap:
        _fail(
            f"{path} aliases reviewer identities with the task-wide "
            f"implementation-owner union: {sorted(overlap)[0]}"
        )


def _validate_toolchain(toolchain: Any, path: str) -> None:
    if not isinstance(toolchain, list) or not toolchain or len(toolchain) > 32:
        _fail(f"{path} must retain between 1 and 32 tool versions")
    names: set[str] = set()
    for index, tool in enumerate(toolchain):
        tool_path = f"{path}[{index}]"
        if not isinstance(tool, dict):
            _fail(f"{tool_path} must be an object")
        _exact_keys(tool, {"name", "version"}, tool_path)
        name = _string(tool["name"], f"{tool_path}.name", maximum=64)
        _string(tool["version"], f"{tool_path}.version", maximum=256)
        if name in names:
            _fail(f"{path} duplicates tool name {name}")
        names.add(name)


def _validate_artifacts(
    artifacts: Any,
    path: str,
    *,
    repository: str,
    evidence_commit: str,
    task_id: str | None = None,
    source_commit: str | None = None,
    budget: dict[str, int] | None = None,
) -> list[dict[str, Any]]:
    if not isinstance(artifacts, list) or len(artifacts) > MAX_EVIDENCE_FILES:
        _fail(f"{path} must be an array of at most {MAX_EVIDENCE_FILES} artifacts")
    if budget is None:
        budget = {"references": 0, "bytes": 0}
    subjects: set[str] = set()
    relative_paths: set[str] = set()
    validated: list[dict[str, Any]] = []
    for index, artifact in enumerate(artifacts):
        artifact_path = f"{path}[{index}]"
        if not isinstance(artifact, dict):
            _fail(f"{artifact_path} must be an object")
        _exact_keys(artifact, {"subject", "path", "sha256", "bytes"}, artifact_path)
        subject = _string(artifact["subject"], f"{artifact_path}.subject", maximum=128)
        if subject in subjects:
            _fail(f"{path} contains duplicate subject {subject}")
        subjects.add(subject)
        relative = _relative_path(artifact["path"], f"{artifact_path}.path")
        if relative in relative_paths:
            _fail(f"{path} contains duplicate path {relative}")
        relative_paths.add(relative)
        expected_sha = _hex(artifact["sha256"], HEX64, f"{artifact_path}.sha256")
        expected_bytes = artifact["bytes"]
        if (
            type(expected_bytes) is not int
            or not 1 <= expected_bytes <= MAX_EVIDENCE_FILE_BYTES
        ):
            _fail(f"{artifact_path}.bytes is outside the retained-evidence bound")
        budget["references"] += 1
        budget["bytes"] += expected_bytes
        if budget["references"] > MAX_EVIDENCE_REFERENCES:
            _fail("ledger exceeds the aggregate evidence-reference bound")
        if budget["bytes"] > MAX_EVIDENCE_REFERENCED_BYTES:
            _fail("ledger exceeds the aggregate referenced-evidence byte bound")
        repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY.get(repository)
        if repository_root is None:
            _fail(f"{artifact_path} has no configured Git object authority")
        _, content = _resolved_git_blob(
            str(repository_root),
            evidence_commit,
            relative,
        )
        if len(content) != expected_bytes:
            _fail(f"{artifact_path}.bytes does not match the evidence-cut blob")
        if hashlib.sha256(content).hexdigest() != expected_sha:
            _fail(f"{artifact_path}.sha256 does not match the evidence-cut blob")
        _validate_receipt_artifact_portability(
            artifact,
            content,
            artifact_path,
            repository=repository,
            task_id=task_id,
            source_commit=source_commit,
            evidence_commit=evidence_commit,
        )
        validated.append(artifact)
    return validated


def _validate_commands(
    commands: Any, path: str, artifact_paths: set[str]
) -> list[dict[str, Any]]:
    if not isinstance(commands, list) or not commands or len(commands) > 128:
        _fail(f"{path} must retain between 1 and 128 command results")
    for index, command in enumerate(commands):
        command_path = f"{path}[{index}]"
        if not isinstance(command, dict):
            _fail(f"{command_path} must be an object")
        _exact_keys(
            command,
            {"command", "exit_code", "output_artifact", "passed", "failed", "skipped"},
            command_path,
        )
        _string(command["command"], f"{command_path}.command", maximum=1024)
        _integer(command["exit_code"], f"{command_path}.exit_code")
        if command["exit_code"] != 0 or command["failed"] != 0:
            _fail(f"{command_path} is not a passing command result")
        output = _relative_path(
            command["output_artifact"], f"{command_path}.output_artifact"
        )
        if output not in artifact_paths:
            _fail(f"{command_path}.output_artifact lacks a verified artifact record")
        for field in ("passed", "failed", "skipped"):
            _integer(command[field], f"{command_path}.{field}", minimum=0)
        if command["passed"] < 1:
            _fail(f"{command_path} did not execute any passing check")
        if command["skipped"] != 0:
            _fail(f"{command_path} contains unexplained skipped checks")
    return commands


def _validate_dependency_receipt_bindings_shape(
    bindings: Any,
    path: str,
    *,
    require_nonempty: bool,
) -> None:
    if not isinstance(bindings, list) or (require_nonempty and not bindings):
        qualifier = "a nonempty" if require_nonempty else "an"
        _fail(f"{path} must be {qualifier} dependency-receipt array")
    seen: set[str] = set()
    for index, binding in enumerate(bindings):
        binding_path = f"{path}[{index}]"
        if not isinstance(binding, dict):
            _fail(f"{binding_path} must be an object")
        _exact_keys(binding, {"task_id", "receipt_sha256"}, binding_path)
        task_id = _string(binding["task_id"], f"{binding_path}.task_id", maximum=3)
        if not TASK_ID.fullmatch(task_id):
            _fail(f"{binding_path}.task_id must identify a checked task")
        if task_id in seen:
            _fail(f"{path} duplicates {task_id}")
        seen.add(task_id)
        _hex(binding["receipt_sha256"], HEX64, f"{binding_path}.receipt_sha256")


def _validate_local_transition_subject_shape(value: Any, path: str) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an exact local transition subject")
    _exact_keys(
        value,
        {
            "schema",
            "receipt_kind",
            "task_id",
            "from",
            "to",
            "requirement_acceptance_sha256",
            "repository",
            "branch",
            "source_commit",
            "source_tree",
            "evidence_commit",
            "evidence_tree",
            "dependency_receipts",
            "task_subject_sha256",
            "correlation_id",
        },
        path,
    )
    if value["schema"] != LOCAL_TRANSITION_SUBJECT_SCHEMA:
        _fail(f"{path}.schema is not the local transition-subject schema")
    if value["receipt_kind"] not in {"start", "coordination", "passing"}:
        _fail(f"{path}.receipt_kind is invalid")
    task_id = _string(value["task_id"], f"{path}.task_id", maximum=3)
    if not TASK_ID.fullmatch(task_id):
        _fail(f"{path}.task_id must identify a checked task")
    for field in ("from", "to"):
        if value[field] not in STATUSES:
            _fail(f"{path}.{field} is not a checked status")
    _hex(
        value["requirement_acceptance_sha256"],
        HEX64,
        f"{path}.requirement_acceptance_sha256",
    )
    _string(value["repository"], f"{path}.repository", maximum=128)
    _validate_branch_name(value["branch"], f"{path}.branch")
    for field in (
        "source_commit",
        "source_tree",
        "evidence_commit",
        "evidence_tree",
    ):
        if value[field] is not None:
            _hex(value[field], HEX40, f"{path}.{field}")
    _validate_dependency_receipt_bindings_shape(
        value["dependency_receipts"],
        f"{path}.dependency_receipts",
        require_nonempty=False,
    )
    if value["task_subject_sha256"] is not None:
        _hex(value["task_subject_sha256"], HEX64, f"{path}.task_subject_sha256")
    _string(value["correlation_id"], f"{path}.correlation_id", maximum=128)


def _validate_coordination_receipt(
    receipt: Any,
    path: str,
    *,
    budget: dict[str, int],
    repository: str,
) -> None:
    if not isinstance(receipt, dict):
        _fail(f"{path} must be a coordination receipt object")
    _exact_keys(
        receipt,
        {
            "kind",
            "repository",
            "branch",
            "source_commit",
            "source_tree",
            "evidence_commit",
            "evidence_tree",
            "evidence",
            "dependency_receipts",
            "transition_subject",
            "timestamp_utc",
        },
        path,
    )
    if receipt["kind"] != "coordination":
        _fail(f"{path}.kind must be coordination")
    git_repository = COORDINATION_GIT_REPOSITORY_BY_TASK_REPOSITORY.get(repository)
    if git_repository is None:
        _fail(f"{path}.repository has no exact task-repository policy")
    if receipt["repository"] != git_repository:
        _fail(f"{path}.repository differs from the task repository")
    _validate_branch_name(receipt["branch"], f"{path}.branch")
    source_commit = _hex(receipt["source_commit"], HEX40, f"{path}.source_commit")
    source_tree = _hex(receipt["source_tree"], HEX40, f"{path}.source_tree")
    _validate_git_commit_tree(git_repository, source_commit, source_tree, path)
    _validate_evidence_cut(receipt, path)
    evidence = _validate_artifacts(
        receipt["evidence"],
        f"{path}.evidence",
        repository=git_repository,
        evidence_commit=receipt["evidence_commit"],
        budget=budget,
    )
    if not evidence:
        _fail(f"{path}.evidence must retain the blocker or reopen basis")
    _validate_dependency_receipt_bindings_shape(
        receipt["dependency_receipts"],
        f"{path}.dependency_receipts",
        require_nonempty=False,
    )
    _validate_local_transition_subject_shape(
        receipt["transition_subject"],
        f"{path}.transition_subject",
    )
    _parse_timestamp(receipt["timestamp_utc"], f"{path}.timestamp_utc")


def _validate_start_receipt(receipt: Any, path: str) -> None:
    if not isinstance(receipt, dict):
        _fail(f"{path} must be a dependency-bound start receipt")
    _exact_keys(
        receipt,
        {"kind", "dependency_receipts", "transition_subject", "timestamp_utc"},
        path,
    )
    if receipt["kind"] != "start":
        _fail(f"{path}.kind must be start")
    _validate_dependency_receipt_bindings_shape(
        receipt["dependency_receipts"],
        f"{path}.dependency_receipts",
        require_nonempty=True,
    )
    _validate_local_transition_subject_shape(
        receipt["transition_subject"],
        f"{path}.transition_subject",
    )
    _parse_timestamp(receipt["timestamp_utc"], f"{path}.timestamp_utc")


def _validate_push_binding(
    *,
    task_id: str,
    commit: str,
    branch: str,
    push_ref: Any,
    object_kind: Any,
    pushed_object: Any,
    path: str,
) -> None:
    ref = _string(push_ref, f"{path}.push_ref", maximum=256)
    pushed = _hex(pushed_object, HEX40, f"{path}.pushed_object")
    if object_kind == "branch":
        if task_id == "R03":
            _fail(f"{path} R03 requires an immutable annotated tag object")
        if ref != f"refs/heads/{branch}" or pushed != commit:
            _fail(f"{path} branch push must bind the implementation commit")
    elif object_kind == "annotated_tag":
        if task_id != "R03" or not ref.startswith("refs/tags/"):
            _fail(f"{path} annotated tag evidence is allowed only for R03")
    else:
        _fail(f"{path}.push_object_kind is invalid")


def _validate_annotated_tag_object(
    repository: str, tag_object: str, implementation_commit: str, path: str
) -> None:
    repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[repository]
    object_type = _run_git(
        repository_root,
        ["cat-file", "-t", tag_object],
        f"{path}.pushed_object",
    )
    if object_type != "tag":
        _fail(f"{path}.pushed_object is not an annotated Git tag object")
    peeled = _run_git(
        repository_root,
        ["rev-parse", "--verify", f"{tag_object}^{{commit}}"],
        f"{path}.pushed_object peeled commit",
    )
    if peeled != implementation_commit:
        _fail(f"{path}.pushed_object does not peel to the implementation commit")


def _task_subject_required(task_id: str, transition_to: str) -> bool:
    if task_id == "B01":
        return transition_to in {"INDEPENDENT_PASS", "COMPLETE"}
    if task_id == "B02":
        return transition_to in {"EXTERNAL_PASS", "INDEPENDENT_PASS", "COMPLETE"}
    return task_id in {"B03", "N01"} and transition_to in {
        "LOCAL_PASS",
        "EXTERNAL_PASS",
        "INDEPENDENT_PASS",
        "COMPLETE",
    }


def _validate_fixed_file_identity_shape(
    value: Any, path: str, *, expected_path: str
) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an exact file-identity object")
    _exact_keys(value, {"path", "sha256", "bytes"}, path)
    relative = _relative_path(value["path"], f"{path}.path")
    _hex(value["sha256"], HEX64, f"{path}.sha256")
    if relative != expected_path:
        _fail(f"{path} identifies the wrong file")
    byte_count = _integer(value["bytes"], f"{path}.bytes", minimum=1)
    if byte_count > MAX_EVIDENCE_FILE_BYTES:
        _fail(f"{path}.bytes exceeds the file-size bound")


def _validate_b01_task_subject_shape(subject: dict[str, Any], path: str) -> None:
    common_identity_fields = {
        "registry_path",
        "registry_sha256",
        "decision_set_sha256",
        "review_policy_sha256",
        "review_packet_path",
        "review_packet_sha256",
        "source_commit",
        "source_tree",
    }
    _exact_keys(
        subject,
        {
            "schema",
            *common_identity_fields,
            "accepted_adr_ids",
            "qualifying_review_ids",
            "role_coverage_sha256",
            "adjudication_artifacts",
        },
        path,
    )
    if subject["schema"] != "ncp.b01-ledger-ratification-subject.v1":
        _fail(f"{path}.schema is not the B01 ratification-subject schema")
    for field in ("accepted_adr_ids", "qualifying_review_ids"):
        values = subject[field]
        if not isinstance(values, list) or not 1 <= len(values) <= 256:
            _fail(f"{path}.{field} must contain 1..256 identities")
        for index, value in enumerate(values):
            _string(value, f"{path}.{field}[{index}]", maximum=128)
        if len(values) != len(set(values)):
            _fail(f"{path}.{field} contains duplicates")
    artifacts = subject["adjudication_artifacts"]
    if not isinstance(artifacts, list) or not 2 <= len(artifacts) <= 8:
        _fail(f"{path}.adjudication_artifacts must contain 2..8 receipts")
    for index, artifact in enumerate(artifacts):
        _relative_path(artifact, f"{path}.adjudication_artifacts[{index}]")
    if len(artifacts) != len(set(artifacts)):
        _fail(f"{path}.adjudication_artifacts contains duplicates")


def _validate_b02_task_subject_shape(subject: dict[str, Any], path: str) -> None:
    _exact_keys(
        subject,
        {
            "schema",
            "registry_path",
            "registry_sha256",
            "decision_set_sha256",
            "review_policy_sha256",
            "review_packet_path",
            "review_packet_sha256",
            "source_commit",
            "source_tree",
            "b01_ratification_receipt_sha256",
            "authorization_artifact",
        },
        path,
    )
    if subject["schema"] != "ncp.b02-rebaseline-authorization-subject.v1":
        _fail(f"{path}.schema is not the B02 authorization-subject schema")
    _relative_path(subject["authorization_artifact"], f"{path}.authorization_artifact")


def _validate_b03_task_subject_shape(subject: dict[str, Any], path: str) -> None:
    _exact_keys(
        subject,
        {
            "schema",
            "decision_set_sha256",
            "b02_authorization_receipt_sha256",
            "registry_set_sha256",
            "allocations_artifact",
        },
        path,
    )
    if subject["schema"] != "ncp.b03-allocation-subject.v1":
        _fail(f"{path}.schema is not the B03 allocation-subject schema")
    _relative_path(subject["allocations_artifact"], f"{path}.allocations_artifact")


def _validate_n01_task_subject_shape(subject: dict[str, Any], path: str) -> None:
    _exact_keys(
        subject,
        {
            "schema",
            "decision_set_sha256",
            "b02_authorization_receipt_sha256",
            "b03_allocation_receipt_sha256",
            "staging_registry_sha256",
            "promoted_registry_path",
            "promoted_registry_sha256",
            "promotion_generator",
            "promoted_registry_schema",
            "contract_manifest_path",
            "contract_manifest_sha256",
            "normative_digest_before",
            "normative_digest_after",
        },
        path,
    )
    if subject["schema"] != "ncp.n01-promotion-subject.v1":
        _fail(f"{path}.schema is not the N01 promotion-subject schema")
    _relative_path(subject["promoted_registry_path"], f"{path}.promoted_registry_path")
    _relative_path(subject["contract_manifest_path"], f"{path}.contract_manifest_path")
    _validate_fixed_file_identity_shape(
        subject["promotion_generator"],
        f"{path}.promotion_generator",
        expected_path=DECISION_REGISTRY_PROMOTION_GENERATOR.relative_to(
            ROOT
        ).as_posix(),
    )
    _validate_fixed_file_identity_shape(
        subject["promoted_registry_schema"],
        f"{path}.promoted_registry_schema",
        expected_path=PROMOTED_DECISION_REGISTRY_SCHEMA.relative_to(ROOT).as_posix(),
    )


def _validate_task_subject_common_fields(subject: dict[str, Any], path: str) -> None:
    for field in (
        "registry_sha256",
        "decision_set_sha256",
        "review_policy_sha256",
        "review_packet_sha256",
        "role_coverage_sha256",
        "b01_ratification_receipt_sha256",
        "b02_authorization_receipt_sha256",
        "b03_allocation_receipt_sha256",
        "registry_set_sha256",
        "staging_registry_sha256",
        "promoted_registry_sha256",
        "contract_manifest_sha256",
        "normative_digest_before",
        "normative_digest_after",
    ):
        if field in subject:
            _hex(subject[field], HEX64, f"{path}.{field}")
    for field in ("source_commit", "source_tree"):
        if field in subject:
            _hex(subject[field], HEX40, f"{path}.{field}")
    for field in ("registry_path", "review_packet_path"):
        if field in subject:
            _relative_path(subject[field], f"{path}.{field}")


def _validate_task_subject_shape(
    subject: Any, path: str, *, task_id: str, transition_to: str
) -> None:
    if not _task_subject_required(task_id, transition_to):
        if subject is not None:
            _fail(f"{path} is allowed only when the task reaches its evidence floor")
        return
    if not isinstance(subject, dict):
        _fail(f"{path} requires the exact {task_id} task-specific subject")
    validators = {
        "B01": _validate_b01_task_subject_shape,
        "B02": _validate_b02_task_subject_shape,
        "B03": _validate_b03_task_subject_shape,
        "N01": _validate_n01_task_subject_shape,
    }
    validators[task_id](subject, path)
    _validate_task_subject_common_fields(subject, path)


def _require_remote_mapping_matches(
    actual: dict[str, Any],
    expected: dict[str, Any],
    path: str,
) -> None:
    for key, expected_value in expected.items():
        if actual.get(key) != expected_value:
            _fail(f"{path}.{key} differs from the passing receipt")


def _validate_branch_remote_verification(
    receipt: dict[str, Any], remote: dict[str, Any], path: str
) -> None:
    if receipt["push_object_kind"] == "branch":
        if remote.get("local_head") != receipt["commit"]:
            _fail(f"{path}.remote_verification_artifact does not bind the local HEAD")
        tracking = remote.get("remote_tracking_object")
        if tracking is not None and tracking != receipt["commit"]:
            _fail(
                f"{path}.remote_verification_artifact remote tracking object "
                "differs from the commit"
            )


def _validate_remote_verification_artifact(
    receipt: dict[str, Any],
    artifact_paths: set[str],
    path: str,
) -> None:
    remote_path = receipt["remote_verification_artifact"]
    if remote_path not in artifact_paths:
        _fail(f"{path}.remote_verification_artifact lacks a verified artifact record")
    evidence = _load_bounded_json_bytes(
        _receipt_artifact_bytes(
            receipt,
            remote_path,
            f"{path}.remote_verification_artifact",
        ),
        f"{path}.remote_verification_artifact",
    )
    source = evidence.get("source")
    remote = evidence.get("remote_verification")
    if not isinstance(source, dict) or not isinstance(remote, dict):
        _fail(
            f"{path}.remote_verification_artifact lacks source and "
            "remote_verification objects"
        )
    _require_remote_mapping_matches(
        source,
        {
            "repository": receipt["repository"],
            "branch": receipt["branch"],
            "commit": receipt["commit"],
            "tree": receipt["source_tree"],
        },
        f"{path}.remote_verification_artifact source",
    )
    _require_remote_mapping_matches(
        remote,
        {
            "remote": receipt["push_remote"],
            "ref": receipt["push_ref"],
            "remote_advertised_object": receipt["pushed_object"],
            "verified_at_utc": receipt["remote_verified_at_utc"],
        },
        f"{path}.remote_verification_artifact remote_verification",
    )
    _validate_branch_remote_verification(receipt, remote, path)
    clean = remote.get("worktree_clean")
    if clean is None:
        clean = remote.get("source_tracked_worktree_clean")
    if clean is not True:
        _fail(f"{path}.remote_verification_artifact does not record a clean source")


def _validate_receipt_gate_class(
    task_id: str,
    transition_to: str,
    path: str,
) -> None:
    _reject_unsupported_evidence_admission(task_id, transition_to, path)
    if transition_to == "EXTERNAL_PASS" and task_id not in REQUIRED_EXTERNAL_GATES:
        _fail(f"{path} task {task_id} has no checked EXTERNAL_PASS gate")
    if (
        transition_to == "INDEPENDENT_PASS"
        and task_id not in INDEPENDENT_REVIEWER_MINIMUM
    ):
        _fail(f"{path} task {task_id} has no checked INDEPENDENT_PASS floor")


@lru_cache(maxsize=None)
def _has_external_or_independent_floor_in_ancestry(task_id: str) -> bool:
    dependency_by_task = {
        catalog_task_id: dependencies
        for catalog_task_id, _, dependencies, _ in TASK_CATALOG
    }
    pending = [task_id]
    visited: set[str] = set()
    while pending:
        current = pending.pop()
        if current in visited:
            continue
        visited.add(current)
        if MINIMUM_TERMINAL_CLASS[current] != "LOCAL":
            return True
        pending.extend(dependency_by_task[current])
    return False


def _reject_unsupported_evidence_admission(
    task_id: str,
    transition_to: str,
    path: str,
) -> None:
    if transition_to in {"EXTERNAL_PASS", "INDEPENDENT_PASS"}:
        _fail(
            f"{path} rejects {transition_to}: {UNSUPPORTED_EVIDENCE_ADMISSION}; "
            "local JSON, URLs, booleans, Git refs, reviewers, and in-process "
            "cryptography cannot satisfy an external or independent floor"
        )
    if transition_to == "COMPLETE" and (
        _has_external_or_independent_floor_in_ancestry(task_id)
    ):
        _fail(
            f"{path} rejects externally dependent COMPLETE: "
            f"{UNSUPPORTED_EVIDENCE_ADMISSION}"
        )


def _validate_receipt_reviewers(
    reviewers: Any,
    path: str,
    *,
    task_id: str,
    transition_to: str,
) -> None:
    if not isinstance(reviewers, list) or not reviewers or len(reviewers) > 16:
        _fail(f"{path}.reviewers must retain between 1 and 16 decisions")
    reviewer_identities: set[str] = set()
    for index, reviewer in enumerate(reviewers):
        _validate_reviewer(reviewer, f"{path}.reviewers[{index}]")
        if reviewer["decision"] != "PASS":
            _fail(f"{path}.reviewers[{index}].decision must be PASS")
        if reviewer["identity"] in reviewer_identities:
            _fail(f"{path}.reviewers duplicates identity {reviewer['identity']}")
        reviewer_identities.add(reviewer["identity"])
    _validate_reviewer_owner_partition(reviewers, f"{path}.reviewers")
    if transition_to == "INDEPENDENT_PASS" and task_id != "B01":
        _validate_review_independence(
            reviewers,
            f"{path}.reviewers",
            minimum=INDEPENDENT_REVIEWER_MINIMUM[task_id],
        )
    elif (
        transition_to == "COMPLETE"
        and MINIMUM_TERMINAL_CLASS[task_id] == "INDEPENDENT"
        and task_id != "B01"
    ):
        _validate_review_independence(
            reviewers,
            f"{path}.reviewers",
            minimum=INDEPENDENT_REVIEWER_MINIMUM[task_id],
        )


def _validate_receipt(
    receipt: Any,
    path: str,
    *,
    task_id: str,
    transition_to: str,
    budget: dict[str, int],
) -> None:
    if not isinstance(receipt, dict):
        _fail(f"{path} must be an object")
    _validate_receipt_gate_class(task_id, transition_to, path)
    expected = {
        "kind",
        "repository",
        "branch",
        "source_commit",
        "source_tree",
        "evidence_commit",
        "evidence_tree",
        "normative_digest_before",
        "normative_digest_after",
        "commands",
        "artifacts",
        "environment",
        "toolchain",
        "reviewers",
        "external_gates_run",
        "external_gates_not_run",
        "residual_risks",
        "rollback_or_recovery",
        "commit",
        "push_remote",
        "push_ref",
        "push_object_kind",
        "pushed_object",
        "remote_verification_artifact",
        "remote_verified_at_utc",
        "dependency_receipts",
        "task_subject",
        "transition_subject",
        "timestamp_utc",
    }
    _exact_keys(receipt, expected, path)
    if receipt["kind"] != "passing":
        _fail(f"{path}.kind must be passing")
    repository = _string(receipt["repository"], f"{path}.repository", maximum=128)
    branch = _validate_branch_name(receipt["branch"], f"{path}.branch")
    source_commit = _hex(receipt["source_commit"], HEX40, f"{path}.source_commit")
    source_tree = _hex(receipt["source_tree"], HEX40, f"{path}.source_tree")
    _validate_git_commit_tree(repository, source_commit, source_tree, path)
    _validate_evidence_cut(receipt, path)
    for name in ("normative_digest_before", "normative_digest_after"):
        value = receipt[name]
        if value is not None:
            _hex(value, HEX64, f"{path}.{name}")
    artifacts = _validate_artifacts(
        receipt["artifacts"],
        f"{path}.artifacts",
        repository=repository,
        evidence_commit=receipt["evidence_commit"],
        task_id=task_id,
        source_commit=source_commit,
        budget=budget,
    )
    artifact_paths = {artifact["path"] for artifact in artifacts}
    _validate_commands(receipt["commands"], f"{path}.commands", artifact_paths)
    _string(receipt["environment"], f"{path}.environment", maximum=1024)
    _validate_toolchain(receipt["toolchain"], f"{path}.toolchain")
    reviewers = receipt["reviewers"]
    _validate_receipt_reviewers(
        reviewers,
        path,
        task_id=task_id,
        transition_to=transition_to,
    )
    for field in ("external_gates_run", "external_gates_not_run", "residual_risks"):
        values = receipt[field]
        if not isinstance(values, list):
            _fail(f"{path}.{field} must be an array")
        for index, value in enumerate(values):
            _string(value, f"{path}.{field}[{index}]", maximum=512)
        if len(values) != len(set(values)):
            _fail(f"{path}.{field} contains duplicates")
    overlap = set(receipt["external_gates_run"]) & set(
        receipt["external_gates_not_run"]
    )
    if overlap:
        _fail(
            f"{path} records external gates as both run and not run: {sorted(overlap)}"
        )
    if transition_to == "EXTERNAL_PASS":
        expected_gates = set(REQUIRED_EXTERNAL_GATES[task_id])
        observed_gates = set(receipt["external_gates_run"])
        if observed_gates != expected_gates:
            _fail(
                f"{path}.external_gates_run differs from the exact checked gates: "
                f"missing={sorted(expected_gates - observed_gates)} "
                f"extra={sorted(observed_gates - expected_gates)}"
            )
    _string(
        receipt["rollback_or_recovery"], f"{path}.rollback_or_recovery", maximum=1024
    )
    commit = _hex(receipt["commit"], HEX40, f"{path}.commit")
    if source_commit != commit:
        _fail(
            f"{path}.source_commit and commit must identify the same implementation cut"
        )
    _string(receipt["push_remote"], f"{path}.push_remote", maximum=256)
    if receipt["push_remote"] != "origin":
        _fail(f"{path}.push_remote must be the authorized origin remote")
    _validate_push_binding(
        task_id=task_id,
        commit=commit,
        branch=branch,
        push_ref=receipt["push_ref"],
        object_kind=receipt["push_object_kind"],
        pushed_object=receipt["pushed_object"],
        path=path,
    )
    if receipt["push_object_kind"] == "annotated_tag":
        _validate_annotated_tag_object(
            repository,
            receipt["pushed_object"],
            commit,
            path,
        )
    _relative_path(
        receipt["remote_verification_artifact"],
        f"{path}.remote_verification_artifact",
    )
    _validate_remote_verification_artifact(receipt, artifact_paths, path)
    remote_verified_at = _parse_timestamp(
        receipt["remote_verified_at_utc"], f"{path}.remote_verified_at_utc"
    )
    bindings = receipt["dependency_receipts"]
    if not isinstance(bindings, list):
        _fail(f"{path}.dependency_receipts must be an array")
    seen_dependencies: set[str] = set()
    for index, binding in enumerate(bindings):
        binding_path = f"{path}.dependency_receipts[{index}]"
        if not isinstance(binding, dict):
            _fail(f"{binding_path} must be an object")
        _exact_keys(binding, {"task_id", "receipt_sha256"}, binding_path)
        dependency = _string(binding["task_id"], f"{binding_path}.task_id", maximum=3)
        if dependency in seen_dependencies:
            _fail(f"{path}.dependency_receipts duplicates {dependency}")
        seen_dependencies.add(dependency)
        _hex(binding["receipt_sha256"], HEX64, f"{binding_path}.receipt_sha256")
    _validate_task_subject_shape(
        receipt["task_subject"],
        f"{path}.task_subject",
        task_id=task_id,
        transition_to=transition_to,
    )
    _validate_local_transition_subject_shape(
        receipt["transition_subject"],
        f"{path}.transition_subject",
    )
    receipt_time = _parse_timestamp(receipt["timestamp_utc"], f"{path}.timestamp_utc")
    if remote_verified_at > receipt_time:
        _fail(f"{path}.remote_verified_at_utc is newer than the receipt")


def _task_reached_minimum(task: dict[str, Any]) -> bool:
    """Return whether the current, non-reopened generation meets its local floor."""
    return task.get("minimum_terminal_class") == "LOCAL" and task.get("status") in {
        "LOCAL_PASS",
        "COMPLETE",
    }


def _receipt_sha256(receipt: dict[str, Any]) -> str:
    encoded = json.dumps(
        receipt, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode()
    return hashlib.sha256(encoded).hexdigest()


def _requirement_acceptance_sha256(task: dict[str, Any]) -> str:
    return _canonical_sha256(
        {
            "schema": LOCAL_REQUIREMENT_ACCEPTANCE_SCHEMA,
            "task_id": task["id"],
            "title": task["title"],
            "dependencies": task["dependencies"],
            "repository_scope": task["repository"],
            "minimum_terminal_class": task["minimum_terminal_class"],
            "claim_tier": task["claim_tier"],
            "requirement_ids": task["requirement_ids"],
            "adr_ids": task["adr_ids"],
            "perspective_ids": [review["id"] for review in task["perspective_reviews"]],
            "lens_ids": [review["id"] for review in task["ten_lens_reviews"]],
        }
    )


def _expected_receipt_repository(task: Mapping[str, Any]) -> str:
    repository_scope = task["repository"]
    expected = COORDINATION_GIT_REPOSITORY_BY_TASK_REPOSITORY.get(repository_scope)
    if expected is None:
        _fail(f"task {task['id']} repository scope has no exact local receipt policy")
    return expected


def _validate_receipt_repository_policy(
    task: Mapping[str, Any],
    receipt_repository: Any,
    path: str,
) -> str:
    expected = _expected_receipt_repository(task)
    actual = _string(receipt_repository, f"{path}.repository", maximum=128)
    if actual != expected:
        _fail(
            f"{path}.repository differs from task {task['id']} exact "
            "task-repository policy"
        )
    return actual


def _expected_local_transition_subject(
    task: dict[str, Any],
    transition: dict[str, Any],
    receipt: dict[str, Any],
    repository_by_name: Mapping[str, dict[str, Any]],
) -> dict[str, Any]:
    receipt_kind = receipt["kind"]
    expected_repository = _expected_receipt_repository(task)
    configured_repository = repository_by_name[expected_repository]
    if receipt_kind == "start":
        repository = expected_repository
        branch = configured_repository["branch"]
        cuts = {
            "source_commit": None,
            "source_tree": None,
            "evidence_commit": None,
            "evidence_tree": None,
        }
        task_subject_sha256 = None
    else:
        repository = receipt["repository"]
        branch = receipt["branch"]
        cuts = {
            field: receipt[field]
            for field in (
                "source_commit",
                "source_tree",
                "evidence_commit",
                "evidence_tree",
            )
        }
        task_specific_subject = (
            receipt["task_subject"] if receipt_kind == "passing" else None
        )
        task_subject_sha256 = (
            _canonical_sha256(task_specific_subject)
            if task_specific_subject is not None
            else None
        )
    return {
        "schema": LOCAL_TRANSITION_SUBJECT_SCHEMA,
        "receipt_kind": receipt_kind,
        "task_id": task["id"],
        "from": transition["from"],
        "to": transition["to"],
        "requirement_acceptance_sha256": _requirement_acceptance_sha256(task),
        "repository": repository,
        "branch": branch,
        **cuts,
        "dependency_receipts": receipt["dependency_receipts"],
        "task_subject_sha256": task_subject_sha256,
        "correlation_id": transition["correlation_id"],
    }


def _validate_local_transition_subject(
    task: dict[str, Any],
    transition: dict[str, Any],
    receipt: dict[str, Any],
    repository_by_name: Mapping[str, dict[str, Any]],
    path: str,
) -> None:
    expected = _expected_local_transition_subject(
        task,
        transition,
        receipt,
        repository_by_name,
    )
    if receipt["transition_subject"] != expected:
        _fail(
            f"{path} does not bind the exact task, transition, requirement, "
            "repository, cuts, dependencies, subject generation, and correlation"
        )


def _passing_generation_identity(receipt: dict[str, Any]) -> dict[str, Any]:
    subject = receipt["transition_subject"]
    return {
        "repository": receipt["repository"],
        "branch": receipt["branch"],
        "source_commit": receipt["source_commit"],
        "source_tree": receipt["source_tree"],
        "requirement_acceptance_sha256": subject["requirement_acceptance_sha256"],
        "task_subject_sha256": subject["task_subject_sha256"],
    }


def _advance_passing_generation(
    current: dict[str, Any] | None,
    receipt: dict[str, Any],
    path: str,
) -> dict[str, Any]:
    observed = _passing_generation_identity(receipt)
    if current is not None and observed != current:
        _fail(
            f"{path} changes the pass-class source or subject generation "
            "without an IN_PROGRESS reopen"
        )
    return observed


def _latest_passing_receipt(task: dict[str, Any]) -> dict[str, Any] | None:
    for transition in reversed(task.get("transitions", [])):
        if transition.get("to") in {
            "LOCAL_PASS",
            "EXTERNAL_PASS",
            "INDEPENDENT_PASS",
            "COMPLETE",
        }:
            receipt = transition.get("receipt")
            return (
                receipt
                if isinstance(receipt, dict) and receipt.get("kind") == "passing"
                else None
            )
    return None


def _dependency_state_before(
    task: dict[str, Any], cutoff: datetime
) -> tuple[str, set[str], dict[str, Any] | None]:
    state = "OPEN"
    reached: set[str] = set()
    active_receipt: dict[str, Any] | None = None
    for index, transition in enumerate(task.get("transitions", [])):
        transition_time = _parse_timestamp(
            transition["timestamp_utc"],
            f"task {task['id']} transition {index} timestamp",
        )
        if transition_time >= cutoff:
            break
        state = transition["to"]
        if state == "IN_PROGRESS":
            reached.clear()
            active_receipt = None
        if state in {
            "LOCAL_PASS",
            "EXTERNAL_PASS",
            "INDEPENDENT_PASS",
            "COMPLETE",
        }:
            reached.add(state)
            receipt = transition.get("receipt")
            active_receipt = (
                receipt
                if isinstance(receipt, dict) and receipt.get("kind") == "passing"
                else None
            )
    return state, reached, active_receipt


def _reached_evidence_floor(required: str, reached: set[str]) -> bool:
    if required == "LOCAL":
        return bool(reached & {"LOCAL_PASS", "COMPLETE"})
    return False


def _file_sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while chunk := handle.read(1024 * 1024):
            digest.update(chunk)
    return digest.hexdigest()


def _require_registry_gate() -> None:
    try:
        result = subprocess.run(  # noqa: S603
            [
                sys.executable,
                str(DECISION_REGISTRY_GENERATOR),
                "--check",
                "--require-all-accepted",
            ],
            cwd=ROOT,
            check=False,
            capture_output=True,
            timeout=30,
            text=True,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        _fail(f"B01 cannot run the exact decision-registry gate: {error}")
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip() or "gate failed"
        _fail(f"B01 exact decision-registry gate failed: {detail}")


def _run_exact_python_gate(script: Path, arguments: list[str], label: str) -> None:
    try:
        result = subprocess.run(  # noqa: S603
            [sys.executable, str(script), *arguments],
            cwd=ROOT,
            env=_git_environment(),
            check=False,
            capture_output=True,
            timeout=60,
            text=True,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        _fail(f"{label} could not run: {error}")
    if result.returncode != 0:
        detail = result.stderr.strip() or result.stdout.strip() or "gate failed"
        _fail(f"{label} failed: {detail}")


def _require_n01_promotion_gates() -> None:
    _run_exact_python_gate(
        DECISION_REGISTRY_PROMOTION_GENERATOR,
        ["--check", "--self-test"],
        "N01 exact decision-registry promotion gate",
    )
    _run_exact_python_gate(
        ROOT / "scripts" / "generate_contract_manifest.py",
        ["--self-test"],
        "N01 exact normative-manifest gate",
    )


def _source_file_identity(
    receipt: dict[str, Any],
    path: Path,
    label: str,
) -> tuple[str, int]:
    relative = path.relative_to(ROOT).as_posix()
    content = _receipt_source_bytes(receipt, relative, label)
    return hashlib.sha256(content).hexdigest(), len(content)


def _checked_decision_registry(
    *,
    require_gate: bool,
    receipt: dict[str, Any] | None = None,
) -> dict[str, Any]:
    if require_gate:
        _require_registry_gate()
    if receipt is None:
        registry = _load_bounded_json_file(
            DECISION_REGISTRY,
            "B01 generated decision registry",
        )
    else:
        registry = _load_bounded_json_bytes(
            _receipt_source_bytes(
                receipt,
                DECISION_REGISTRY.relative_to(ROOT).as_posix(),
                "B01 generated decision registry",
            ),
            "B01 generated decision registry",
        )
    if (
        registry.get("schema") != "ncp.proposed-decision-registry.v1"
        or registry.get("normative") is not False
        or registry.get("candidate") != "1.0.0-rc.1"
        or registry.get("wire_version") != "1.0"
        or registry.get("promotion_blocked") is not True
    ):
        _fail("B01 decision registry crosses its non-normative claim boundary")
    counts = registry.get("counts")
    decisions = registry.get("decisions")
    if (
        not isinstance(counts, dict)
        or counts.get("accepted") != 11
        or counts.get("proposed") != 0
        or not isinstance(decisions, list)
        or [decision.get("id") for decision in decisions]
        != [f"ADR-{number:03d}" for number in range(1, 12)]
        or any(
            decision.get("status") != "ACCEPTED"
            or decision.get("acceptance_blockers") != []
            for decision in decisions
        )
    ):
        _fail("B01 task subject requires all eleven exact ADRs to be accepted")
    lifecycle = registry.get("review_packet_lifecycle")
    packet_subject = registry.get("review_packet_subject")
    if lifecycle != {
        "schema": "ncp.b01-review-packet-lifecycle.v1",
        "state": "CURRENT",
    } or not isinstance(packet_subject, dict):
        _fail("B01 task subject requires one CURRENT review packet subject")
    for identity_key, expected_path in (
        ("source", DECISION_REGISTRY_SOURCE),
        ("review_packet", DECISION_REVIEW_PACKET),
    ):
        identity = registry.get(identity_key)
        expected_digest, expected_bytes = (
            _source_file_identity(
                receipt,
                expected_path,
                f"B01 registry {identity_key}",
            )
            if receipt is not None
            else (_file_sha256(expected_path), expected_path.stat().st_size)
        )
        if (
            not isinstance(identity, dict)
            or identity.get("path") != expected_path.relative_to(ROOT).as_posix()
            or identity.get("sha256") != expected_digest
            or identity.get("bytes") != expected_bytes
        ):
            _fail(f"B01 registry {identity_key} identity is stale")
    policy = registry.get("review_policy")
    if not isinstance(policy, dict):
        _fail("B01 registry review policy is missing")
    for identity_key, expected_path in (
        ("generator", DECISION_REGISTRY_GENERATOR),
        ("output_json_schema", DECISION_REGISTRY_SCHEMA),
    ):
        identity = policy.get(identity_key)
        expected_digest, expected_bytes = (
            _source_file_identity(
                receipt,
                expected_path,
                f"B01 review-policy {identity_key}",
            )
            if receipt is not None
            else (_file_sha256(expected_path), expected_path.stat().st_size)
        )
        if (
            not isinstance(identity, dict)
            or identity.get("path") != expected_path.relative_to(ROOT).as_posix()
            or identity.get("sha256") != expected_digest
            or identity.get("bytes") != expected_bytes
        ):
            _fail(f"B01 review-policy {identity_key} identity is stale")
    return registry


def _validate_retained_external_receipt(
    value: Any,
    path: str,
    *,
    receipt: dict[str, Any],
    forbidden_artifact_paths: set[str],
    required_prefix: str,
) -> tuple[str, str, str]:
    if not isinstance(value, dict):
        _fail(f"{path} must be a retained evidence-reference object")
    _exact_keys(value, {"url", "path", "sha256", "bytes", "media_type"}, path)
    url = _validate_https_url(value["url"], f"{path}.url")
    relative = _relative_path(value["path"], f"{path}.path")
    if not relative.startswith(required_prefix):
        _fail(f"{path}.path must be retained under {required_prefix}")
    if relative in forbidden_artifact_paths:
        _fail(f"{path}.path must be separate from every local decision artifact")
    digest = _hex(value["sha256"], HEX64, f"{path}.sha256")
    byte_count = _integer(value["bytes"], f"{path}.bytes", minimum=1)
    if byte_count > MAX_EVIDENCE_FILE_BYTES:
        _fail(f"{path}.bytes exceeds the retained-evidence bound")
    media_type = _string(value["media_type"], f"{path}.media_type", maximum=128)
    if not MEDIA_TYPE.fullmatch(media_type):
        _fail(f"{path}.media_type is not a bounded lowercase media type")
    matching = [
        artifact
        for artifact in receipt["artifacts"]
        if artifact["path"] == relative
        and artifact["sha256"] == digest
        and artifact["bytes"] == byte_count
    ]
    if len(matching) != 1:
        _fail(f"{path} is not exactly content-addressed by the passing receipt")
    _require_committed_file(
        receipt,
        relative,
        digest,
        byte_count,
        path,
        cut="evidence",
    )
    return url, relative, digest


def _validate_b01_adjudication(
    artifact_path: str,
    expected_subject: dict[str, Any],
    path: str,
    *,
    receipt: dict[str, Any],
    adjudication_artifact_paths: set[str],
    not_before: datetime,
    not_after: datetime,
) -> tuple[str, str, tuple[str, str, str]]:
    value = _load_bounded_json_bytes(
        _receipt_artifact_bytes(receipt, artifact_path, path),
        path,
    )
    _exact_keys(
        value,
        {
            "schema",
            "adjudication_id",
            "adjudicator_identity",
            "implementation_owner_identities",
            "independence_claimed",
            "decision",
            "subject",
            "role_authority_reviewed",
            "independence_evidence_reviewed",
            "external_receipt",
            "timestamp_utc",
        },
        path,
    )
    if value["schema"] != "ncp.b01-external-adjudication.v1":
        _fail(f"{path}.schema is not the B01 external-adjudication schema")
    adjudication_id = _string(
        value["adjudication_id"], f"{path}.adjudication_id", maximum=128
    )
    identity = _validate_identity_uri(
        value["adjudicator_identity"], f"{path}.adjudicator_identity"
    )
    owners = value["implementation_owner_identities"]
    if (
        not isinstance(owners, list)
        or not owners
        or len(owners) > 32
        or len(owners) != len(set(owners))
    ):
        _fail(f"{path}.implementation_owner_identities must contain 1..32 identities")
    for index, owner in enumerate(owners):
        _validate_identity_uri(
            owner, f"{path}.implementation_owner_identities[{index}]"
        )
    if owners != expected_subject["implementation_owner_identities"]:
        _fail(
            f"{path}.implementation_owner_identities differs from the exact "
            "accepted-registry owner universe"
        )
    if identity in owners:
        _fail(f"{path} cannot count an implementation owner as an adjudicator")
    if (
        value["independence_claimed"] is not True
        or value["decision"] != "PASS"
        or value["role_authority_reviewed"] is not True
        or value["independence_evidence_reviewed"] is not True
    ):
        _fail(f"{path} does not record a qualifying external adjudication")
    if value["subject"] != expected_subject:
        _fail(f"{path}.subject differs from the exact B01 review subject")
    external_receipt = _validate_retained_external_receipt(
        value["external_receipt"],
        f"{path}.external_receipt",
        receipt=receipt,
        forbidden_artifact_paths=adjudication_artifact_paths,
        required_prefix="evidence/implementation/reviews/B01/",
    )
    adjudicated_at = _parse_timestamp(value["timestamp_utc"], f"{path}.timestamp_utc")
    if not not_before < adjudicated_at < not_after:
        _fail(
            f"{path}.timestamp_utc must be strictly later than every qualifying "
            "review and strictly earlier than the passing receipt"
        )
    return adjudication_id, identity, external_receipt


def _b01_role_coverage_sha256(registry: dict[str, Any]) -> str:
    projection: list[dict[str, Any]] = []
    records = registry["review_records"]
    for decision in registry["decisions"]:
        roles: list[dict[str, Any]] = []
        for requirement in decision["required_reviews"]:
            qualifying = sorted(
                (
                    {
                        "review_id": record["review_id"],
                        "reviewer_identity": record["reviewer"]["identity"],
                        "reviewer_identity_kind": record["reviewer"]["identity_kind"],
                        "implementation_owner_identities": record["reviewer"][
                            "implementation_owner_identities"
                        ],
                        "independence_claimed": record["reviewer"][
                            "independence_claimed"
                        ],
                        "role_authorization_sha256": record["role_authorization"][
                            "sha256"
                        ],
                        "independence_assessment_sha256": (
                            record["independence_assessment"]["sha256"]
                            if record["independence_assessment"] is not None
                            else None
                        ),
                        "external_receipt_sha256": record["external_receipt"]["sha256"],
                    }
                    for record in records
                    if record["adr_id"] == decision["id"]
                    and record["role_id"] == requirement["role_id"]
                    and record.get("derived", {}).get("qualifying_acceptance") is True
                ),
                key=lambda item: item["review_id"],
            )
            identities = {item["reviewer_identity"] for item in qualifying}
            if len(identities) < requirement["min_distinct_identities"]:
                _fail(
                    "B01 accepted registry lacks exact distinct-identity role "
                    f"coverage for {decision['id']}/{requirement['role_id']}"
                )
            if requirement["requires_independence"] and any(
                not item["independence_claimed"] for item in qualifying
            ):
                _fail(
                    "B01 accepted registry counts a non-independent review for "
                    f"{decision['id']}/{requirement['role_id']}"
                )
            roles.append(
                {
                    "role_id": requirement["role_id"],
                    "min_distinct_identities": requirement["min_distinct_identities"],
                    "requires_independence": requirement["requires_independence"],
                    "qualifying_reviews": qualifying,
                }
            )
        projection.append({"adr_id": decision["id"], "roles": roles})
    return _canonical_sha256(projection)


def _b01_implementation_owner_identities(registry: dict[str, Any]) -> list[str]:
    owners = sorted(
        {
            owner
            for record in registry["review_records"]
            if record.get("derived", {}).get("qualifying_acceptance") is True
            for owner in record["reviewer"]["implementation_owner_identities"]
        }
    )
    if not owners:
        _fail("B01 accepted registry lacks an implementation-owner identity universe")
    return owners


def _registry_review_evidence_components(
    registry: dict[str, Any],
) -> tuple[set[str], set[str], set[str]]:
    urls: set[str] = set()
    paths: set[str] = set()
    digests: set[str] = set()

    def collect(value: Any) -> None:
        if isinstance(value, dict):
            if {"url", "path", "sha256", "bytes", "media_type"} <= set(value):
                urls.add(value["url"])
                paths.add(value["path"])
                digests.add(value["sha256"])
            for child in value.values():
                collect(child)
        elif isinstance(value, list):
            for child in value:
                collect(child)

    collect(registry["review_records"])
    return urls, paths, digests


def _registry_review_evidence_identities(
    registry: dict[str, Any],
) -> list[dict[str, Any]]:
    """Return one exact retained-file identity for every registry review reference."""
    by_path: dict[str, dict[str, Any]] = {}

    def collect(value: Any, path: str) -> None:
        if isinstance(value, dict):
            if set(value) == {"url", "path", "sha256", "bytes", "media_type"}:
                relative = _relative_path(value["path"], f"{path}.path")
                identity = {
                    "path": relative,
                    "sha256": _hex(value["sha256"], HEX64, f"{path}.sha256"),
                    "bytes": _integer(value["bytes"], f"{path}.bytes", minimum=1),
                }
                if identity["bytes"] > MAX_EVIDENCE_FILE_BYTES:
                    _fail(f"{path}.bytes exceeds the retained-evidence bound")
                existing = by_path.get(relative)
                if existing is not None and existing != identity:
                    _fail(
                        "B01 registry review evidence gives one retained path "
                        "conflicting content identities"
                    )
                by_path[relative] = identity
            for key, child in value.items():
                collect(child, f"{path}.{key}")
        elif isinstance(value, list):
            for index, child in enumerate(value):
                collect(child, f"{path}[{index}]")

    collect(registry["review_records"], "B01 registry.review_records")
    return [by_path[relative] for relative in sorted(by_path)]


def _require_registry_review_evidence_at_receipt_commit(
    registry: dict[str, Any], receipt: dict[str, Any]
) -> None:
    identities = _registry_review_evidence_identities(registry)
    if not identities:
        _fail("B01 accepted registry retains no review evidence")
    for index, identity in enumerate(identities):
        content = _receipt_source_bytes(
            receipt,
            identity["path"],
            f"B01 registry review evidence {index}",
        )
        if (
            len(content) != identity["bytes"]
            or hashlib.sha256(content).hexdigest() != identity["sha256"]
        ):
            _fail(
                f"B01 registry review evidence {index} differs from its "
                "content-addressed source-cut file"
            )


def _require_non_normative_receipt_digest(receipt: dict[str, Any], label: str) -> None:
    before = receipt["normative_digest_before"]
    after = receipt["normative_digest_after"]
    if before is None or after is None or before != after:
        _fail(f"{label} cannot change or omit the normative contract digest")


def _validate_b01_task_subject(
    task_subject: dict[str, Any],
    receipt: dict[str, Any],
    *,
    promoted: bool,
) -> None:
    _require_non_normative_receipt_digest(receipt, "B01")
    registry = _checked_decision_registry(
        require_gate=not promoted,
        receipt=receipt,
    )
    registry_sha256, _ = _source_file_identity(
        receipt,
        DECISION_REGISTRY,
        "B01 generated decision registry",
    )
    for current_path, label in (
        (DECISION_REGISTRY, "B01 generated decision registry"),
        (DECISION_REGISTRY_SOURCE, "B01 decision-registry source"),
        (DECISION_REGISTRY_GENERATOR, "B01 decision-registry generator"),
        (DECISION_REGISTRY_SCHEMA, "B01 decision-registry output schema"),
        (DECISION_REVIEW_PACKET, "B01 immutable review packet"),
    ):
        _require_current_file_at_receipt_commit(receipt, current_path, label)
    _require_registry_review_evidence_at_receipt_commit(registry, receipt)
    packet_subject = registry["review_packet_subject"]
    source = packet_subject["source"]
    _require_strict_git_ancestor(
        receipt["repository"],
        source["commit"],
        receipt["source_commit"],
        "B01 zero-review packet source commit",
    )
    qualifying_ids = sorted(
        record["review_id"]
        for record in registry["review_records"]
        if record.get("derived", {}).get("qualifying_acceptance") is True
    )
    qualifying_records = [
        record
        for record in registry["review_records"]
        if record.get("derived", {}).get("qualifying_acceptance") is True
    ]
    qualifying_times = [
        _parse_timestamp(record["timestamp_utc"], "B01 qualifying-review timestamp")
        for record in qualifying_records
    ]
    qualifying_times.extend(
        _parse_timestamp(
            condition["closure"]["timestamp_utc"],
            "B01 qualifying condition-closure timestamp",
        )
        for record in qualifying_records
        for condition in record["conditions"]
        if condition["closure"] is not None
    )
    if not qualifying_times:
        _fail("B01 accepted registry lacks qualifying review timestamps")
    last_qualifying_review = max(qualifying_times)
    receipt_time = _parse_timestamp(receipt["timestamp_utc"], "B01 receipt timestamp")
    expected = {
        "registry_path": DECISION_REGISTRY.relative_to(ROOT).as_posix(),
        "registry_sha256": registry_sha256,
        "decision_set_sha256": registry["decision_set"]["sha256"],
        "review_policy_sha256": _canonical_sha256(registry["review_policy"]),
        "review_packet_path": DECISION_REVIEW_PACKET.relative_to(ROOT).as_posix(),
        "review_packet_sha256": registry["review_packet"]["sha256"],
        "source_commit": source["commit"],
        "source_tree": source["tree"],
        "accepted_adr_ids": [f"ADR-{number:03d}" for number in range(1, 12)],
        "qualifying_review_ids": qualifying_ids,
        "role_coverage_sha256": _b01_role_coverage_sha256(registry),
    }
    for field, value in expected.items():
        if task_subject[field] != value:
            _fail(f"B01 task subject {field} differs from the accepted registry")
    artifact_paths = {artifact["path"] for artifact in receipt["artifacts"]}
    adjudication_ids: set[str] = set()
    adjudicator_identities: set[str] = set()
    adjudication_receipt_urls: set[str] = set()
    adjudication_receipt_paths: set[str] = set()
    adjudication_receipt_digests: set[str] = set()
    (
        registry_evidence_urls,
        registry_evidence_paths,
        registry_evidence_digests,
    ) = _registry_review_evidence_components(registry)
    adjudication_subject = {
        **expected,
        "implementation_owner_identities": (
            _b01_implementation_owner_identities(registry)
        ),
    }
    for index, artifact_path in enumerate(task_subject["adjudication_artifacts"]):
        if artifact_path not in artifact_paths:
            _fail("B01 adjudication artifact is not bound by the passing receipt")
        _require_receipt_artifact_at_evidence_commit(
            receipt,
            artifact_path,
            f"B01 adjudication artifact {index}",
        )
        adjudication_id, identity, external_receipt = _validate_b01_adjudication(
            artifact_path,
            adjudication_subject,
            f"B01 adjudication artifact {index}",
            receipt=receipt,
            adjudication_artifact_paths=set(task_subject["adjudication_artifacts"]),
            not_before=last_qualifying_review,
            not_after=receipt_time,
        )
        receipt_url, receipt_path, receipt_digest = external_receipt
        if (
            adjudication_id in adjudication_ids
            or identity in adjudicator_identities
            or receipt_url in adjudication_receipt_urls
            or receipt_url in registry_evidence_urls
            or receipt_path in adjudication_receipt_paths
            or receipt_path in registry_evidence_paths
            or receipt_digest in adjudication_receipt_digests
            or receipt_digest in registry_evidence_digests
        ):
            _fail(
                "B01 external adjudications must use distinct IDs, identities, "
                "and receipt URLs, paths, and byte digests that no registry "
                "review evidence reuses"
            )
        adjudication_ids.add(adjudication_id)
        adjudicator_identities.add(identity)
        adjudication_receipt_urls.add(receipt_url)
        adjudication_receipt_paths.add(receipt_path)
        adjudication_receipt_digests.add(receipt_digest)
    if len(adjudicator_identities) < INDEPENDENT_REVIEWER_MINIMUM["B01"]:
        _fail("B01 lacks the required distinct external adjudication identities")


def _require_b02_b01_ratification_binding(
    task_subject: dict[str, Any], b01_receipt: dict[str, Any]
) -> str:
    expected = _receipt_sha256(b01_receipt)
    if task_subject["b01_ratification_receipt_sha256"] != expected:
        _fail(
            "B02 owner authorization is detached from the exact B01 "
            "ratification receipt generation"
        )
    return expected


def _b02_reserved_external_receipt_components(
    registry: dict[str, Any], b01_receipt: dict[str, Any]
) -> list[set[Any]]:
    reserved_components = list(_registry_review_evidence_components(registry))
    for index, artifact_path in enumerate(
        b01_receipt["task_subject"]["adjudication_artifacts"]
    ):
        adjudication = _load_bounded_json_bytes(
            _receipt_artifact_bytes(
                b01_receipt,
                artifact_path,
                f"B01 predecessor adjudication {index}",
            ),
            f"B01 predecessor adjudication {index}",
        )
        external_receipt = adjudication.get("external_receipt")
        if not isinstance(external_receipt, dict):
            continue
        for field_index, field in enumerate(("url", "path", "sha256")):
            reserved_components[field_index].add(external_receipt.get(field))
    return reserved_components


def _validate_b02_task_subject(
    task_subject: dict[str, Any],
    receipt: dict[str, Any],
    b01_receipt: dict[str, Any],
    *,
    promoted: bool,
    started_at: datetime,
) -> None:
    _require_non_normative_receipt_digest(receipt, "B02")
    b01_receipt_sha256 = _require_b02_b01_ratification_binding(
        task_subject, b01_receipt
    )
    registry = _checked_decision_registry(
        require_gate=not promoted,
        receipt=receipt,
    )
    registry_sha256, _ = _source_file_identity(
        receipt,
        DECISION_REGISTRY,
        "B02 accepted decision registry",
    )
    for current_path, label in (
        (DECISION_REGISTRY, "B02 accepted decision registry"),
        (DECISION_REGISTRY_SOURCE, "B02 decision-registry source"),
        (DECISION_REGISTRY_GENERATOR, "B02 decision-registry generator"),
        (DECISION_REGISTRY_SCHEMA, "B02 decision-registry output schema"),
        (DECISION_REVIEW_PACKET, "B02 immutable review packet"),
    ):
        _require_current_file_at_receipt_commit(receipt, current_path, label)
    packet_source = registry["review_packet_subject"]["source"]
    expected = {
        "registry_path": DECISION_REGISTRY.relative_to(ROOT).as_posix(),
        "registry_sha256": registry_sha256,
        "decision_set_sha256": registry["decision_set"]["sha256"],
        "review_policy_sha256": _canonical_sha256(registry["review_policy"]),
        "review_packet_path": DECISION_REVIEW_PACKET.relative_to(ROOT).as_posix(),
        "review_packet_sha256": registry["review_packet"]["sha256"],
        "source_commit": packet_source["commit"],
        "source_tree": packet_source["tree"],
        "b01_ratification_receipt_sha256": b01_receipt_sha256,
    }
    for field, value in expected.items():
        if task_subject[field] != value:
            _fail(f"B02 task subject {field} differs from the accepted registry")
    artifact_path = task_subject["authorization_artifact"]
    if artifact_path not in {artifact["path"] for artifact in receipt["artifacts"]}:
        _fail("B02 authorization artifact is not bound by the passing receipt")
    _require_receipt_artifact_at_evidence_commit(
        receipt, artifact_path, "B02 owner-authorization artifact"
    )
    authorization = _load_bounded_json_bytes(
        _receipt_artifact_bytes(
            receipt,
            artifact_path,
            "B02 owner-authorization artifact",
        ),
        "B02 owner-authorization artifact",
    )
    _exact_keys(
        authorization,
        {
            "schema",
            "authorization_id",
            "authorizer_identity",
            "authorizer_role",
            "decision",
            "subject",
            "external_receipt",
            "timestamp_utc",
        },
        "B02 owner-authorization artifact",
    )
    if (
        authorization["schema"] != "ncp.b02-owner-rebaseline-authorization.v1"
        or authorization["authorizer_role"] != "candidate-rebaseline-owner"
        or authorization["decision"] != "AUTHORIZE"
    ):
        _fail("B02 artifact is not an owner rebaseline authorization")
    _string(
        authorization["authorization_id"],
        "B02 owner-authorization artifact.authorization_id",
        maximum=128,
    )
    _validate_identity_uri(
        authorization["authorizer_identity"],
        "B02 owner-authorization artifact.authorizer_identity",
    )
    expected_authorization_subject = {
        **expected,
        "candidate": "1.0.0-rc.1",
        "wire_version": "1.0",
    }
    if authorization["subject"] != expected_authorization_subject:
        _fail("B02 authorization artifact binds the wrong candidate subject")
    authorization_external_receipt = _validate_retained_external_receipt(
        authorization["external_receipt"],
        "B02 owner-authorization artifact.external_receipt",
        receipt=receipt,
        forbidden_artifact_paths={artifact_path},
        required_prefix="evidence/implementation/reviews/B02/",
    )
    reserved_components = _b02_reserved_external_receipt_components(
        registry, b01_receipt
    )
    if any(
        authorization_external_receipt[field_index] in reserved_components[field_index]
        for field_index in range(3)
    ):
        _fail(
            "B02 owner authorization cannot reuse a B01 registry-review or "
            "adjudication receipt URL, path, or byte digest"
        )
    authorized_at = _parse_timestamp(
        authorization["timestamp_utc"],
        "B02 owner-authorization artifact.timestamp_utc",
    )
    b02_receipt_time = _parse_timestamp(
        receipt["timestamp_utc"], "B02 receipt timestamp"
    )
    if not started_at < authorized_at < b02_receipt_time:
        _fail(
            "B02 owner authorization must be strictly later than the "
            "dependency-ready B02 start and strictly earlier than the passing receipt"
        )


def _decode_rfc6901_pointer(value: Any, path: str) -> list[str]:
    pointer = _string(value, path, maximum=2048)
    if not pointer.startswith("/"):
        _fail(f"{path} must be a non-root RFC 6901 JSON pointer")
    encoded_tokens = pointer[1:].split("/")
    if not 1 <= len(encoded_tokens) <= 32 or any(
        token == "" for token in encoded_tokens
    ):
        _fail(f"{path} must contain 1..32 nonempty JSON-pointer tokens")
    decoded_tokens: list[str] = []
    for index, encoded in enumerate(encoded_tokens):
        if re.search(r"~(?![01])", encoded):
            _fail(f"{path} token {index} contains a non-RFC6901 escape")
        decoded = encoded.replace("~1", "/").replace("~0", "~")
        canonical = decoded.replace("~", "~0").replace("/", "~1")
        if encoded != canonical:
            _fail(f"{path} token {index} is not canonical RFC 6901")
        _string(decoded, f"{path} token {index}", maximum=256)
        if decoded != decoded.strip() or any(
            ord(character) < 0x20 for character in decoded
        ):
            _fail(f"{path} token {index} contains ambiguous whitespace or controls")
        decoded_tokens.append(decoded)
    return decoded_tokens


def _resolve_rfc6901_pointer(document: Any, pointer: Any, path: str) -> Any:
    current = document
    for index, token in enumerate(_decode_rfc6901_pointer(pointer, path)):
        if isinstance(current, dict):
            if token not in current:
                _fail(f"{path} token {index} does not resolve")
            current = current[token]
        elif isinstance(current, list):
            if not re.fullmatch(r"0|[1-9][0-9]*", token):
                _fail(f"{path} token {index} is not a canonical array index")
            item_index = int(token)
            if item_index >= len(current):
                _fail(f"{path} token {index} is outside the array")
            current = current[item_index]
        else:
            _fail(f"{path} token {index} traverses a scalar")
    return current


def _decode_b03_codeowners(raw: bytes, path: str) -> list[str]:
    if not 1 <= len(raw) <= MAX_CODEOWNERS_BYTES:
        _fail(f"{path} must contain 1..{MAX_CODEOWNERS_BYTES} bytes")
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        _fail(f"{path} must be valid UTF-8: {error}")
    if "\x00" in text or "\r" in text or not text.isascii():
        _fail(f"{path} must use unambiguous ASCII LF text without NUL")
    lines = text.splitlines()
    if len(lines) > MAX_CODEOWNERS_LINES:
        _fail(f"{path} exceeds the bounded line count")
    return lines


def _b03_codeowners_line_content(line: str, path: str) -> str:
    if len(line.encode("ascii")) > 4096:
        _fail(f"{path} exceeds 4096 bytes")
    comment_index = line.find("#")
    if (
        comment_index > 0
        and line[:comment_index].strip()
        and not line[comment_index - 1].isspace()
    ):
        _fail(f"{path} contains an ambiguous inline #")
    return (line[:comment_index] if comment_index >= 0 else line).strip()


def _validate_b03_codeowners_pattern(pattern: str, path: str) -> None:
    if (
        not pattern.isascii()
        or any(not 0x21 <= ord(character) <= 0x7E for character in pattern)
        or pattern.startswith("!")
        or "\\" in pattern
        or "[" in pattern
        or "]" in pattern
        or "//" in pattern
    ):
        _fail(
            f"{path} uses unsupported negation, escaping, range, "
            "or ambiguous pattern syntax"
        )
    normalized = pattern.removeprefix("/")
    directory_suffix = normalized.endswith("/")
    normalized = normalized.removesuffix("/")
    components = normalized.split("/")
    if (
        not normalized
        or any(component in {"", ".", ".."} for component in components)
        or any("**" in component and component != "**" for component in components)
        or "**" in components[:-1]
    ):
        _fail(f"{path} has a non-canonical or unsupported pattern")
    if directory_suffix and components[-1] == "**":
        _fail(f"{path} redundantly combines a directory suffix and **")


def _validate_b03_codeowners_owners(owners: list[str], path: str) -> tuple[str, ...]:
    for owner_index, owner in enumerate(owners):
        if not B03_CODEOWNER_TOKEN.fullmatch(owner):
            _fail(
                f"{path} owner {owner_index} must be one canonical "
                "lowercase GitHub user or organization-team token"
            )
    if len(owners) != len(set(owners)):
        _fail(f"{path} contains a duplicate owner token")
    return tuple(sorted(owners))


def _parse_b03_codeowners(raw: bytes, path: str) -> list[tuple[str, tuple[str, ...]]]:
    rules: list[tuple[str, tuple[str, ...]]] = []
    for line_number, line in enumerate(_decode_b03_codeowners(raw, path), start=1):
        line_path = f"{path} line {line_number}"
        content = _b03_codeowners_line_content(line, line_path)
        if not content:
            continue
        tokens = content.split()
        pattern = tokens[0]
        owners = tokens[1:]
        _validate_b03_codeowners_pattern(pattern, line_path)
        rules.append((pattern, _validate_b03_codeowners_owners(owners, line_path)))
    if not rules:
        _fail(f"{path} contains no ownership rules")
    return rules


def _b03_codeowners_component_matches(pattern: str, value: str) -> bool:
    expression = ""
    for character in pattern:
        if character == "*":
            expression += ".*"
        elif character == "?":
            expression += "."
        else:
            expression += re.escape(character)
    return re.fullmatch(expression, value) is not None


def _b03_codeowners_pattern_matches(pattern: str, target: str) -> bool:
    normalized = pattern.removeprefix("/")
    directory_suffix = normalized.endswith("/")
    normalized = normalized.removesuffix("/")
    pattern_components = normalized.split("/")
    if pattern_components[-1] == "**":
        directory_suffix = True
        pattern_components = pattern_components[:-1]
    target_components = target.split("/")
    if len(pattern_components) == 1 and "/" not in normalized:
        return any(
            _b03_codeowners_component_matches(pattern_components[0], component)
            for component in target_components
        )
    if directory_suffix:
        return len(target_components) > len(pattern_components) and all(
            _b03_codeowners_component_matches(expected, actual)
            for expected, actual in zip(
                pattern_components, target_components, strict=False
            )
        )
    if all(
        "*" not in component and "?" not in component
        for component in pattern_components
    ) and len(target_components) > len(pattern_components):
        return target_components[: len(pattern_components)] == pattern_components
    return len(pattern_components) == len(target_components) and all(
        _b03_codeowners_component_matches(expected, actual)
        for expected, actual in zip(pattern_components, target_components, strict=True)
    )


def _b03_effective_codeowners(
    rules: list[tuple[str, tuple[str, ...]]], target: str
) -> tuple[str, ...]:
    effective: tuple[str, ...] = ()
    matched = False
    for pattern, owners in rules:
        if _b03_codeowners_pattern_matches(pattern, target):
            matched = True
            effective = owners
    if not matched:
        return ()
    return effective


def _validate_b03_canonical_id_list(
    value: Any,
    path: str,
    *,
    minimum: int,
    maximum: int,
    pattern: re.Pattern[str] = ALLOCATION_INVARIANT_ID,
    allowed: set[str] | None = None,
) -> list[str]:
    if (
        not isinstance(value, list)
        or not minimum <= len(value) <= maximum
        or value != sorted(value)
        or len(value) != len(set(value))
    ):
        _fail(
            f"{path} must contain {minimum}..{maximum} unique canonical "
            "sorted identities"
        )
    checked: list[str] = []
    for index, member in enumerate(value):
        identity = _string(member, f"{path}[{index}]", maximum=128)
        if not identity.isascii() or not pattern.fullmatch(identity):
            _fail(f"{path}[{index}] is not a canonical ASCII identity")
        if allowed is not None and identity not in allowed:
            _fail(f"{path}[{index}] is not in the closed allowed set")
        checked.append(identity)
    return checked


def _validate_b03_scoped_applicability(
    value: Any,
    path: str,
    *,
    scope_independent: str,
    member_key: str,
    unknown_key: str,
    allowed: set[str] | None,
) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an object")
    _exact_keys(value, {"scope", member_key, unknown_key}, path)
    scope = _string(value["scope"], f"{path}.scope", maximum=32)
    if scope not in {"LISTED", scope_independent}:
        _fail(f"{path}.scope is not a closed applicability scope")
    members = _validate_b03_canonical_id_list(
        value[member_key],
        f"{path}.{member_key}",
        minimum=1 if scope == "LISTED" else 0,
        maximum=32 if scope == "LISTED" else 0,
        pattern=B03_METADATA_IDENTIFIER,
        allowed=allowed,
    )
    if scope == "LISTED" and not members:
        _fail(f"{path} LISTED scope requires at least one member")
    if value[unknown_key] != "REJECT":
        _fail(f"{path}.{unknown_key} must be REJECT; unknown cannot grant")


def _validate_b03_wire_applicability(value: Any, path: str) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an object")
    _exact_keys(value, {"wire_versions", "unknown_wire_version_behavior"}, path)
    if value["wire_versions"] != ["1.0"]:
        _fail(f"{path}.wire_versions must equal ['1.0']")
    if value["unknown_wire_version_behavior"] != "REJECT":
        _fail(
            f"{path}.unknown_wire_version_behavior must be REJECT; unknown cannot grant"
        )


def _validate_b03_actor_applicability(value: Any, path: str) -> None:
    _validate_b03_scoped_applicability(
        value,
        path,
        scope_independent="ACTOR_INDEPENDENT",
        member_key="actors",
        unknown_key="unknown_actor_behavior",
        allowed=None,
    )
    if any(
        actor in {"all", "any", "default", "unknown", "unauthenticated"}
        for actor in value["actors"]
    ):
        _fail(f"{path} cannot use a granting catch-all actor")


def _validate_b03_authority_effect(value: Any, path: str) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an object")
    _exact_keys(
        value,
        {
            "classification",
            "authorization_precondition_ids",
            "unknown_or_unproved_behavior",
        },
        path,
    )
    classification = _string(value["classification"], f"{path}.classification")
    if classification not in B03_AUTHORITY_EFFECTS:
        _fail(f"{path}.classification is not closed")
    preconditions = _validate_b03_canonical_id_list(
        value["authorization_precondition_ids"],
        f"{path}.authorization_precondition_ids",
        minimum=0 if classification == "NO_AUTHORITY" else 1,
        maximum=0 if classification == "NO_AUTHORITY" else 32,
    )
    if classification != "NO_AUTHORITY" and not preconditions:
        _fail(f"{path} active effect needs explicit authorization preconditions")
    if value["unknown_or_unproved_behavior"] != "NO_AUTHORITY":
        _fail(
            f"{path}.unknown_or_unproved_behavior must be "
            "NO_AUTHORITY; unknown cannot grant"
        )


def _validate_b03_limits_and_bounds(value: Any, path: str) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an object")
    _exact_keys(value, {"constraint_ids", "missing_or_exceeded_behavior"}, path)
    _validate_b03_canonical_id_list(
        value["constraint_ids"],
        f"{path}.constraint_ids",
        minimum=1,
        maximum=32,
    )
    if value["missing_or_exceeded_behavior"] != "REJECT":
        _fail(
            f"{path}.missing_or_exceeded_behavior must be "
            "REJECT; missing or exceeded bounds cannot grant"
        )


def _validate_b03_unknown_and_default_behavior(value: Any, path: str) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an object")
    _exact_keys(
        value,
        {"unknown_identifier", "missing_required_metadata", "default_authority"},
        path,
    )
    expected = {
        "unknown_identifier": "REJECT",
        "missing_required_metadata": "REJECT",
        "default_authority": "NONE",
    }
    if value != expected:
        _fail(f"{path} must be fail closed")


def _validate_b03_retirement_and_migration(
    value: Any,
    path: str,
    *,
    stability: str,
    allocation_identifier: str,
) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an object")
    _exact_keys(
        value,
        {
            "state",
            "replacement_identifier",
            "migration_rule_id",
            "identifier_reuse",
            "unknown_or_stale_behavior",
        },
        path,
    )
    retirement_state = _string(value["state"], f"{path}.state", maximum=16)
    expected_state = {
        "EXPERIMENTAL": "ACTIVE",
        "CANDIDATE": "ACTIVE",
        "STABLE": "ACTIVE",
        "DEPRECATED": "DEPRECATED",
        "RETIRED": "RETIRED",
    }[stability]
    if retirement_state != expected_state:
        _fail(f"{path}.state conflicts with stability")
    replacement = value["replacement_identifier"]
    if replacement is not None:
        replacement = _string(
            replacement, f"{path}.replacement_identifier", maximum=256
        )
        invalid_replacement = (
            not replacement.isascii()
            or replacement == allocation_identifier
            or any(not 0x21 <= ord(character) <= 0x7E for character in replacement)
            or any(character in replacement for character in "*?[]{}")
        )
        if invalid_replacement:
            _fail(
                f"{path}.replacement_identifier is "
                "not one exact distinct printable ASCII identifier"
            )
    if retirement_state == "ACTIVE" and replacement is not None:
        _fail(f"{path} active entry cannot name a replacement")
    migration_rule = _string(
        value["migration_rule_id"], f"{path}.migration_rule_id", maximum=128
    )
    if not ALLOCATION_INVARIANT_ID.fullmatch(migration_rule):
        _fail(f"{path}.migration_rule_id must be canonical uppercase snake case")
    if value["identifier_reuse"] != "FORBIDDEN":
        _fail(f"{path}.identifier_reuse must be FORBIDDEN")
    if value["unknown_or_stale_behavior"] != "REJECT":
        _fail(
            f"{path}.unknown_or_stale_behavior must be "
            "REJECT; unknown or stale state cannot grant"
        )


def _validate_b03_common_allocation_metadata(
    value: Any,
    *,
    owner_identity: str,
    allocation_identifier: str,
    path: str,
) -> None:
    if not isinstance(value, dict):
        _fail(f"{path} must be an object")
    _exact_keys(
        value,
        {
            "schema",
            "owner_identity",
            "codeowner_tokens",
            "stability",
            "wire_applicability",
            "session_applicability",
            "actor_applicability",
            "plane_applicability",
            "authority_effect",
            "limits_and_bounds",
            "unknown_and_default_behavior",
            "conformance_obligations",
            "retirement_and_migration",
        },
        path,
    )
    if value["schema"] != B03_ALLOCATION_METADATA_SCHEMA:
        _fail(f"{path}.schema is not the common B03 allocation-metadata schema")
    if (
        _validate_identity_uri(value["owner_identity"], f"{path}.owner_identity")
        != owner_identity
    ):
        _fail(f"{path}.owner_identity differs from the allocation owner")
    _validate_b03_canonical_id_list(
        value["codeowner_tokens"],
        f"{path}.codeowner_tokens",
        minimum=1,
        maximum=16,
        pattern=B03_CODEOWNER_TOKEN,
    )
    stability = _string(value["stability"], f"{path}.stability", maximum=32)
    if stability not in B03_STABILITY_CLASSES:
        _fail(f"{path}.stability is not a closed stability class")

    _validate_b03_wire_applicability(
        value["wire_applicability"], f"{path}.wire_applicability"
    )
    _validate_b03_scoped_applicability(
        value["session_applicability"],
        f"{path}.session_applicability",
        scope_independent="SESSION_INDEPENDENT",
        member_key="session_types",
        unknown_key="unknown_session_type_behavior",
        allowed=B03_SESSION_TYPES,
    )
    _validate_b03_actor_applicability(
        value["actor_applicability"], f"{path}.actor_applicability"
    )
    _validate_b03_scoped_applicability(
        value["plane_applicability"],
        f"{path}.plane_applicability",
        scope_independent="PLANE_INDEPENDENT",
        member_key="planes",
        unknown_key="unknown_plane_behavior",
        allowed=B03_PLANES,
    )

    _validate_b03_authority_effect(
        value["authority_effect"], f"{path}.authority_effect"
    )
    _validate_b03_limits_and_bounds(
        value["limits_and_bounds"], f"{path}.limits_and_bounds"
    )
    _validate_b03_unknown_and_default_behavior(
        value["unknown_and_default_behavior"],
        f"{path}.unknown_and_default_behavior",
    )

    _validate_b03_canonical_id_list(
        value["conformance_obligations"],
        f"{path}.conformance_obligations",
        minimum=1,
        maximum=32,
    )

    _validate_b03_retirement_and_migration(
        value["retirement_and_migration"],
        f"{path}.retirement_and_migration",
        stability=stability,
        allocation_identifier=allocation_identifier,
    )


def _validate_b03_registry_binding(
    entry: dict[str, Any],
    *,
    registry_documents: dict[str, dict[str, Any]],
    codeowner_rules: list[tuple[str, tuple[str, ...]]],
    seen_pointers: set[tuple[str, str]],
    seen_value_digests: set[str],
    path: str,
) -> None:
    registry_path = _relative_path(entry["registry_path"], f"{path}.registry_path")
    if registry_path not in B03_JSON_REGISTRY_PATHS:
        _fail(f"{path}.registry_path is not one of the six bounded JSON registries")
    pointer = _string(
        entry["registry_pointer"], f"{path}.registry_pointer", maximum=2048
    )
    pointer_key = (registry_path, pointer)
    if pointer_key in seen_pointers:
        _fail("B03 allocations contain a duplicate or alias registry pointer")
    resolved = _resolve_rfc6901_pointer(
        registry_documents[registry_path],
        pointer,
        f"{path}.registry_pointer",
    )
    if not isinstance(resolved, dict):
        _fail(f"{path}.registry_pointer must resolve one allocation object")
    for field in ("kind", "identifier", "owner_identity"):
        if resolved.get(field) != entry[field]:
            _fail(
                f"{path}.registry_pointer resolved allocation {field} differs "
                "from the artifact entry"
            )
    _validate_b03_common_allocation_metadata(
        resolved.get("common_metadata"),
        owner_identity=entry["owner_identity"],
        allocation_identifier=entry["identifier"],
        path=f"{path}.registry_pointer resolved common_metadata",
    )
    effective_codeowners = _b03_effective_codeowners(codeowner_rules, registry_path)
    if not effective_codeowners:
        _fail(f"{path}.registry_path has no effective repository-text code owner")
    if resolved["common_metadata"]["codeowner_tokens"] != list(effective_codeowners):
        _fail(
            f"{path}.registry_pointer resolved common_metadata.codeowner_tokens "
            "differs from the effective last-matching CODEOWNERS rule"
        )
    expected_digest = _hex(
        entry["registry_value_sha256"],
        HEX64,
        f"{path}.registry_value_sha256",
    )
    actual_digest = _canonical_sha256(resolved)
    if expected_digest != actual_digest:
        _fail(f"{path}.registry_value_sha256 differs from the resolved registry value")
    if actual_digest in seen_value_digests:
        _fail("B03 allocations contain a duplicate or aliased registry value")
    seen_pointers.add(pointer_key)
    seen_value_digests.add(actual_digest)


def _validate_b03_allocation_coverage(keys: set[tuple[str, str]]) -> None:
    allocation_kinds = {kind for kind, _identifier in keys}
    missing_kinds = B03_REQUIRED_ALLOCATION_KINDS - allocation_kinds
    if missing_kinds:
        _fail(
            "B03 allocations omit required bounded allocation kinds: "
            f"{sorted(missing_kinds)}"
        )
    missing_identifiers = B03_REQUIRED_ALLOCATION_IDENTIFIERS - keys
    if missing_identifiers:
        _fail(
            "B03 allocations omit required closed allocation identifiers: "
            f"{sorted(missing_identifiers)}"
        )
    for kind, exact_identifiers in B03_EXACT_CLOSED_IDENTIFIER_SETS.items():
        observed_identifiers = {
            identifier
            for allocation_kind, identifier in keys
            if allocation_kind == kind
        }
        if observed_identifiers != exact_identifiers:
            _fail(
                f"B03 allocations for closed kind {kind} must equal "
                f"{sorted(exact_identifiers)} exactly"
            )


def _validate_b03_allocation_constraint_entry(
    constraint: Any,
    path: str,
    allocation_keys: set[tuple[str, str]],
) -> tuple[tuple[str, str], set[str]]:
    if not isinstance(constraint, dict):
        _fail(f"{path} must be an object")
    _exact_keys(
        constraint,
        {"kind", "identifier", "required_invariants"},
        path,
    )
    kind = _string(
        constraint["kind"],
        f"{path}.kind",
        maximum=MAX_B03_ALLOCATION_KIND_BYTES,
    )
    identifier = _string(constraint["identifier"], f"{path}.identifier", maximum=256)
    key = (kind, identifier)
    if key not in allocation_keys:
        _fail(f"{path} does not identify one exact bounded allocation")
    invariants = constraint["required_invariants"]
    if (
        not isinstance(invariants, list)
        or not 1 <= len(invariants) <= MAX_B03_ALLOCATION_INVARIANTS
        or invariants != sorted(invariants)
        or len(invariants) != len(set(invariants))
    ):
        _fail(
            f"{path}.required_invariants must contain 1.."
            f"{MAX_B03_ALLOCATION_INVARIANTS} unique canonical sorted identities"
        )
    for invariant_index, invariant in enumerate(invariants):
        checked = _string(
            invariant,
            f"{path}.required_invariants[{invariant_index}]",
            maximum=128,
        )
        if not ALLOCATION_INVARIANT_ID.fullmatch(checked):
            _fail(
                f"{path}.required_invariants[{invariant_index}] "
                "must be canonical uppercase snake case"
            )
    return key, set(invariants)


def _validate_b03_allocation_constraints(
    value: Any, keys: set[tuple[str, str]]
) -> None:
    if (
        not isinstance(value, list)
        or not 1 <= len(value) <= MAX_B03_ALLOCATION_CONSTRAINTS
    ):
        _fail(
            "B03 allocation_constraints must contain 1.."
            f"{MAX_B03_ALLOCATION_CONSTRAINTS} bounded entries"
        )
    constraints_by_key: dict[tuple[str, str], set[str]] = {}
    ordered_keys: list[tuple[str, str]] = []
    for index, constraint in enumerate(value):
        key, invariants = _validate_b03_allocation_constraint_entry(
            constraint,
            f"B03 allocation_constraints[{index}]",
            keys,
        )
        if key in constraints_by_key:
            _fail(f"B03 allocation_constraints duplicates {key}")
        ordered_keys.append(key)
        constraints_by_key[key] = invariants
    if ordered_keys != sorted(ordered_keys):
        _fail("B03 allocation_constraints must use canonical key ordering")
    for key, required in B03_REQUIRED_ALLOCATION_CONSTRAINTS.items():
        if constraints_by_key.get(key) != required:
            _fail(
                f"B03 allocation_constraints for {key} differ from the exact "
                "fail-closed/current-head invariant set"
            )


