def _validate_b03_semantic_boundary(kind: str, identifier: str, path: str) -> None:
    if not identifier.isascii() or any(
        not 0x21 <= ord(character) <= 0x7E for character in identifier
    ):
        _fail(f"{path}.identifier must use printable non-space ASCII")
    if any(character in identifier for character in "*?[]{}"):
        _fail(f"{path}.identifier cannot allocate a wildcard or pattern alias")
    normalized_identifier = identifier.casefold()
    if ("prisoma" in kind or "prisoma" in normalized_identifier) and (
        kind,
        identifier,
    ) not in B03_ALLOWED_PRISOMA_SCHEMA_ALLOCATIONS:
        _fail(
            f"{path} cannot allocate unbounded consumer-specific Prisoma "
            "semantics outside the exact native-capture and numeric evidence schemas"
        )
    if ("semantic" in kind or "axis" in kind) and ("slot" in kind or "meaning" in kind):
        _fail(f"{path} cannot allocate consumer-owned semantic-axis slots or meanings")
    if kind in {
        "consumer-semantic-axis-contract-content-reference-type",
        "consumer-semantic-capture-state-head-identity",
        "installed-consumer-semantic-capture-state-selector-identity",
        "consumer-semantic-capture-state-commit-receipt-type",
        "consumer-semantic-registry-head-identity",
        "consumer-semantic-registry-head-commit-receipt-type",
    } and (
        normalized_identifier in {"v", "l", "d", "a", "v/l/d/a", "vlda"}
        or "slot" in normalized_identifier
        or "meaning" in normalized_identifier
    ):
        _fail(
            f"{path} must allocate only a generic content-reference type, "
            "not consumer-owned axis semantics"
        )


def _validate_b03_allocation_name_set(
    ordered_keys: list[tuple[str, str]],
) -> None:
    if len(ordered_keys) != len(set(ordered_keys)):
        _fail("B03 allocations contain a duplicate kind and identifier")
    folded_keys = {(kind, identifier.casefold()) for kind, identifier in ordered_keys}
    if len(folded_keys) != len(ordered_keys):
        _fail("B03 allocations contain a case-fold identifier collision")
    if ordered_keys != sorted(ordered_keys):
        _fail("B03 allocations must use canonical kind/identifier ordering")
    extension_prefixes = sorted(
        identifier.casefold()
        for kind, identifier in ordered_keys
        if kind == "extension-prefix"
    )
    for index, prefix in enumerate(extension_prefixes):
        if any(
            other.startswith(prefix) or prefix.startswith(other)
            for other in extension_prefixes[index + 1 :]
        ):
            _fail("B03 extension-prefix allocations overlap")


def _validate_b03_registry_file_identity(
    identity: Any,
    index: int,
    receipt: dict[str, Any],
) -> tuple[dict[str, Any], str, dict[str, Any] | None]:
    path = f"B03 registry_files[{index}]"
    if not isinstance(identity, dict):
        _fail(f"{path} must be a file-identity object")
    _exact_keys(identity, {"path", "sha256", "bytes"}, path)
    relative = _relative_path(identity["path"], f"{path}.path")
    digest = _hex(identity["sha256"], HEX64, f"{path}.sha256")
    byte_count = _integer(identity["bytes"], f"{path}.bytes", minimum=1)
    if byte_count > MAX_EVIDENCE_FILE_BYTES:
        _fail(f"{path}.bytes exceeds the file-size bound")
    source_bytes = _receipt_source_bytes(receipt, relative, path)
    if (
        hashlib.sha256(source_bytes).hexdigest() != digest
        or len(source_bytes) != byte_count
    ):
        _fail(f"{path} differs from the exact source-cut registry file")
    _require_committed_file(
        receipt,
        relative,
        digest,
        byte_count,
        path,
        cut="source",
    )
    document = None
    if relative in B03_JSON_REGISTRY_PATHS:
        document = _load_bounded_json_bytes(
            source_bytes,
            f"{path} bounded registry JSON",
        )
        _walk_limits(document)
    return identity, relative, document


def _validate_b03_registry_files(
    value: Any, receipt: dict[str, Any]
) -> tuple[list[dict[str, Any]], dict[str, dict[str, Any]]]:
    if (
        not isinstance(value, list)
        or [item.get("path") for item in value if isinstance(item, dict)]
        != list(B03_REGISTRY_PATHS)
        or len(value) != len(B03_REGISTRY_PATHS)
    ):
        _fail("B03 allocations artifact lacks the exact bounded registry file set")
    checked: list[dict[str, Any]] = []
    documents: dict[str, dict[str, Any]] = {}
    for index, identity in enumerate(value):
        item, relative, document = _validate_b03_registry_file_identity(
            identity, index, receipt
        )
        checked.append(item)
        if document is not None:
            documents[relative] = document
    return checked, documents


def _validate_b03_allocation_entry(
    entry: Any,
    index: int,
    *,
    registry_documents: dict[str, dict[str, Any]],
    codeowner_rules: list[tuple[str, tuple[str, ...]]],
    seen_registry_pointers: set[tuple[str, str]],
    seen_registry_value_digests: set[str],
) -> tuple[str, str]:
    path = f"B03 allocations[{index}]"
    if not isinstance(entry, dict):
        _fail(f"{path} must be an object")
    _exact_keys(
        entry,
        {
            "kind",
            "identifier",
            "owner_identity",
            "registry_path",
            "registry_pointer",
            "registry_value_sha256",
        },
        path,
    )
    kind = _string(
        entry["kind"],
        f"{path}.kind",
        maximum=MAX_B03_ALLOCATION_KIND_BYTES,
    )
    if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", kind):
        _fail(f"{path}.kind must be canonical lowercase kebab case")
    identifier = _string(entry["identifier"], f"{path}.identifier", maximum=256)
    _validate_b03_semantic_boundary(kind, identifier, path)
    _validate_identity_uri(entry["owner_identity"], f"{path}.owner_identity")
    _validate_b03_registry_binding(
        entry,
        registry_documents=registry_documents,
        codeowner_rules=codeowner_rules,
        seen_pointers=seen_registry_pointers,
        seen_value_digests=seen_registry_value_digests,
        path=path,
    )
    return kind, identifier


def _validate_b03_allocation_entries(
    value: Any,
    *,
    registry_documents: dict[str, dict[str, Any]],
    codeowner_rules: list[tuple[str, tuple[str, ...]]],
) -> list[tuple[str, str]]:
    if not isinstance(value, list) or not 1 <= len(value) <= 1024:
        _fail("B03 allocations must contain 1..1024 bounded entries")
    seen_registry_pointers: set[tuple[str, str]] = set()
    seen_registry_value_digests: set[str] = set()
    return [
        _validate_b03_allocation_entry(
            entry,
            index,
            registry_documents=registry_documents,
            codeowner_rules=codeowner_rules,
            seen_registry_pointers=seen_registry_pointers,
            seen_registry_value_digests=seen_registry_value_digests,
        )
        for index, entry in enumerate(value)
    ]


def _validate_b03_task_subject(
    task_subject: dict[str, Any],
    task_by_id: dict[str, dict[str, Any]],
    receipt: dict[str, Any],
) -> None:
    _require_non_normative_receipt_digest(receipt, "B03")
    b02_receipt = _latest_passing_receipt(task_by_id["B02"])
    assert b02_receipt is not None
    b02_receipt_sha = _receipt_sha256(b02_receipt)
    b02_subject = b02_receipt["task_subject"]
    if (
        task_subject["decision_set_sha256"] != b02_subject["decision_set_sha256"]
        or task_subject["b02_authorization_receipt_sha256"] != b02_receipt_sha
    ):
        _fail("B03 task subject differs from the exact B02 authorization")
    artifact_path = task_subject["allocations_artifact"]
    if artifact_path not in {artifact["path"] for artifact in receipt["artifacts"]}:
        _fail("B03 allocations artifact is not bound by the passing receipt")
    _require_receipt_artifact_at_evidence_commit(
        receipt, artifact_path, "B03 bounded-allocation artifact"
    )
    if artifact_path in B03_REGISTRY_PATHS:
        _fail("B03 allocations artifact cannot alias a source registry input")
    allocations = _load_bounded_json_bytes(
        _receipt_artifact_bytes(
            receipt,
            artifact_path,
            "B03 bounded-allocation artifact",
        ),
        "B03 bounded-allocation artifact",
    )
    _exact_keys(
        allocations,
        {
            "schema",
            "decision_set_sha256",
            "b02_authorization_receipt_sha256",
            "registry_set_sha256",
            "registry_value_digest_algorithm",
            "registry_files",
            "allocations",
            "allocation_constraints",
        },
        "B03 bounded-allocation artifact",
    )
    if (
        allocations["schema"] != "ncp.b03-bounded-allocations.v1"
        or allocations["decision_set_sha256"] != task_subject["decision_set_sha256"]
        or allocations["b02_authorization_receipt_sha256"] != b02_receipt_sha
        or allocations["registry_value_digest_algorithm"]
        != B03_REGISTRY_VALUE_DIGEST_ALGORITHM
    ):
        _fail("B03 allocations artifact binds the wrong authorization subject")
    checked_registry_files, registry_documents = _validate_b03_registry_files(
        allocations["registry_files"], receipt
    )
    registry_set_sha256 = _canonical_sha256(checked_registry_files)
    if (
        _hex(
            allocations["registry_set_sha256"],
            HEX64,
            "B03 bounded-allocation artifact.registry_set_sha256",
        )
        != registry_set_sha256
        or task_subject["registry_set_sha256"] != registry_set_sha256
    ):
        _fail("B03 task subject binds the wrong exact registry-file set")
    codeowner_rules = _parse_b03_codeowners(
        _receipt_source_bytes(
            receipt,
            ".github/CODEOWNERS",
            "B03 bounded CODEOWNERS",
        ),
        "B03 bounded CODEOWNERS",
    )
    if not _b03_effective_codeowners(codeowner_rules, ".github/CODEOWNERS"):
        _fail(
            "B03 CODEOWNERS file has no effective repository-text owner after "
            "last-match evaluation"
        )
    ordered_keys = _validate_b03_allocation_entries(
        allocations["allocations"],
        registry_documents=registry_documents,
        codeowner_rules=codeowner_rules,
    )
    keys = set(ordered_keys)
    _validate_b03_allocation_name_set(ordered_keys)
    _validate_b03_allocation_coverage(keys)
    _validate_b03_allocation_constraints(allocations["allocation_constraints"], keys)


def _promoted_registry_projection(
    staging: dict[str, Any],
    *,
    promotion_generator: dict[str, Any],
    promoted_registry_schema: dict[str, Any],
    staging_registry_sha256: str,
    staging_registry_bytes: int,
    b02_authorization_receipt_sha256: str,
    b03_allocation_receipt_sha256: str,
    registry_set_sha256: str,
) -> dict[str, Any]:
    promoted = copy.deepcopy(staging)
    promoted.update(
        {
            "schema": "ncp.decision-registry.v1",
            "normative": True,
            "claim_boundary": PROMOTED_REGISTRY_CLAIM_BOUNDARY,
            "generated_by": DECISION_REGISTRY_PROMOTION_GENERATOR.relative_to(
                ROOT
            ).as_posix(),
            "promotion_blocked": False,
            "promotion": {
                "schema": "ncp.decision-registry-promotion.v1",
                "task": "N01",
                "candidate": "1.0.0-rc.1",
                "wire_version": "1.0",
                "staging_registry": {
                    "path": DECISION_REGISTRY.relative_to(ROOT).as_posix(),
                    "sha256": staging_registry_sha256,
                    "bytes": staging_registry_bytes,
                },
                "decision_set_sha256": staging["decision_set"]["sha256"],
                "b02_authorization_receipt_sha256": (b02_authorization_receipt_sha256),
                "b03_allocation_receipt_sha256": b03_allocation_receipt_sha256,
                "registry_set_sha256": registry_set_sha256,
                "promotion_generator": copy.deepcopy(promotion_generator),
                "promoted_registry_schema": copy.deepcopy(promoted_registry_schema),
            },
        }
    )
    return promoted


def _validate_promoted_registry_projection(
    promoted: dict[str, Any],
    staging: dict[str, Any],
    *,
    promotion_generator: dict[str, Any],
    promoted_registry_schema: dict[str, Any],
    staging_registry_sha256: str,
    staging_registry_bytes: int,
    b02_authorization_receipt_sha256: str,
    b03_allocation_receipt_sha256: str,
    registry_set_sha256: str,
) -> None:
    expected = _promoted_registry_projection(
        staging,
        promotion_generator=promotion_generator,
        promoted_registry_schema=promoted_registry_schema,
        staging_registry_sha256=staging_registry_sha256,
        staging_registry_bytes=staging_registry_bytes,
        b02_authorization_receipt_sha256=b02_authorization_receipt_sha256,
        b03_allocation_receipt_sha256=b03_allocation_receipt_sha256,
        registry_set_sha256=registry_set_sha256,
    )
    if promoted != expected:
        _fail(
            "N01 promoted registry differs from the exact mechanical staging "
            "projection or predecessor provenance"
        )


def _validate_n01_task_subject(
    task_subject: dict[str, Any],
    task_by_id: dict[str, dict[str, Any]],
    receipt: dict[str, Any],
) -> None:
    b02_receipt = _latest_passing_receipt(task_by_id["B02"])
    b03_receipt = _latest_passing_receipt(task_by_id["B03"])
    assert b02_receipt is not None and b03_receipt is not None
    b01_receipt = _latest_passing_receipt(task_by_id["B01"])
    assert b01_receipt is not None
    b01_subject = b01_receipt["task_subject"]
    b03_subject = b03_receipt["task_subject"]
    assert isinstance(b03_subject, dict)
    for current_path, label in (
        (DECISION_REGISTRY, "N01 frozen staging decision registry"),
        (
            DECISION_REGISTRY_PROMOTION_GENERATOR,
            "N01 decision-registry promotion generator",
        ),
        (
            PROMOTED_DECISION_REGISTRY_SCHEMA,
            "N01 normative decision-registry schema",
        ),
        (PROMOTED_DECISION_REGISTRY, "N01 promoted decision registry"),
        (CONTRACT_MANIFEST, "N01 regenerated contract manifest"),
    ):
        _require_current_file_at_receipt_commit(receipt, current_path, label)
    promotion_generator_sha256, promotion_generator_bytes = _source_file_identity(
        receipt,
        DECISION_REGISTRY_PROMOTION_GENERATOR,
        "N01 decision-registry promotion generator",
    )
    promoted_schema_sha256, promoted_schema_bytes = _source_file_identity(
        receipt,
        PROMOTED_DECISION_REGISTRY_SCHEMA,
        "N01 normative decision-registry schema",
    )
    staging_registry_sha256, staging_registry_bytes = _source_file_identity(
        receipt,
        DECISION_REGISTRY,
        "N01 frozen staging decision registry",
    )
    promoted_registry_sha256, promoted_registry_bytes = _source_file_identity(
        receipt,
        PROMOTED_DECISION_REGISTRY,
        "N01 promoted decision registry",
    )
    contract_manifest_sha256, _ = _source_file_identity(
        receipt,
        CONTRACT_MANIFEST,
        "N01 regenerated contract manifest",
    )
    promotion_generator_identity = {
        "path": DECISION_REGISTRY_PROMOTION_GENERATOR.relative_to(ROOT).as_posix(),
        "sha256": promotion_generator_sha256,
        "bytes": promotion_generator_bytes,
    }
    promoted_schema_identity = {
        "path": PROMOTED_DECISION_REGISTRY_SCHEMA.relative_to(ROOT).as_posix(),
        "sha256": promoted_schema_sha256,
        "bytes": promoted_schema_bytes,
    }
    expected = {
        "decision_set_sha256": b01_subject["decision_set_sha256"],
        "b02_authorization_receipt_sha256": _receipt_sha256(b02_receipt),
        "b03_allocation_receipt_sha256": _receipt_sha256(b03_receipt),
        "staging_registry_sha256": b01_subject["registry_sha256"],
        "promoted_registry_path": PROMOTED_DECISION_REGISTRY.relative_to(
            ROOT
        ).as_posix(),
        "promotion_generator": promotion_generator_identity,
        "promoted_registry_schema": promoted_schema_identity,
        "contract_manifest_path": CONTRACT_MANIFEST.relative_to(ROOT).as_posix(),
        "normative_digest_before": b03_receipt["normative_digest_after"],
    }
    for field, value in expected.items():
        if task_subject[field] != value:
            _fail(f"N01 task subject {field} differs from its exact predecessors")
    if task_subject["promoted_registry_sha256"] != promoted_registry_sha256:
        _fail("N01 task subject lacks the exact promoted decision registry")
    if task_subject["contract_manifest_sha256"] != contract_manifest_sha256:
        _fail("N01 task subject lacks the exact regenerated contract manifest")
    staging = _checked_decision_registry(require_gate=False, receipt=receipt)
    if (
        staging_registry_sha256 != task_subject["staging_registry_sha256"]
        or staging["decision_set"]["sha256"] != task_subject["decision_set_sha256"]
    ):
        _fail("N01 staging registry differs from the exact frozen B01 subject")
    promoted = _load_bounded_json_bytes(
        _receipt_source_bytes(
            receipt,
            PROMOTED_DECISION_REGISTRY.relative_to(ROOT).as_posix(),
            "N01 promoted decision registry",
        ),
        "N01 promoted decision registry",
    )
    _validate_promoted_registry_projection(
        promoted,
        staging,
        promotion_generator=promotion_generator_identity,
        promoted_registry_schema=promoted_schema_identity,
        staging_registry_sha256=task_subject["staging_registry_sha256"],
        staging_registry_bytes=staging_registry_bytes,
        b02_authorization_receipt_sha256=task_subject[
            "b02_authorization_receipt_sha256"
        ],
        b03_allocation_receipt_sha256=task_subject["b03_allocation_receipt_sha256"],
        registry_set_sha256=b03_subject["registry_set_sha256"],
    )
    if (
        any(decision.get("status") != "ACCEPTED" for decision in promoted["decisions"])
        or len(promoted["decisions"]) != 11
    ):
        _fail("N01 promoted registry does not contain eleven accepted decisions")
    _require_n01_promotion_gates()
    manifest = _load_bounded_json_bytes(
        _receipt_source_bytes(
            receipt,
            CONTRACT_MANIFEST.relative_to(ROOT).as_posix(),
            "N01 contract manifest",
        ),
        "N01 contract manifest",
    )
    expected_normative_sources = {
        task_subject["promoted_registry_path"]: (
            task_subject["promoted_registry_sha256"],
            promoted_registry_bytes,
        ),
        promoted_schema_identity["path"]: (
            promoted_schema_identity["sha256"],
            promoted_schema_identity["bytes"],
        ),
    }
    matching_sources = {
        path: [
            entry
            for entry in manifest.get("normative_sources", [])
            if entry.get("path") == path
        ]
        for path in expected_normative_sources
    }
    if (
        any(
            len(matching_sources[path]) != 1
            or matching_sources[path][0].get("sha256") != identity[0]
            or matching_sources[path][0].get("bytes") != identity[1]
            for path, identity in expected_normative_sources.items()
        )
        or manifest.get("contract_digest_sha256")
        != task_subject["normative_digest_after"]
        or receipt["normative_digest_before"] != task_subject["normative_digest_before"]
        or receipt["normative_digest_after"] != task_subject["normative_digest_after"]
        or task_subject["normative_digest_before"]
        == task_subject["normative_digest_after"]
    ):
        _fail("N01 contract manifest does not bind the promoted normative identity")


def _bound_dependency_receipts_at(
    task: dict[str, Any],
    bindings: Any,
    cutoff: datetime,
    task_by_id: dict[str, dict[str, Any]],
    path: str,
) -> dict[str, dict[str, Any]]:
    if not isinstance(bindings, list):
        _fail(f"{path} must be an exact dependency-receipt array")
    expected_ids = task["dependencies"]
    if [
        binding.get("task_id") for binding in bindings if isinstance(binding, dict)
    ] != (expected_ids):
        _fail(f"{path} differs from the checked dependency order")
    resolved: dict[str, dict[str, Any]] = {}
    for index, (dependency_id, binding) in enumerate(
        zip(expected_ids, bindings, strict=True)
    ):
        binding_path = f"{path}[{index}]"
        if not isinstance(binding, dict):
            _fail(f"{binding_path} must be an exact dependency binding")
        _exact_keys(binding, {"task_id", "receipt_sha256"}, binding_path)
        state, reached, active_receipt = _dependency_state_before(
            task_by_id[dependency_id],
            cutoff,
        )
        if (
            state
            not in {
                "LOCAL_PASS",
                "EXTERNAL_PASS",
                "INDEPENDENT_PASS",
                "COMPLETE",
            }
            or not _reached_evidence_floor(
                task_by_id[dependency_id]["minimum_terminal_class"],
                reached,
            )
            or active_receipt is None
        ):
            _fail(f"{path} resolves before dependency {dependency_id} is passing")
        if binding["receipt_sha256"] != _receipt_sha256(active_receipt):
            _fail(
                f"{binding_path} does not bind the exact active {dependency_id} "
                "receipt at the dependent transition"
            )
        resolved[dependency_id] = active_receipt
    return resolved


def _require_dependency_receipt_precedes(
    dependency_receipt: Mapping[str, Any],
    dependent_receipt_time: datetime,
    path: str,
) -> None:
    dependency_receipt_time = _parse_timestamp(
        dependency_receipt["timestamp_utc"],
        f"{path}.timestamp_utc",
    )
    if dependency_receipt_time >= dependent_receipt_time:
        _fail(f"{path} must be strictly earlier than the dependent receipt")


def _validate_current_task_subjects(
    task_by_id: dict[str, dict[str, Any]],
) -> None:
    promoted = _task_reached_minimum(task_by_id["N01"])
    for task_id in ("B01", "B02", "B03", "N01"):
        task = task_by_id[task_id]
        if task["status"] not in {
            "LOCAL_PASS",
            "EXTERNAL_PASS",
            "INDEPENDENT_PASS",
            "COMPLETE",
        } or not _task_reached_minimum(task):
            continue
        receipt = _latest_passing_receipt(task)
        assert receipt is not None
        task_subject = receipt["task_subject"]
        assert isinstance(task_subject, dict)
        if task_id == "B01":
            _validate_b01_task_subject(task_subject, receipt, promoted=promoted)
        elif task_id == "B02":
            b01_receipt = _latest_passing_receipt(task_by_id["B01"])
            assert b01_receipt is not None
            _validate_b02_task_subject(
                task_subject,
                receipt,
                b01_receipt,
                promoted=promoted,
                started_at=_parse_timestamp(
                    task["transitions"][0]["timestamp_utc"],
                    "B02 dependency-ready start timestamp",
                ),
            )
        elif task_id == "B03":
            _validate_b03_task_subject(task_subject, task_by_id, receipt)
        else:
            _validate_n01_task_subject(task_subject, task_by_id, receipt)


def _validate_invalidation_record(
    record: Any, path: str, *, source_task_id: str
) -> None:
    if not isinstance(record, dict):
        _fail(f"{path} must be an object")
    _exact_keys(record, {"task_id", "receipt_sha256", "reopen_correlation_id"}, path)
    task_id = _string(record["task_id"], f"{path}.task_id", maximum=3)
    if not TASK_ID.fullmatch(task_id) or task_id == source_task_id:
        _fail(f"{path}.task_id must identify a different checked task")
    _hex(record["receipt_sha256"], HEX64, f"{path}.receipt_sha256")
    _string(
        record["reopen_correlation_id"], f"{path}.reopen_correlation_id", maximum=128
    )


def _validate_current_review_independence(
    reviewers: list[Any],
    path: str,
    *,
    task_id: str,
    status: str,
) -> None:
    if status == "INDEPENDENT_PASS" and task_id != "B01":
        _validate_review_independence(
            reviewers,
            f"{path}.reviewers",
            minimum=INDEPENDENT_REVIEWER_MINIMUM[task_id],
        )
    elif (
        status == "COMPLETE"
        and MINIMUM_TERMINAL_CLASS[task_id] == "INDEPENDENT"
        and task_id != "B01"
    ):
        _validate_review_independence(
            reviewers,
            f"{path}.reviewers",
            minimum=INDEPENDENT_REVIEWER_MINIMUM[task_id],
        )


def _validate_task(
    task: Any,
    expected: tuple[str, str, tuple[str, ...], str],
    path: str,
    *,
    budget: dict[str, int],
) -> None:
    if not isinstance(task, dict):
        _fail(f"{path} must be an object")
    keys = {
        "id",
        "title",
        "status",
        "claim_tier",
        "minimum_terminal_class",
        "dependencies",
        "repository",
        "source_commit",
        "target_commit",
        "dirty_state_disposition",
        "changed_files",
        "requirement_ids",
        "adr_ids",
        "perspective_reviews",
        "ten_lens_reviews",
        "commands",
        "artifacts",
        "reviewers",
        "residual_risks",
        "rollback_or_recovery",
        "invalidates",
        "transitions",
        "reviewer_comment",
    }
    _exact_keys(task, keys, path)
    task_id, title, dependencies, repository = expected
    if task["id"] != task_id or not TASK_ID.fullmatch(str(task["id"])):
        _fail(f"{path}.id is unknown or out of order")
    if task["title"] != title:
        _fail(f"{path}.title differs from the checked catalog")
    if task["dependencies"] != list(dependencies):
        _fail(f"{path}.dependencies differ from the checked DAG")
    if task["repository"] != repository:
        _fail(f"{path}.repository differs from the checked catalog")
    if task["minimum_terminal_class"] != MINIMUM_TERMINAL_CLASS[task_id]:
        _fail(f"{path}.minimum_terminal_class differs from the checked evidence class")
    if task["claim_tier"] != TASK_CLAIM_TIER[task_id]:
        _fail(f"{path}.claim_tier differs from the checked claim boundary")
    status = task["status"]
    if status not in STATUSES:
        _fail(f"{path}.status is invalid")
    for field in ("source_commit", "target_commit"):
        if task[field] is not None:
            _hex(task[field], HEX40, f"{path}.{field}")
    dirty = task["dirty_state_disposition"]
    if dirty not in {
        "NOT_EVALUATED",
        "ACCEPTED_CLEAN",
        "PRESERVED_DIRTY",
        "REFUSED_DIRTY",
    }:
        _fail(f"{path}.dirty_state_disposition is invalid")
    if (
        status in {"LOCAL_PASS", "EXTERNAL_PASS", "INDEPENDENT_PASS", "COMPLETE"}
        and dirty != "ACCEPTED_CLEAN"
    ):
        _fail(f"{path} cannot pass with dirty or unevaluated evidence")
    for field in ("changed_files", "artifacts"):
        if not isinstance(task[field], list):
            _fail(f"{path}.{field} must be an array")
        for index, value in enumerate(task[field]):
            _relative_path(value, f"{path}.{field}[{index}]")
        if len(task[field]) != len(set(task[field])):
            _fail(f"{path}.{field} contains duplicates")
    if task_id == "B01":
        if task["changed_files"] != sorted(task["changed_files"]):
            _fail(f"{path}.changed_files must use canonical sorted ordering")
        governed = set(B01_GOVERNED_FIXED_PATHS)
        source = _load_bounded_json_file(
            DECISION_REGISTRY_SOURCE,
            "B01 changed-files decision source",
        )
        decisions = source.get("decisions") if isinstance(source, dict) else None
        if not isinstance(decisions, list):
            _fail("B01 changed-files decision source lacks decisions")
        for decision_index, decision in enumerate(decisions):
            if not isinstance(decision, dict):
                _fail(
                    "B01 changed-files decision source contains a non-object "
                    f"decision at {decision_index}"
                )
            governed.add(
                _relative_path(
                    decision.get("path"),
                    f"B01 changed-files decision[{decision_index}].path",
                )
            )
            module_paths = decision.get("module_paths")
            if not isinstance(module_paths, list):
                _fail(
                    "B01 changed-files decision source contains invalid "
                    f"module_paths at {decision_index}"
                )
            governed.update(
                _relative_path(
                    module_path,
                    (
                        f"B01 changed-files decision[{decision_index}]"
                        f".module_paths[{module_index}]"
                    ),
                )
                for module_index, module_path in enumerate(module_paths)
            )
        missing_governed = sorted(governed - set(task["changed_files"]))
        if missing_governed:
            _fail(f"{path}.changed_files omits governed path {missing_governed[0]}")
    for field in ("requirement_ids", "adr_ids", "residual_risks"):
        if not isinstance(task[field], list):
            _fail(f"{path}.{field} must be an array")
        for index, value in enumerate(task[field]):
            _string(value, f"{path}.{field}[{index}]", maximum=512)
        if len(task[field]) != len(set(task[field])):
            _fail(f"{path}.{field} contains duplicates")
    required_base = (
        {
            "B00-ledger-integrity",
            "B00-no-optimistic-status",
            "B00-resumption-control",
            "B00-current-generation-evidence",
            "B00-content-bound-receipts",
        }
        if task_id == "B00"
        else {f"{task_id}-acceptance"}
    )
    if not required_base.issubset(task["requirement_ids"]):
        _fail(f"{path}.requirement_ids lacks the checked task acceptance requirement")
    if task_id == "B01" and task["adr_ids"] != [
        f"ADR-{number:03d}" for number in range(1, 12)
    ]:
        _fail(f"{path}.adr_ids must bind ADR-001 through ADR-011 exactly")
    if not isinstance(task["invalidates"], list):
        _fail(f"{path}.invalidates must be an array")
    for index, record in enumerate(task["invalidates"]):
        _validate_invalidation_record(
            record, f"{path}.invalidates[{index}]", source_task_id=task_id
        )
    if len(task["invalidates"]) != len(
        {
            (
                record["task_id"],
                record["receipt_sha256"],
                record["reopen_correlation_id"],
            )
            for record in task["invalidates"]
            if isinstance(record, dict)
        }
    ):
        _fail(f"{path}.invalidates contains duplicate records")
    for review_field, expected_ids in (
        ("perspective_reviews", PERSPECTIVES),
        ("ten_lens_reviews", LENSES),
    ):
        reviews = task[review_field]
        if not isinstance(reviews, list):
            _fail(f"{path}.{review_field} must be an array")
        ids: list[str] = []
        for index, review in enumerate(reviews):
            review_path = f"{path}.{review_field}[{index}]"
            if not isinstance(review, dict):
                _fail(f"{review_path} must be an object")
            _exact_keys(
                review, {"id", "disposition", "rationale", "reviewer"}, review_path
            )
            ids.append(_string(review["id"], f"{review_path}.id", maximum=3))
            if review["disposition"] not in {
                "NOT_REVIEWED",
                "PASS",
                "FAIL",
                "NOT_APPLICABLE",
            }:
                _fail(f"{review_path}.disposition is invalid")
            _string(review["rationale"], f"{review_path}.rationale", maximum=1024)
            _string(review["reviewer"], f"{review_path}.reviewer", maximum=128)
        if len(ids) != len(set(ids)) or any(
            identifier not in expected_ids for identifier in ids
        ):
            _fail(f"{path}.{review_field} has duplicate or unknown review IDs")
        if status in {"LOCAL_PASS", "EXTERNAL_PASS", "INDEPENDENT_PASS", "COMPLETE"}:
            if tuple(ids) != expected_ids or any(
                review["disposition"] not in {"PASS", "NOT_APPLICABLE"}
                for review in reviews
            ):
                _fail(f"{path}.{review_field} is incomplete for a passing status")
    if not isinstance(task["commands"], list) or not isinstance(
        task["reviewers"], list
    ):
        _fail(f"{path}.commands and reviewers must be arrays")
    for index, reviewer in enumerate(task["reviewers"]):
        _validate_reviewer(reviewer, f"{path}.reviewers[{index}]")
    _validate_reviewer_owner_partition(task["reviewers"], f"{path}.reviewers")
    _string(task["rollback_or_recovery"], f"{path}.rollback_or_recovery", maximum=1024)
    if task["reviewer_comment"] is not None:
        _string(task["reviewer_comment"], f"{path}.reviewer_comment", maximum=2048)
    transitions = task["transitions"]
    if not isinstance(transitions, list) or len(transitions) > 128:
        _fail(f"{path}.transitions must be an array of at most 128 transitions")
    previous = "OPEN"
    previous_time: datetime | None = None
    allowed = {
        "OPEN": {"IN_PROGRESS"},
        "IN_PROGRESS": {"BLOCKED", "LOCAL_PASS"},
        "BLOCKED": {"IN_PROGRESS"},
        "LOCAL_PASS": {"COMPLETE", "IN_PROGRESS"},
        "EXTERNAL_PASS": set(),
        "INDEPENDENT_PASS": set(),
        "COMPLETE": {"IN_PROGRESS"},
    }
    passing_generation: dict[str, Any] | None = None
    for index, transition in enumerate(transitions):
        transition_path = f"{path}.transitions[{index}]"
        if not isinstance(transition, dict):
            _fail(f"{transition_path} must be an object")
        _exact_keys(
            transition,
            {"from", "to", "timestamp_utc", "correlation_id", "reason", "receipt"},
            transition_path,
        )
        _reject_unsupported_evidence_admission(
            task_id,
            transition["to"],
            transition_path,
        )
        if transition["from"] != previous or transition["to"] not in allowed[previous]:
            _fail(f"{transition_path} is not an allowed contiguous transition")
        transition_time = _parse_timestamp(
            transition["timestamp_utc"], f"{transition_path}.timestamp_utc"
        )
        prior_time = previous_time
        if prior_time is not None and transition_time <= prior_time:
            _fail(f"{transition_path}.timestamp_utc must move strictly forward")
        previous_time = transition_time
        _string(
            transition["correlation_id"],
            f"{transition_path}.correlation_id",
            maximum=128,
        )
        _string(transition["reason"], f"{transition_path}.reason", maximum=512)
        if previous == "OPEN" and transition["to"] == "IN_PROGRESS":
            if task["dependencies"]:
                _validate_start_receipt(
                    transition["receipt"], f"{transition_path}.receipt"
                )
                receipt_time = _parse_timestamp(
                    transition["receipt"]["timestamp_utc"],
                    f"{transition_path}.receipt.timestamp_utc",
                )
                if receipt_time > transition_time:
                    _fail(f"{transition_path}.receipt is newer than its transition")
            elif transition["receipt"] is not None:
                _fail(f"{transition_path}.receipt must be null without dependencies")
        elif transition["to"] in {"BLOCKED", "IN_PROGRESS"}:
            _validate_coordination_receipt(
                transition["receipt"],
                f"{transition_path}.receipt",
                budget=budget,
                repository=task["repository"],
            )
            receipt_time = _parse_timestamp(
                transition["receipt"]["timestamp_utc"],
                f"{transition_path}.receipt.timestamp_utc",
            )
            if receipt_time > transition_time:
                _fail(f"{transition_path}.receipt is newer than its transition")
            if prior_time is not None and receipt_time < prior_time:
                _fail(f"{transition_path}.receipt predates the prior transition")
            if (
                previous
                in {
                    "LOCAL_PASS",
                    "EXTERNAL_PASS",
                    "INDEPENDENT_PASS",
                    "COMPLETE",
                }
                and transition["to"] == "IN_PROGRESS"
            ):
                passing_generation = None
        else:
            receipt_value = transition["receipt"]
            if isinstance(receipt_value, dict) and "repository" in receipt_value:
                _validate_receipt_repository_policy(
                    task,
                    receipt_value["repository"],
                    f"{transition_path}.receipt",
                )
            _validate_receipt(
                receipt_value,
                f"{transition_path}.receipt",
                task_id=task_id,
                transition_to=transition["to"],
                budget=budget,
            )
            receipt_time = _parse_timestamp(
                transition["receipt"]["timestamp_utc"],
                f"{transition_path}.receipt.timestamp_utc",
            )
            if receipt_time > transition_time:
                _fail(f"{transition_path}.receipt is newer than its transition")
            if prior_time is not None and receipt_time < prior_time:
                _fail(f"{transition_path}.receipt predates the prior transition")
            if (
                transition["to"] == "EXTERNAL_PASS"
                and not transition["receipt"]["external_gates_run"]
            ):
                _fail(f"{transition_path} EXTERNAL_PASS requires named external gates")
            passing_generation = _advance_passing_generation(
                passing_generation,
                transition["receipt"],
                transition_path,
            )
        previous = transition["to"]
    _validate_task_wide_reviewer_owner_partition(task, path)
    if previous != status:
        _fail(f"{path}.status does not match its transition history")
    if status == "OPEN" and transitions:
        _fail(f"{path} OPEN task cannot have transitions")
    if status != "OPEN" and not transitions:
        _fail(f"{path} non-OPEN task requires transition history")
    if status in {"LOCAL_PASS", "EXTERNAL_PASS", "INDEPENDENT_PASS", "COMPLETE"}:
        if (
            task["source_commit"] is None
            or not task["commands"]
            or not task["artifacts"]
        ):
            _fail(
                f"{path} passing status lacks immutable source, commands, or artifacts"
            )
        latest = _latest_passing_receipt(task)
        if latest is None:
            _fail(f"{path} passing status lacks a passing receipt")
        if task["commands"] != latest["commands"]:
            _fail(f"{path}.commands differs from the current passing receipt")
        if task["artifacts"] != [artifact["path"] for artifact in latest["artifacts"]]:
            _fail(f"{path}.artifacts differs from the current passing receipt")
        if task["reviewers"] != latest["reviewers"]:
            _fail(f"{path}.reviewers differs from the current passing receipt")
        if (
            task["source_commit"] != latest["source_commit"]
            or task["target_commit"] != latest["commit"]
        ):
            _fail(
                f"{path} current commit fields differ from the current passing receipt"
            )
    elif task["commands"] or task["artifacts"] or task["reviewers"]:
        _fail(
            f"{path} non-passing current state must retain evidence only in transition receipts"
        )
    if status == "COMPLETE" and not _task_reached_minimum(task):
        _fail(f"{path} COMPLETE did not reach its required evidence class")
    _validate_current_review_independence(
        task["reviewers"],
        path,
        task_id=task_id,
        status=status,
    )


def _validate_blueprint_binding(blueprint: Any) -> None:
    if not isinstance(blueprint, dict):
        _fail("$.blueprint must be an object")
    _exact_keys(blueprint, {"path", "sha256"}, "$.blueprint")
    if blueprint["path"] != "docs/handoff/NCP_V1_0_ECOSYSTEM_FINALIZATION_BLUEPRINT.md":
        _fail("$.blueprint.path is not canonical")
    expected_blueprint = hashlib.sha256(BLUEPRINT.read_bytes()).hexdigest()
    if blueprint["sha256"] != expected_blueprint:
        _fail("$.blueprint.sha256 is stale")


def _canonical_distribution_name(value: Any, path: str) -> str:
    if not isinstance(value, str) or not value:
        _fail(f"{path} must be a nonempty distribution name")
    if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", value):
        _fail(f"{path} is not a canonical distribution name")
    return re.sub(r"[-_.]+", "-", value).lower()


def _decode_requirements_file(raw: bytes, path: str) -> str:
    if not 1 <= len(raw) <= MAX_EVIDENCE_REQUIREMENTS_BYTES:
        _fail(f"{path} exceeds the bounded requirements-file size")
    try:
        text = raw.decode("ascii")
    except UnicodeDecodeError as error:
        _fail(f"{path} is not ASCII: {error}")
    if "\r" in text or not text.endswith("\n"):
        _fail(f"{path} must use canonical LF lines with a final line feed")
    return text


def _parse_locked_distributions(lock_text: str) -> dict[str, tuple[str, str | None]]:
    locked: dict[str, tuple[str, str | None]] = {}
    for line_number, line in enumerate(lock_text.splitlines(), start=1):
        if not line or line.startswith("#") or line[0].isspace():
            continue
        if not line.endswith(" \\"):
            _fail(
                "scripts/requirements-evidence-schema.txt line "
                f"{line_number} is not a hash-continued exact pin"
            )
        requirement = line[:-2]
        pinned, marker_separator, marker = requirement.partition(" ; ")
        if pinned.count("==") != 1:
            _fail(
                "scripts/requirements-evidence-schema.txt line "
                f"{line_number} is not an exact distribution pin"
            )
        distribution, version = pinned.split("==", 1)
        canonical = _canonical_distribution_name(
            distribution,
            f"scripts/requirements-evidence-schema.txt line {line_number}",
        )
        if distribution != canonical:
            _fail(
                "scripts/requirements-evidence-schema.txt line "
                f"{line_number} does not use its canonical distribution name"
            )
        if (
            not version
            or any(character.isspace() for character in version)
            or "\\" in version
        ):
            _fail(
                "scripts/requirements-evidence-schema.txt line "
                f"{line_number} has an invalid exact version"
            )
        if canonical in locked:
            _fail(
                "scripts/requirements-evidence-schema.txt repeats distribution "
                f"{canonical}"
            )
        locked[canonical] = (
            version,
            marker if marker_separator else None,
        )
    return locked


def _validate_evidence_requirements_contract(
    input_bytes: bytes,
    lock_bytes: bytes,
) -> None:
    input_text = _decode_requirements_file(
        input_bytes, "scripts/requirements-evidence-schema.in"
    )
    direct_requirements = tuple(
        line.strip()
        for line in input_text.splitlines()
        if line.strip() and not line.lstrip().startswith("#")
    )
    if direct_requirements != EVIDENCE_DIRECT_REQUIREMENTS:
        _fail(
            "scripts/requirements-evidence-schema.in must contain exactly the "
            "checked non-cryptographic direct requirement set"
        )
    if "cryptography" in input_text.casefold():
        _fail(
            "scripts/requirements-evidence-schema.in contains a cryptographic "
            "dependency that cannot authorize external evidence"
        )

    lock_text = _decode_requirements_file(
        lock_bytes, "scripts/requirements-evidence-schema.txt"
    )
    locked = _parse_locked_distributions(lock_text)
    if locked != EVIDENCE_LOCKED_DISTRIBUTIONS:
        _fail(
            "scripts/requirements-evidence-schema.txt differs from the exact "
            "seven-distribution universal resolution"
        )
    for direct_requirement in EVIDENCE_DIRECT_REQUIREMENTS:
        direct_name, direct_version = direct_requirement.split("==", 1)
        if locked.get(direct_name) != (direct_version, None):
            _fail(
                "scripts/requirements-evidence-schema.txt does not resolve each "
                "exact direct requirement from "
                "scripts/requirements-evidence-schema.in"
            )
    if lock_text.count("    # via -r scripts/requirements-evidence-schema.in\n") != len(
        EVIDENCE_DIRECT_REQUIREMENTS
    ):
        _fail(
            "scripts/requirements-evidence-schema.txt must bind every exact "
            "direct requirement to scripts/requirements-evidence-schema.in"
        )
    expected_compile_command = (
        "#    uv pip compile scripts/requirements-evidence-schema.in "
        "--python-version 3.12 --universal --generate-hashes "
        "--no-emit-index-url --output-file "
        "scripts/requirements-evidence-schema.txt\n"
    )
    if lock_text.count(expected_compile_command) != 1:
        _fail(
            "scripts/requirements-evidence-schema.txt lacks the exact reproducible "
            "universal compile command"
        )
    if "--hash=sha256:" not in lock_text:
        _fail(
            "scripts/requirements-evidence-schema.txt contains no SHA-256 "
            "artifact hashes"
        )
    if hashlib.sha256(input_bytes).hexdigest() != EVIDENCE_REQUIREMENTS_INPUT_SHA256:
        _fail("scripts/requirements-evidence-schema.in bytes are stale")
    if hashlib.sha256(lock_bytes).hexdigest() != EVIDENCE_REQUIREMENTS_LOCK_SHA256:
        _fail("scripts/requirements-evidence-schema.txt bytes are stale")


def _validate_installed_schema_distributions(
    observed_distributions: list[tuple[str, str]],
    python_version: tuple[int, int],
) -> None:
    observed: dict[str, str] = {}
    for index, (distribution, version) in enumerate(observed_distributions):
        canonical = _canonical_distribution_name(
            distribution, f"installed distribution {index}"
        )
        if canonical in observed:
            _fail(
                "evidence-schema environment contains duplicate installed "
                f"distribution {canonical}"
            )
        if not isinstance(version, str) or not version:
            _fail(
                "evidence-schema environment contains an installed distribution "
                f"without a version: {canonical}"
            )
        observed[canonical] = version

    runtime = {
        name: version
        for name, version in observed.items()
        if name not in EVIDENCE_ENVIRONMENT_BOOTSTRAP_DISTRIBUTIONS
    }
    expected = {
        name: version
        for name, (version, marker) in EVIDENCE_LOCKED_DISTRIBUTIONS.items()
        if marker is None or python_version < (3, 13)
    }
    unexpected = sorted(set(runtime) - set(expected))
    missing = sorted(set(expected) - set(runtime))
    drift = sorted(
        name for name in set(runtime) & set(expected) if runtime[name] != expected[name]
    )
    if unexpected or missing or drift:
        details: list[str] = []
        if unexpected:
            details.append(f"unexpected={unexpected}")
        if missing:
            details.append(f"missing={missing}")
        if drift:
            details.append(
                "version_drift="
                + repr([(name, expected[name], runtime[name]) for name in drift])
            )
        _fail(
            "evidence-schema environment differs from the exact applicable lock "
            f"closure: {', '.join(details)}"
        )


@lru_cache(maxsize=1)
def _validate_evidence_schema_supply_chain() -> None:
    for path in (EVIDENCE_REQUIREMENTS_INPUT, EVIDENCE_REQUIREMENTS_LOCK):
        if path.is_symlink() or not path.is_file():
            _fail(f"{path.relative_to(ROOT)} must be a regular non-symlink file")
    _validate_evidence_requirements_contract(
        EVIDENCE_REQUIREMENTS_INPUT.read_bytes(),
        EVIDENCE_REQUIREMENTS_LOCK.read_bytes(),
    )

    installed: list[tuple[str, str]] = []
    for distribution in importlib_metadata.distributions():
        name = distribution.metadata.get("Name")
        if not isinstance(name, str):
            _fail(
                "evidence-schema environment contains a distribution without "
                "canonical Name metadata"
            )
        installed.append((name, distribution.version))
    _validate_installed_schema_distributions(
        installed,
        (sys.version_info.major, sys.version_info.minor),
    )


def _validate_implementation_tool_bindings(implementation_tools: Any) -> None:
    _validate_evidence_schema_supply_chain()
    if not isinstance(implementation_tools, list) or len(implementation_tools) != 5:
        _fail(
            "$.implementation_tools must bind exactly the semantic checker, "
            "ledger generator, ledger schema, Draft 2020-12 validator, and "
            "hash-locked validator environment"
        )
    expected_tools = (
        "scripts/check_implementation_ledger.py",
        "scripts/generate_implementation_ledger.py",
        "evidence/implementation/task-ledger.schema.v1.json",
        "scripts/validate_evidence_schemas.py",
        "scripts/requirements-evidence-schema.txt",
    )
    for index, (tool, expected_path) in enumerate(
        zip(implementation_tools, expected_tools, strict=True)
    ):
        tool_path = f"$.implementation_tools[{index}]"
        if not isinstance(tool, dict):
            _fail(f"{tool_path} must be an object")
        _exact_keys(tool, {"path", "sha256"}, tool_path)
        if tool["path"] != expected_path:
            _fail(f"{tool_path}.path is not canonical")
        expected_digest = hashlib.sha256(
            (ROOT / expected_path).read_bytes()
        ).hexdigest()
        if tool["sha256"] != expected_digest:
            _fail(f"{tool_path}.sha256 is stale")


def _validate_defect_traceability(defect_traceability: Any) -> None:
    if not isinstance(defect_traceability, list) or len(defect_traceability) != len(
        DEFECT_TRACEABILITY
    ):
        _fail("$.defect_traceability must map D01-D20 exactly")
    expected_defects = list(DEFECT_TRACEABILITY)
    if [
        entry.get("id") for entry in defect_traceability if isinstance(entry, dict)
    ] != expected_defects:
        _fail("$.defect_traceability IDs are missing, duplicated, or out of order")
    for index, entry in enumerate(defect_traceability):
        entry_path = f"$.defect_traceability[{index}]"
        if not isinstance(entry, dict):
            _fail(f"{entry_path} must be an object")
        _exact_keys(entry, {"id", "task_ids", "closure_rule"}, entry_path)
        if entry["task_ids"] != list(DEFECT_TRACEABILITY[entry["id"]]):
            _fail(f"{entry_path}.task_ids differs from the checked closure map")
        if entry["closure_rule"] != DEFECT_CLOSURE_RULES[entry["id"]]:
            _fail(f"{entry_path}.closure_rule differs from the checked closure rule")


def _validate_ledger_root_identity(data: Any) -> dict[str, Any]:
    if not isinstance(data, dict):
        _fail("ledger root must be an object")
    root_keys = {
        "schema",
        "claim_boundary",
        "ledger_grants_release_authorization",
        "blueprint",
        "implementation_tools",
        "defect_traceability",
        "limits",
        "perspective_mapping",
        "lens_mapping",
        "toolchain",
        "repositories",
        "tasks",
    }
    _exact_keys(data, root_keys, "$")
    if data["schema"] != SCHEMA_ID:
        _fail("$.schema is invalid")
    if data["claim_boundary"] != CLAIM_BOUNDARY:
        _fail("$.claim_boundary differs from the checked non-claim boundary")
    if data["ledger_grants_release_authorization"] is not False:
        _fail("$.ledger_grants_release_authorization must remain false")
    return data


def validate(data: Any) -> None:
    _walk_limits(data)
    _scan_sensitive(data)
    try:
        adr008_raw = read_bounded_regular_file(
            ADR008,
            limits=TASK_SUBJECT_FILE_LIMITS,
            label="ADR-008",
        )
    except BoundedJsonError as error:
        _fail(str(error))
    _validate_adr008_illustrative_json(adr008_raw)
    data = _validate_ledger_root_identity(data)
    _validate_blueprint_binding(data["blueprint"])
    _validate_implementation_tool_bindings(data["implementation_tools"])
    _validate_defect_traceability(data["defect_traceability"])
    limits = data["limits"]
    if limits != {
        "max_file_bytes": 2_000_000,
        "max_depth": 32,
        "max_tasks": 64,
        "max_string_bytes": 4096,
        "max_evidence_references": MAX_EVIDENCE_REFERENCES,
        "max_evidence_referenced_bytes": MAX_EVIDENCE_REFERENCED_BYTES,
    }:
        _fail("$.limits differs from the enforced parser limits")
    mappings = data["perspective_mapping"]
    if (
        not isinstance(mappings, list)
        or any(not isinstance(item, dict) for item in mappings)
        or [item["id"] for item in mappings] != list(PERSPECTIVES)
    ):
        _fail("$.perspective_mapping must define P1-P3 exactly in order")
    for index, mapping in enumerate(mappings):
        _exact_keys(
            mapping,
            {"id", "name", "lens_ids", "required_question"},
            f"$.perspective_mapping[{index}]",
        )
        _string(mapping["name"], f"$.perspective_mapping[{index}].name", maximum=128)
        if not isinstance(mapping["lens_ids"], list) or not mapping["lens_ids"]:
            _fail(f"$.perspective_mapping[{index}].lens_ids must be nonempty")
        if any(lens not in LENSES for lens in mapping["lens_ids"]):
            _fail(f"$.perspective_mapping[{index}].lens_ids contains an unknown lens")
        _string(
            mapping["required_question"],
            f"$.perspective_mapping[{index}].required_question",
            maximum=1024,
        )
    lens_mapping = data["lens_mapping"]
    if (
        not isinstance(lens_mapping, list)
        or any(not isinstance(item, dict) for item in lens_mapping)
        or [item["id"] for item in lens_mapping] != list(LENSES)
    ):
        _fail("$.lens_mapping must define L1-L10 exactly in order")
    old_lenses = {f"L{number:02d}" for number in range(1, 21)}
    for index, mapping in enumerate(lens_mapping):
        _exact_keys(
            mapping,
            {"id", "name", "max_effort_lenses", "stricter_rule"},
            f"$.lens_mapping[{index}]",
        )
        _string(mapping["name"], f"$.lens_mapping[{index}].name", maximum=128)
        if (
            not isinstance(mapping["max_effort_lenses"], list)
            or not mapping["max_effort_lenses"]
        ):
            _fail(f"$.lens_mapping[{index}].max_effort_lenses must be nonempty")
        if any(lens not in old_lenses for lens in mapping["max_effort_lenses"]):
            _fail(f"$.lens_mapping[{index}] contains an unknown twenty-lens ID")
        _string(
            mapping["stricter_rule"],
            f"$.lens_mapping[{index}].stricter_rule",
            maximum=1024,
        )
    mapping_digest = hashlib.sha256(
        json.dumps(
            {
                "lens_mapping": lens_mapping,
                "perspective_mapping": mappings,
            },
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        ).encode()
    ).hexdigest()
    if mapping_digest != REVIEW_MAPPING_SHA256:
        _fail(
            "review mappings differ from the checked three-perspective and ten-lens rules"
        )
    _validate_toolchain(data["toolchain"], "$.toolchain")
    repositories = data["repositories"]
    if not isinstance(repositories, list) or not repositories:
        _fail("$.repositories must be nonempty")
    repo_names: set[str] = set()
    for index, repository in enumerate(repositories):
        path = f"$.repositories[{index}]"
        if not isinstance(repository, dict):
            _fail(f"{path} must be an object")
        _exact_keys(
            repository,
            {
                "name",
                "remote",
                "branch",
                "head",
                "tree",
                "dirty",
                "changed_paths",
                "intake_disposition",
            },
            path,
        )
        name = _string(repository["name"], f"{path}.name", maximum=64)
        if name in repo_names:
            _fail(f"{path}.name is duplicated")
        repo_names.add(name)
        _validate_authorized_github_remote(
            repository["remote"], f"{path}.remote", repository_name=name
        )
        _validate_branch_name(repository["branch"], f"{path}.branch")
        _hex(repository["head"], HEX40, f"{path}.head")
        _hex(repository["tree"], HEX40, f"{path}.tree")
        if not isinstance(repository["dirty"], bool):
            _fail(f"{path}.dirty must be boolean")
        _integer(repository["changed_paths"], f"{path}.changed_paths", minimum=0)
        if repository["dirty"] != (repository["changed_paths"] > 0):
            _fail(f"{path}.dirty disagrees with changed_paths")
        _string(
            repository["intake_disposition"], f"{path}.intake_disposition", maximum=512
        )
    if tuple(repository["name"] for repository in repositories) != REPOSITORY_NAMES:
        _fail("$.repositories differs from the checked ordered ecosystem inventory")
    repository_by_name = {repository["name"]: repository for repository in repositories}
    tasks = data["tasks"]
    if (
        not isinstance(tasks, list)
        or len(tasks) != len(TASK_CATALOG)
        or len(tasks) > limits["max_tasks"]
    ):
        _fail("$.tasks does not contain the exact bounded catalog")
    if any(not isinstance(task, dict) for task in tasks):
        _fail("$.tasks entries must be objects")
    ids = [task.get("id") for task in tasks]
    expected_ids = [task[0] for task in TASK_CATALOG]
    if ids != expected_ids or len(ids) != len(set(ids)):
        _fail("$.tasks contains duplicate, unknown, missing, or out-of-order task IDs")
    dependency_graph = {
        task_id: dependencies for task_id, _, dependencies, _ in TASK_CATALOG
    }
    _check_transitively_reduced(dependency_graph)
    catalog_repository_scopes = {repository for _, _, _, repository in TASK_CATALOG}
    if set(COORDINATION_GIT_REPOSITORY_BY_TASK_REPOSITORY) != (
        catalog_repository_scopes
    ):
        _fail("task-repository receipt policy does not cover every exact scope")
    external_tasks = {
        task_id
        for task_id, minimum in MINIMUM_TERMINAL_CLASS.items()
        if minimum == "EXTERNAL"
    }
    independent_tasks = {
        task_id
        for task_id, minimum in MINIMUM_TERMINAL_CLASS.items()
        if minimum == "INDEPENDENT"
    }
    if set(REQUIRED_EXTERNAL_GATES) != external_tasks:
        _fail("checked external-gate map does not cover every external evidence floor")
    if set(INDEPENDENT_REVIEWER_MINIMUM) != independent_tasks:
        _fail("checked reviewer map does not cover every independent evidence floor")
    evidence_budget = {"references": 0, "bytes": 0}
    for index, (task, expected) in enumerate(zip(tasks, TASK_CATALOG, strict=True)):
        _validate_task(task, expected, f"$.tasks[{index}]", budget=evidence_budget)
    _validate_legacy_portability_exception_inventory(tasks)
    task_by_id = {task["id"]: task for task in tasks}
    observed_v11_tasks = {
        task["id"] for task in tasks if "V11" in task["requirement_ids"]
    }
    if observed_v11_tasks != V11_ATLAS_TASKS:
        _fail(
            "V11 atlas ownership must cover the provider, five producer tasks, "
            "the final visual gate and exact release refreshes"
        )
    all_correlation_ids = [
        transition["correlation_id"]
        for task in tasks
        for transition in task["transitions"]
    ]
    if len(all_correlation_ids) != len(set(all_correlation_ids)):
        _fail("transition correlation IDs must be globally unique")
    for task in tasks:
        for transition in task["transitions"]:
            receipt = transition.get("receipt")
            if not isinstance(receipt, dict) or receipt.get("kind") not in {
                "start",
                "coordination",
                "passing",
            }:
                continue
            _validate_local_transition_subject(
                task,
                transition,
                receipt,
                repository_by_name,
                f"task {task['id']} transition subject",
            )
            if receipt["kind"] == "start":
                continue
            receipt_repository = _validate_receipt_repository_policy(
                task,
                receipt["repository"],
                f"task {task['id']} receipt",
            )
            repository = repository_by_name.get(receipt_repository)
            if repository is None:
                _fail(f"task {task['id']} receipt uses an unconfigured Git repository")
            if receipt["branch"] != repository["branch"]:
                _fail(
                    f"task {task['id']} receipt branch differs from the "
                    "configured repository branch"
                )
            repository_root = GIT_ROOT_BY_RECEIPT_REPOSITORY[receipt_repository]
            configured_repository = _validate_authorized_github_remote(
                repository["remote"],
                f"task {task['id']} receipt configured remote",
                repository_name=receipt_repository,
            )
            origin_repository = _authorized_origin_repository(
                repository_root,
                f"task {task['id']} configured origin",
                repository_name=receipt_repository,
            )
            if origin_repository != configured_repository:
                _fail(
                    f"task {task['id']} receipt origin differs from the "
                    "configured authorized remote"
                )
        if not task["dependencies"]:
            continue
        start = task["transitions"][0] if task["transitions"] else None
        if start is None:
            continue
        start_time = _parse_timestamp(
            start["timestamp_utc"], f"task {task['id']} start timestamp"
        )
        expected_start_bindings: list[dict[str, str]] = []
        latest_dependency_receipt_time: datetime | None = None
        for dependency_id in task["dependencies"]:
            dependency = task_by_id[dependency_id]
            state, reached, dependency_receipt = _dependency_state_before(
                dependency, start_time
            )
            if (
                state
                not in {
                    "LOCAL_PASS",
                    "EXTERNAL_PASS",
                    "INDEPENDENT_PASS",
                    "COMPLETE",
                }
                or not _reached_evidence_floor(
                    dependency["minimum_terminal_class"], reached
                )
                or dependency_receipt is None
            ):
                _fail(
                    f"task {task['id']} starts before dependency {dependency_id} "
                    "reaches its evidence class"
                )
            dependency_receipt_time = _parse_timestamp(
                dependency_receipt["timestamp_utc"],
                f"task {task['id']} dependency {dependency_id} receipt timestamp",
            )
            if (
                latest_dependency_receipt_time is None
                or dependency_receipt_time > latest_dependency_receipt_time
            ):
                latest_dependency_receipt_time = dependency_receipt_time
            expected_start_bindings.append(
                {
                    "task_id": dependency_id,
                    "receipt_sha256": _receipt_sha256(dependency_receipt),
                }
            )
        start_receipt = start["receipt"]
        if (
            not isinstance(start_receipt, dict)
            or start_receipt.get("dependency_receipts") != expected_start_bindings
        ):
            _fail(
                f"task {task['id']} start receipt does not bind the exact active "
                "dependency receipts"
            )
        start_receipt_time = _parse_timestamp(
            start_receipt["timestamp_utc"],
            f"task {task['id']} start-receipt timestamp",
        )
        if (
            latest_dependency_receipt_time is None
            or start_receipt_time <= latest_dependency_receipt_time
        ):
            _fail(
                f"task {task['id']} start receipt must be strictly later than "
                "every bound dependency receipt"
            )
    for task in tasks:
        for index, transition in enumerate(task["transitions"]):
            receipt = transition.get("receipt")
            if not isinstance(receipt, dict) or receipt.get("kind") not in {
                "start",
                "coordination",
                "passing",
            }:
                continue
            receipt_time = _parse_timestamp(
                receipt["timestamp_utc"],
                f"task {task['id']} transition {index} receipt timestamp",
            )
            resolved_dependencies = _bound_dependency_receipts_at(
                task,
                receipt["dependency_receipts"],
                receipt_time,
                task_by_id,
                f"task {task['id']} transition {index}.dependencies",
            )
            for dependency_id, dependency_receipt in resolved_dependencies.items():
                _require_dependency_receipt_precedes(
                    dependency_receipt,
                    receipt_time,
                    f"task {task['id']} bound dependency {dependency_id}",
                )
                if (
                    receipt["kind"] != "start"
                    and dependency_receipt["repository"] == receipt["repository"]
                ):
                    _require_git_ancestor_or_equal(
                        receipt["repository"],
                        dependency_receipt["source_commit"],
                        receipt["source_commit"],
                        f"task {task['id']} same-repository dependency "
                        f"{dependency_id} source cut",
                    )
    for task in tasks:
        if task["status"] in {
            "LOCAL_PASS",
            "EXTERNAL_PASS",
            "INDEPENDENT_PASS",
            "COMPLETE",
        }:
            for dependency_id in task["dependencies"]:
                dependency = task_by_id[dependency_id]
                if dependency["status"] not in {
                    "LOCAL_PASS",
                    "EXTERNAL_PASS",
                    "INDEPENDENT_PASS",
                    "COMPLETE",
                } or not _task_reached_minimum(dependency):
                    _fail(
                        f"task {task['id']} optimistically passes before dependency {dependency_id} reaches its evidence class"
                    )
            receipt = _latest_passing_receipt(task)
            assert receipt is not None
            task_receipt_time = _parse_timestamp(
                receipt["timestamp_utc"], f"task {task['id']} passing receipt timestamp"
            )
            expected_bindings = []
            for dependency_id in task["dependencies"]:
                dependency_receipt = _latest_passing_receipt(task_by_id[dependency_id])
                if dependency_receipt is None:
                    _fail(
                        f"task {task['id']} lacks passing receipt for dependency {dependency_id}"
                    )
                dependency_receipt_time = _parse_timestamp(
                    dependency_receipt["timestamp_utc"],
                    f"task {task['id']} dependency {dependency_id} current receipt timestamp",
                )
                if dependency_receipt_time >= task_receipt_time:
                    _fail(
                        f"task {task['id']} passing receipt must be strictly later "
                        f"than dependency {dependency_id} receipt"
                    )
                expected_bindings.append(
                    {
                        "task_id": dependency_id,
                        "receipt_sha256": _receipt_sha256(dependency_receipt),
                    }
                )
            if receipt["dependency_receipts"] != expected_bindings:
                _fail(
                    f"task {task['id']} passing receipt does not bind exact dependency receipts"
                )
    _validate_current_task_subjects(task_by_id)
    catalog_order = {
        task_id: index for index, (task_id, _, _, _) in enumerate(TASK_CATALOG)
    }
    children: dict[str, list[str]] = {task_id: [] for task_id in catalog_order}
    for child_id, _, dependencies, _ in TASK_CATALOG:
        for dependency_id in dependencies:
            children[dependency_id].append(child_id)

    def descendants(task_id: str) -> list[str]:
        found: set[str] = set()
        pending = list(children[task_id])
        while pending:
            child_id = pending.pop()
            if child_id in found:
                continue
            found.add(child_id)
            pending.extend(children[child_id])
        return sorted(found, key=catalog_order.__getitem__)

    def active_receipt_before(
        task: dict[str, Any], cutoff: datetime
    ) -> dict[str, Any] | None:
        active: dict[str, Any] | None = None
        state = "OPEN"
        for transition in task["transitions"]:
            transition_time = _parse_timestamp(
                transition["timestamp_utc"], "transition timestamp"
            )
            if transition_time >= cutoff:
                break
            state = transition["to"]
            if state in {"LOCAL_PASS", "EXTERNAL_PASS", "INDEPENDENT_PASS", "COMPLETE"}:
                receipt = transition["receipt"]
                active = receipt if isinstance(receipt, dict) else None
            elif state in {"IN_PROGRESS", "BLOCKED"}:
                active = None
        return (
            active
            if state in {"LOCAL_PASS", "EXTERNAL_PASS", "INDEPENDENT_PASS", "COMPLETE"}
            else None
        )

    for task in tasks:
        expected_invalidations: list[dict[str, str]] = []
        for transition in task["transitions"]:
            if (
                transition["from"]
                not in {"LOCAL_PASS", "EXTERNAL_PASS", "INDEPENDENT_PASS", "COMPLETE"}
                or transition["to"] != "IN_PROGRESS"
            ):
                continue
            reopen_time = _parse_timestamp(
                transition["timestamp_utc"], "reopen timestamp"
            )
            for descendant_id in descendants(task["id"]):
                invalidated = active_receipt_before(
                    task_by_id[descendant_id], reopen_time
                )
                if invalidated is not None:
                    expected_invalidations.append(
                        {
                            "task_id": descendant_id,
                            "receipt_sha256": _receipt_sha256(invalidated),
                            "reopen_correlation_id": transition["correlation_id"],
                        }
                    )
        if task["invalidates"] != expected_invalidations:
            _fail(
                f"task {task['id']} invalidates does not exactly bind descendant receipts invalidated by reopen"
            )
    for defect_id, task_ids in DEFECT_TRACEABILITY.items():
        for task_id in task_ids:
            if defect_id not in task_by_id[task_id]["requirement_ids"]:
                _fail(
                    f"defect {defect_id} is absent from task {task_id} requirement_ids"
                )


def load(path: Path = LEDGER) -> dict[str, Any]:
    try:
        raw = read_bounded_regular_file(
            path,
            limits=LEDGER_FILE_LIMITS,
            label="implementation ledger",
        )
        value = parse_json_bytes(
            raw,
            limits=LEDGER_JSON_LIMITS,
            label="implementation ledger",
        )
    except BoundedJsonError as error:
        _fail(str(error))
    if not isinstance(value, dict):
        _fail("ledger root must be an object")
    _walk_limits(value)
    try:
        validate_ledger_instance(value)
    except EvidenceSchemaError as error:
        _fail(str(error))
    validate(value)
    canonical = (
        json.dumps(value, indent=2, ensure_ascii=False, sort_keys=True) + "\n"
    ).encode()
    if raw != canonical:
        _fail("ledger bytes are not canonical two-space-indented UTF-8 JSON")
    return value


def _must_fail(action: Any, label: str, expected: str) -> None:
    try:
        action()
    except LedgerError as error:
        if expected not in str(error):
            _fail(
                f"self-test mutant {label} failed for the wrong reason: "
                f"expected {expected!r}, received {str(error)!r}"
            )
        return
    _fail(f"self-test mutant unexpectedly passed: {label}")


def _self_test_adr008_value(raw: bytes) -> dict[str, Any]:
    if _validate_adr008_illustrative_json(raw) < 1:
        _fail("self-test ADR-008 illustrative JSON retained no sha256 references")
    return _parse_adr008_illustrative_json(raw)


def _self_test_adr008_reference_span(
    raw: bytes,
) -> tuple[int, re.Match[bytes], int, int]:
    illustrative_offset = raw.find(b"## Illustrative extension envelope")
    if illustrative_offset < 0:
        _fail("self-test ADR-008 source has no illustrative heading")
    first_reference = re.search(rb"sha256:[0-9a-f]{64}", raw[illustrative_offset:])
    if first_reference is None:
        _fail("self-test ADR-008 illustrative JSON has no sha256 reference")
    reference_start, reference_end = (
        illustrative_offset + position for position in first_reference.span()
    )
    return illustrative_offset, first_reference, reference_start, reference_end


def _self_test_git_environment_filter() -> None:
    prior_git_parameters = os.environ.get("GIT_CONFIG_PARAMETERS")
    os.environ["GIT_CONFIG_PARAMETERS"] = "'core.replaceRefs=true'"
    try:
        if "GIT_CONFIG_PARAMETERS" in _git_environment():
            _fail("self-test git environment retained injected config parameters")
    finally:
        if prior_git_parameters is None:
            os.environ.pop("GIT_CONFIG_PARAMETERS", None)
        else:
            os.environ["GIT_CONFIG_PARAMETERS"] = prior_git_parameters


def _self_test_authorized_origin_line_boundary(
    authorized_remotes: tuple[str, ...],
) -> None:
    with tempfile.TemporaryDirectory(prefix="ncp-origin-line-boundary-") as temporary:
        repository_index = 0

        def repository_with_origin(*remotes: str) -> Path:
            nonlocal repository_index
            repository_index += 1
            repository = Path(temporary) / f"repository-{repository_index}"
            repository.mkdir()
            _self_test_git(repository, "init", "-b", "main")
            for remote in remotes:
                _self_test_git(
                    repository,
                    "config",
                    "--add",
                    "remote.origin.url",
                    remote,
                )
            return repository

        for remote in authorized_remotes:
            repository = repository_with_origin(remote)
            observed = _authorized_origin_repository(
                repository,
                "self-test exact configured origin",
                repository_name="NCP",
            )
            if observed != "sepahead/NCP":
                _fail("self-test exact configured origin changed repository identity")
        for label, remote in (
            ("leading space", " https://github.com/sepahead/NCP"),
            ("trailing space", "https://github.com/sepahead/NCP "),
            ("trailing tab", "https://github.com/sepahead/NCP\t"),
            ("trailing carriage return", "https://github.com/sepahead/NCP\r"),
        ):
            repository = repository_with_origin(remote)
            _must_fail(
                lambda: _authorized_origin_repository(
                    repository,
                    "hostile whitespace configured origin",
                    repository_name="NCP",
                ),
                f"configured origin with {label}",
                "one exact",
            )

        for label, remotes in (
            (
                "duplicate authorized fetch URLs",
                (
                    "git@github.com:sepahead/NCP.git",
                    "https://github.com/sepahead/NCP",
                ),
            ),
            (
                "authorized then hostile fetch URLs",
                (
                    "git@github.com:sepahead/NCP.git",
                    "https://github.com/attacker/NCP",
                ),
            ),
        ):
            repository = repository_with_origin(*remotes)
            _must_fail(
                lambda: _authorized_origin_repository(
                    repository,
                    "ambiguous configured origin",
                    repository_name="NCP",
                ),
                label,
                "one exact",
            )

        repository = repository_with_origin("git@github.com:sepahead/NCP.git")
        _self_test_git(
            repository,
            "config",
            "--add",
            "remote.origin.pushurl",
            "https://github.com/sepahead/NCP",
        )
        if (
            _authorized_origin_repository(
                repository,
                "authorized separate push origin",
                repository_name="NCP",
            )
            != "sepahead/NCP"
        ):
            _fail("self-test authorized separate push origin changed identity")

        repository = repository_with_origin("git@github.com:sepahead/NCP.git")
        for push_url in (
            "https://github.com/sepahead/NCP",
            "https://github.com/attacker/NCP",
        ):
            _self_test_git(
                repository,
                "config",
                "--add",
                "remote.origin.pushurl",
                push_url,
            )
        _must_fail(
            lambda: _authorized_origin_repository(
                repository,
                "ambiguous push origin",
                repository_name="NCP",
            ),
            "authorized then hostile push URLs",
            "one exact",
        )

        repository = repository_with_origin("git@github.com:sepahead/NCP.git")
        _self_test_git(
            repository,
            "config",
            "remote.origin.pushurl",
            "https://github.com/attacker/NCP",
        )
        _must_fail(
            lambda: _authorized_origin_repository(
                repository,
                "hostile push origin",
                repository_name="NCP",
            ),
            "hostile single push URL",
            "authorized GitHub",
        )

        for rewrite_kind in ("insteadOf", "pushInsteadOf"):
            repository = repository_with_origin("https://github.com/sepahead/NCP")
            _self_test_git(
                repository,
                "config",
                f"url.https://github.com/attacker/NCP.{rewrite_kind}",
                "https://github.com/sepahead/NCP",
            )
            _must_fail(
                lambda: _authorized_origin_repository(
                    repository,
                    f"hostile {rewrite_kind} origin",
                    repository_name="NCP",
                ),
                f"hostile {rewrite_kind} rewrite",
                "authorized GitHub",
            )


def _self_test_current_generation_evidence_reset(task: dict[str, Any]) -> None:
    if _task_reached_minimum(task):
        _fail(
            "self-test current-generation evidence reset unexpectedly retained "
            "an old external pass"
        )


def _self_test_b03_allocation_coverage_mutants(
    allocation_keys: set[tuple[str, str]],
) -> None:
    for missing_kind in sorted(B03_REQUIRED_ALLOCATION_KINDS):
        _must_fail(
            lambda missing_kind=missing_kind: _validate_b03_allocation_coverage(
                {key for key in allocation_keys if key[0] != missing_kind}
            ),
            f"B03 missing required allocation kind {missing_kind}",
            "required bounded allocation kinds",
        )
    for missing_identifier in sorted(B03_REQUIRED_ALLOCATION_IDENTIFIERS):
        _must_fail(
            lambda missing_identifier=missing_identifier: (
                _validate_b03_allocation_coverage(
                    allocation_keys - {missing_identifier}
                )
            ),
            f"B03 missing required allocation identifier {missing_identifier}",
            "required closed allocation identifiers",
        )
    _must_fail(
        lambda: _validate_b03_allocation_coverage(
            allocation_keys
            | {
                (
                    "observer-grant-reattachment-policy-result",
                    "REATTACH_REQUIRES_NEW_GRANT_KEY",
                )
            }
        ),
        "B03 forbidden reattachment-result alias",
        "must equal ['REATTACH_ALLOWED', 'REATTACH_FORBIDDEN'] exactly",
    )


def _self_test_b03_constraint_removal_mutants(
    constraints: list[dict[str, Any]],
    allocation_keys: set[tuple[str, str]],
) -> None:
    for constraint_index, key in enumerate(sorted(B03_REQUIRED_ALLOCATION_CONSTRAINTS)):
        for removed_invariant in sorted(B03_REQUIRED_ALLOCATION_CONSTRAINTS[key]):
            hostile_constraints = copy.deepcopy(constraints)
            hostile_constraints[constraint_index]["required_invariants"].remove(
                removed_invariant
            )
            _must_fail(
                lambda hostile_constraints=hostile_constraints: (
                    _validate_b03_allocation_constraints(
                        hostile_constraints, allocation_keys
                    )
                ),
                (
                    "B03 weakened exact allocation constraint set for "
                    f"{key}: {removed_invariant}"
                ),
                "fail-closed/current-head invariant set",
            )


def _self_test_b03_codeowners_parser_mutants() -> None:
    for hostile_codeowners, label, expected_error in (
        (b"!/contract/ @attacker\n", "negation", "unsupported"),
        (b"\\#forged @attacker\n", "escaping", "ambiguous inline #"),
        (b"contract/[ab].json @attacker\n", "range", "unsupported"),
    ):
        _must_fail(
            lambda hostile_codeowners=hostile_codeowners: _parse_b03_codeowners(
                hostile_codeowners, "B03 hostile CODEOWNERS"
            ),
            f"B03 CODEOWNERS unsupported {label}",
            expected_error,
        )


def _self_test_b03_codeowners_semantics(
    rules: list[tuple[str, tuple[str, ...]]],
) -> None:
    actual = (
        _b03_effective_codeowners(rules, "contract/surface.v1.json"),
        _b03_effective_codeowners(rules, "docs/one-level.md"),
        _b03_effective_codeowners(rules, "docs/nested/two-level.md"),
        _b03_effective_codeowners(rules, ".github/CODEOWNERS"),
    )
    expected = (
        ("@contract-owner", "@second-owner"),
        ("@docs-owner",),
        ("@global-owner",),
        ("@global-owner",),
    )
    if actual != expected:
        _fail("self-test CODEOWNERS safe-subset last-match semantics are incorrect")


def _self_test_git(
    repository: Path,
    *arguments: str,
    input_bytes: bytes | None = None,
) -> str:
    if GIT is None:
        _fail("self-test requires git")
    result = subprocess.run(  # noqa: S603
        [GIT, "--no-replace-objects", *arguments],
        cwd=repository,
        env=_git_environment(),
        input=input_bytes,
        check=False,
        capture_output=True,
        timeout=10,
    )
    if result.returncode != 0:
        detail = result.stderr.decode("utf-8", errors="replace").strip()
        _fail(f"self-test git {' '.join(arguments)} failed: {detail}")
    return result.stdout.decode("utf-8").strip()


def _self_test_write_json(path: Path, value: Any) -> bytes:
    encoded = (
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        + "\n"
    ).encode()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(encoded)
    return encoded


def _self_test_commit(repository: Path, message: str) -> tuple[str, str]:
    _self_test_git(repository, "add", "-A")
    _self_test_git(repository, "commit", "-m", message)
    commit = _self_test_git(repository, "rev-parse", "HEAD")
    tree = _self_test_git(repository, "rev-parse", "HEAD^{tree}")
    return commit, tree


