    def png_chunk(chunk_type: bytes, content: bytes) -> bytes:
        return (
            len(content).to_bytes(4, "big")
            + chunk_type
            + content
            + (zlib.crc32(chunk_type + content) & 0xFFFFFFFF).to_bytes(4, "big")
        )

    def png(metadata: bytes = b"") -> bytes:
        ihdr = (1).to_bytes(4, "big") + (1).to_bytes(4, "big") + bytes((8, 2, 0, 0, 0))
        return (
            PNG_SIGNATURE
            + png_chunk(b"IHDR", ihdr)
            + metadata
            + png_chunk(b"IDAT", zlib.compress(b"\x00\x00\x00\x00"))
            + png_chunk(b"IEND", b"")
        )

